def application_secret() -> str:
    configured = (os.environ.get("FAIRFARES_APP_SECRET") or os.environ.get("SECRET_KEY") or "").strip()
    if len(configured) >= 32:
        return configured
    secret_path = DB_PATH.parent / ".fairfares-app-secret"
    secret_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        existing = secret_path.read_text(encoding="utf-8").strip()
        if len(existing) >= 32:
            return existing
    except FileNotFoundError:
        pass
    generated = secrets.token_urlsafe(48)
    try:
        with secret_path.open("x", encoding="utf-8") as handle:
            handle.write(generated)
        secret_path.chmod(0o600)
        return generated
    except FileExistsError:
        existing = secret_path.read_text(encoding="utf-8").strip()
        if len(existing) >= 32:
            return existing
    raise RuntimeError("FairFares application secret could not be initialized securely.")


def normalize_email(value: object) -> str:
    return re.sub(r"\s+", "", str(value or "")).lower()


def normalize_phone(value: object) -> str:
    return re.sub(r"\D+", "", str(value or ""))


def canonical_e164_phone(value: object, country_code: object = "") -> str:
    raw_phone = str(value or "").strip()
    phone_digits = normalize_phone(raw_phone)
    if raw_phone.startswith("+"):
        candidate = f"+{phone_digits}"
    else:
        calling_digits = normalize_phone(country_code)
        national_digits = phone_digits.lstrip("0")
        candidate = f"+{calling_digits}{national_digits}" if calling_digits else ""
    return candidate if re.fullmatch(r"\+[1-9]\d{7,14}", candidate) else ""


def auth_token_hash(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def jwt_json_part(value: str) -> dict[str, object]:
    padded = value + "=" * (-len(value) % 4)
    decoded = base64.urlsafe_b64decode(padded.encode("ascii"))
    result = json.loads(decoded.decode("utf-8"))
    if not isinstance(result, dict):
        raise ValueError("Invalid identity token payload.")
    return result


def configured_google_client_ids() -> set[str]:
    values: list[str] = []
    for env_name in ("GOOGLE_OAUTH_CLIENT_IDS", "GOOGLE_IOS_CLIENT_ID", "GOOGLE_ANDROID_CLIENT_ID", "GOOGLE_WEB_CLIENT_ID"):
        values.extend(re.split(r"[\s,]+", os.environ.get(env_name, "").strip()))
    return {value for value in values if value}


def configured_apple_client_ids() -> set[str]:
    # FairFares has both an Expo native app and the older Capacitor shell.
    # Keep those owned bundle IDs valid even when a deployment still carries a
    # stale APPLE_SIGN_IN_CLIENT_IDS override from one of the two builds.
    allowed = {"com.fairfares.mobile", "com.fairfares.app"}
    allowed.update(
        value
        for value in re.split(r"[\s,]+", os.environ.get("APPLE_SIGN_IN_CLIENT_IDS", "").strip())
        if value
    )
    return allowed


def verify_google_identity_token(identity_token: str) -> dict[str, object]:
    client_ids = configured_google_client_ids()
    if not client_ids:
        raise RuntimeError("Google sign-in is not configured.")
    try:
        from google.auth.transport.requests import Request
        from google.oauth2 import id_token
        claims = id_token.verify_oauth2_token(identity_token, Request())
    except Exception as exc:
        raise ValueError("Google could not verify this sign-in.") from exc
    if str(claims.get("aud") or "") not in client_ids:
        raise ValueError("Google sign-in was issued for another app.")
    if str(claims.get("iss") or "") not in {"accounts.google.com", "https://accounts.google.com"}:
        raise ValueError("Google sign-in issuer is invalid.")
    if claims.get("email_verified") not in {True, "true", "True", 1}:
        raise ValueError("Google email is not verified.")
    return claims


def verify_apple_identity_token(identity_token: str) -> dict[str, object]:
    if rsa is None or padding is None or hashes is None:
        raise RuntimeError("Apple sign-in verification dependencies are unavailable.")
    pieces = identity_token.split(".")
    if len(pieces) != 3:
        raise ValueError("Apple identity token is invalid.")
    header = jwt_json_part(pieces[0])
    claims = jwt_json_part(pieces[1])
    if header.get("alg") != "RS256" or not header.get("kid"):
        raise ValueError("Apple identity token algorithm is invalid.")
    try:
        with urllib.request.urlopen("https://appleid.apple.com/auth/keys", timeout=10) as response:
            key_set = json.loads(response.read().decode("utf-8"))
        jwk = next(key for key in key_set.get("keys", []) if key.get("kid") == header.get("kid"))
        modulus = int.from_bytes(base64.urlsafe_b64decode(str(jwk["n"]) + "=" * (-len(str(jwk["n"])) % 4)), "big")
        exponent = int.from_bytes(base64.urlsafe_b64decode(str(jwk["e"]) + "=" * (-len(str(jwk["e"])) % 4)), "big")
        public_key = rsa.RSAPublicNumbers(exponent, modulus).public_key()
        signature = base64.urlsafe_b64decode(pieces[2] + "=" * (-len(pieces[2]) % 4))
        public_key.verify(signature, f"{pieces[0]}.{pieces[1]}".encode("ascii"), padding.PKCS1v15(), hashes.SHA256())
    except (InvalidSignature, KeyError, StopIteration, ValueError, urllib.error.URLError) as exc:
        raise ValueError("Apple could not verify this sign-in.") from exc
    allowed = configured_apple_client_ids()
    audience = clean_text_value(claims.get("aud"), 200)
    if claims.get("iss") != "https://appleid.apple.com":
        raise ValueError("Apple sign-in issuer is invalid.")
    if audience not in allowed:
        print(json.dumps({
            "event": "apple_signin_audience_mismatch",
            "audience": audience or "missing",
            "allowed_audiences": sorted(allowed),
        }, separators=(",", ":")), flush=True)
        raise ValueError(
            f"Apple sign-in audience '{audience or 'missing'}' is not configured for this FairFares app."
        )
    if int(claims.get("exp") or 0) <= int(time.time()):
        raise ValueError("Apple sign-in has expired.")
    if claims.get("email_verified") not in {True, "true", "True", 1, None}:
        raise ValueError("Apple email is not verified.")
    return claims


def twilio_verify_request(path: str, values: dict[str, str]) -> dict[str, object]:
    account_sid = os.environ.get("TWILIO_ACCOUNT_SID", "").strip()
    auth_token = os.environ.get("TWILIO_AUTH_TOKEN", "").strip()
    service_sid = os.environ.get("TWILIO_VERIFY_SERVICE_SID", "").strip()
    if not account_sid or not auth_token or not service_sid:
        raise RuntimeError("Phone verification is not configured.")
    url = f"https://verify.twilio.com/v2/Services/{urllib.parse.quote(service_sid)}/{path}"
    auth = base64.b64encode(f"{account_sid}:{auth_token}".encode("utf-8")).decode("ascii")
    request = urllib.request.Request(
        url,
        data=urllib.parse.urlencode(values).encode("utf-8"),
        headers={"Authorization": f"Basic {auth}", "Content-Type": "application/x-www-form-urlencoded"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            result = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            detail = json.loads(exc.read().decode("utf-8")).get("message")
        except Exception:
            detail = "Phone verification provider rejected the request."
        raise ValueError(str(detail)) from exc
    except urllib.error.URLError as exc:
        raise RuntimeError("Phone verification is temporarily unavailable.") from exc
    return result if isinstance(result, dict) else {}


def normalized_email_sql(column: str = "email") -> str:
    return f"LOWER(REPLACE(REPLACE(REPLACE(REPLACE({column}, ' ', ''), char(9), ''), char(10), ''), char(13), ''))"


def normalized_phone_sql(column: str = "phone") -> str:
    return (
        "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE("
        f"{column}, ' ', ''), char(9), ''), char(10), ''), char(13), ''), '-', ''), '(', ''), ')', ''), '+', ''), '.', '')"
    )


def find_user_by_email(con: sqlite3.Connection, email: object) -> sqlite3.Row | None:
    clean_email = normalize_email(email)
    if not clean_email:
        return None
    user = con.execute("SELECT * FROM users WHERE LOWER(email) = ? LIMIT 1", (clean_email,)).fetchone()
    if user:
        return user
    return con.execute(
        f"SELECT * FROM users WHERE {normalized_email_sql('email')} = ? LIMIT 1",
        (clean_email,),
    ).fetchone()


def find_user_by_login_identifier(con: sqlite3.Connection, identifier: object) -> sqlite3.Row | None:
    value = str(identifier or "").strip()
    if not value:
        return None
    if "@" in value:
        return find_user_by_email(con, value)
    target_phone = normalize_phone(value)
    if not target_phone:
        return None
    rows = con.execute("SELECT * FROM users WHERE phone IS NOT NULL AND phone != '' ORDER BY id DESC").fetchall()
    for row in rows:
        if normalize_phone(row_value(row, "phone")) == target_phone:
            return row
    return None


def log_login_failure(email: str, reason: str) -> None:
    safe_email = normalize_email(email)
    print(f"Login failed: {reason} for {safe_email or 'blank-email'}")


def ensure_column(con: sqlite3.Connection, table: str, column: str, definition: str) -> None:
    columns = {row["name"] for row in con.execute(f"PRAGMA table_info({table})")}
    if column not in columns:
        con.execute(f"ALTER TABLE {table} ADD COLUMN {definition}")


def configured_admin_credentials() -> tuple[str, str]:
    email = normalize_email(os.environ.get("FAIRFARES_ADMIN_EMAIL", ""))
    password = os.environ.get("FAIRFARES_ADMIN_PASSWORD", "")
    return email, password


def configured_email_set(env_name: str, default_value: str = "") -> set[str]:
    raw_value = os.environ.get(env_name, default_value)
    return {normalize_email(email) for email in raw_value.split(",") if normalize_email(email)}


def normalized_user_role(value: object) -> str:
    role = str(value or "").strip().upper()
    return role if role in VALID_USER_ROLES else ROLE_CUSTOMER


def user_role_flags(role: str) -> tuple[int, str]:
    normalized = normalized_user_role(role)
    return (1 if normalized == ROLE_ADMIN else 0, normalized)


def ensure_admin_account(con: sqlite3.Connection, email: str, password: str) -> None:
    email = normalize_email(email)
    if not email or not password:
        return
    admin = find_user_by_email(con, email)
    password_hash = hash_password(password)
    if not admin:
        con.execute(
            """
            INSERT INTO users
            (name, email, password_hash, is_admin, role, is_verified, verified_at)
            VALUES (?, ?, ?, 1, 'ADMIN', 1, CURRENT_TIMESTAMP)
            """,
            ("FairFares Admin", email, password_hash),
        )
        return
    if not verify_password(password, admin["password_hash"]):
        con.execute(
            """
            UPDATE users
            SET name = COALESCE(NULLIF(name, ''), 'FairFares Admin'),
                password_hash = ?,
                is_admin = 1,
                role = 'ADMIN',
                is_verified = 1,
                verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP),
                guest_account = 0
            WHERE id = ?
            """,
            (password_hash, admin["id"]),
        )
    else:
        con.execute(
            """
            UPDATE users
            SET is_admin = 1,
                role = 'ADMIN',
                is_verified = 1,
                verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP),
                guest_account = 0
            WHERE id = ?
            """,
            (admin["id"],),
        )


def cleanup_expired_sessions(con: sqlite3.Connection) -> None:
    idle_cutoff = f"-{SESSION_IDLE_TIMEOUT_DAYS} days"
    absolute_cutoff = f"-{SESSION_ABSOLUTE_TIMEOUT_DAYS} days"
    con.execute(
        """
        DELETE FROM sessions
        WHERE datetime(created_at) < datetime('now', ?)
           OR datetime(COALESCE(NULLIF(last_seen_at, ''), created_at)) < datetime('now', ?)
        """,
        (absolute_cutoff, idle_cutoff),
    )


def repair_normalized_auth_emails(con: sqlite3.Connection) -> None:
    for row in con.execute("SELECT id, email FROM users").fetchall():
        clean_email = normalize_email(row["email"])
        if not clean_email or clean_email == row["email"]:
            continue
        conflict = con.execute(
            "SELECT id FROM users WHERE LOWER(email) = ? AND id != ? LIMIT 1",
            (clean_email, row["id"]),
        ).fetchone()
        if not conflict:
            con.execute("UPDATE users SET email = ? WHERE id = ?", (clean_email, row["id"]))
    for row in con.execute("SELECT id, email FROM staff_account_requests").fetchall():
        clean_email = normalize_email(row["email"])
        if clean_email and clean_email != row["email"]:
            con.execute("UPDATE staff_account_requests SET email = ? WHERE id = ?", (clean_email, row["id"]))


def ensure_default_admin(con: sqlite3.Connection) -> None:
    legacy_admin = find_user_by_email(con, DEFAULT_ADMIN_EMAIL)
    legacy_password = "ChangeMe" + "123!"
    if legacy_admin and verify_password(legacy_password, row_value(legacy_admin, "password_hash")):
        # Invalidate repository-known credentials from older deployments while
        # preserving the account for the verified password-reset flow.
        con.execute(
            "UPDATE users SET password_hash = ? WHERE id = ?",
            (hash_password(secrets.token_urlsafe(48)), int(legacy_admin["id"])),
        )
    configured_email, configured_password = configured_admin_credentials()
    if configured_email and configured_password:
        ensure_admin_account(con, configured_email, configured_password)


def normalize_user_roles(con: sqlite3.Connection) -> None:
    con.execute(
        """
        UPDATE users
        SET role = 'ADMIN',
            is_admin = 1
        WHERE is_admin = 1 OR UPPER(TRIM(role)) = 'ADMIN'
        """
    )
    con.execute(
        """
        UPDATE users
        SET role = 'EMPLOYEE',
            is_admin = 0
        WHERE UPPER(TRIM(role)) = 'EMPLOYEE'
        """
    )
    con.execute(
        """
        UPDATE users
        SET role = 'CUSTOMER',
            is_admin = 0
        WHERE UPPER(TRIM(role)) NOT IN ('ADMIN', 'EMPLOYEE', 'CUSTOMER')
           OR role IS NULL
           OR TRIM(role) = ''
        """
    )
    con.execute(
        """
        UPDATE users
        SET is_admin = 0
        WHERE role = 'CUSTOMER'
        """
    )


def apply_staff_role_overrides(con: sqlite3.Connection) -> None:
    promoted_admins = configured_email_set("FAIRFARES_PROMOTED_ADMIN_EMAILS", DEFAULT_PROMOTED_ADMIN_EMAILS)
    revoked_admins = configured_email_set("FAIRFARES_REVOKED_ADMIN_EMAILS", DEFAULT_REVOKED_ADMIN_EMAILS)
    for email in revoked_admins:
        con.execute(
            """
            UPDATE users
            SET is_admin = 0,
                role = 'CUSTOMER'
            WHERE lower(email) = ?
            """,
            (email,),
        )
    for email in promoted_admins - revoked_admins:
        con.execute(
            """
            UPDATE users
            SET is_admin = 1,
                role = 'ADMIN',
                is_verified = 1,
                verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP),
                guest_account = 0
            WHERE lower(email) = ?
            """,
            (email,),
        )


def create_verification(user_id: int, email: str, purpose: str = "ACCOUNT") -> str:
    token = secrets.token_urlsafe(32)
    with db() as con:
        con.execute(
            "INSERT INTO email_verifications (token, user_id, email, purpose) VALUES (?, ?, ?, ?)",
            (token, user_id, email, purpose),
        )
    return token


def send_with_resend(email: str, subject: str, text_body: str, html_body: str) -> str:
    api_key = os.environ.get("RESEND_API_KEY")
    if not api_key:
        return "not configured"

    payload = json.dumps(
        {
            "from": os.environ.get("RESEND_FROM", "FairFares <onboarding@resend.dev>"),
            "to": [email],
            "subject": subject,
            "text": text_body,
            "html": html_body,
        }
    ).encode("utf-8")
    request = urllib.request.Request(
        "https://api.resend.com/emails",
        data=payload,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "User-Agent": "fairfares-local/1.0",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=12) as response:
            return f"sent through Resend ({response.status})" if 200 <= response.status < 300 else f"Resend returned {response.status}"
    except urllib.error.HTTPError as error:
        detail = error.read().decode("utf-8", errors="replace").strip()
        return f"Resend rejected the email ({error.code}): {detail}"
    except (OSError, TimeoutError, urllib.error.URLError) as error:
        return f"Resend request failed: {error}"


def email_delivery_succeeded(status: str) -> bool:
    normalized = (status or "").lower()
    return normalized.startswith("sent through ") or "test capture" in normalized


