def send_accommodation_message_email(
    email: str,
    recipient_name: str,
    sender_name: str,
    post_title: str,
    message_text: str,
    conversation_url: str,
) -> tuple[Path, str]:
    load_env_file()
    OUTBOX_DIR.mkdir(parents=True, exist_ok=True)
