def get_mobile_housing_testimonials(city: str = "", limit: int = 6) -> list[dict[str, object]]:
    city_name = (city or "").split(",", 1)[0].strip()
    with db() as con:
        rows = con.execute(
            """
            SELECT testimonials.id, testimonials.rating, testimonials.message, testimonials.city,
                   users.name AS user_name, users.profile_photo_url
            FROM testimonials
            JOIN users ON users.id = testimonials.user_id
            WHERE testimonials.status = 'PUBLISHED'
              AND testimonials.rating BETWEEN 4 AND 5
              AND LENGTH(TRIM(testimonials.message)) >= 8
            ORDER BY CASE
                       WHEN ? != '' AND testimonials.city LIKE ? COLLATE NOCASE THEN 0
                       ELSE 1
                     END,
                     COALESCE(testimonials.published_at, testimonials.created_at) DESC,
                     testimonials.id DESC
            LIMIT ?
            """,
            (city_name, f"{city_name}%", max(1, min(int(limit), 12))),
        ).fetchall()
    testimonials: list[dict[str, object]] = []
    for row in rows:
        testimonials.append(
            {
                "id": int(row_value(row, "id") or 0),
                "name": str(row_value(row, "user_name") or "FairFares member"),
                "city": str(row_value(row, "city") or "FairFares community")[:80],
                "photoUrl": str(row_value(row, "profile_photo_url") or ""),
                "rating": int(row_value(row, "rating") or 5),
                "message": str(row_value(row, "message") or "")[:300],
            }
        )
    return testimonials


def has_submitted_housing_experience(user_id: int) -> bool:
    if user_id <= 0:
        return False
    with db() as con:
        return bool(
            con.execute(
                """
                SELECT 1
                FROM app_feedback
                WHERE user_id = ? AND page = 'mobile-housing-city-experience'
                LIMIT 1
                """,
                (user_id,),
            ).fetchone()
        )


def get_exports_imports_interest_summary() -> dict[str, int]:
    with db() as con:
        row = con.execute(
            """
            SELECT
                COUNT(*) AS total,
                COUNT(DISTINCT CASE WHEN user_id IS NOT NULL THEN user_id END) AS signed_in_users,
                SUM(CASE WHEN user_id IS NULL THEN 1 ELSE 0 END) AS guest_submissions,
                SUM(CASE WHEN created_at >= datetime('now', '-7 days') THEN 1 ELSE 0 END) AS last_7_days
            FROM app_feedback
            WHERE page = 'mobile-home-exports-imports'
            """
        ).fetchone()
    return {
        "total": int(row_value(row, "total", 0) or 0),
        "signed_in_users": int(row_value(row, "signed_in_users", 0) or 0),
        "guest_submissions": int(row_value(row, "guest_submissions", 0) or 0),
        "last_7_days": int(row_value(row, "last_7_days", 0) or 0),
    }


def assistant_user_role(user: sqlite3.Row | None) -> str:
    if not user:
        return "guest"
    if is_staff_user(user):
        return "admin"
    return "user"


MONTH_NAME_TO_NUMBER = {
    "jan": 1,
    "january": 1,
    "feb": 2,
    "february": 2,
    "mar": 3,
    "march": 3,
    "apr": 4,
    "april": 4,
    "may": 5,
    "jun": 6,
    "june": 6,
    "jul": 7,
    "july": 7,
    "aug": 8,
    "august": 8,
    "sep": 9,
    "sept": 9,
    "september": 9,
    "oct": 10,
    "october": 10,
    "nov": 11,
    "november": 11,
    "dec": 12,
    "december": 12,
}


def assistant_time_match(value: str) -> re.Match[str] | None:
    match = re.search(r"\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)\b", value, re.I)
    if match:
        return match
    return re.search(r"\b(\d{1,2})(?::(\d{2}))\b", value)


def assistant_parse_time(value: str, default: str = "10:00 AM") -> str:
    match = re.search(r"\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)\b", value, re.I)
    if not match:
        match = re.search(r"\b(\d{1,2})(?::(\d{2}))\b", value)
        if not match:
            return default
        hour = int(match.group(1))
        minute = int(match.group(2))
        if hour > 23 or minute > 59:
            return default
        return datetime.strptime(f"{hour:02d}:{minute:02d}", "%H:%M").strftime("%I:%M %p").lstrip("0")
    hour = int(match.group(1))
    minute = int(match.group(2) or "0")
    period = match.group(3).lower().replace(".", "")
    if hour < 1 or hour > 12 or minute > 59:
        return default
    if period == "pm" and hour != 12:
        hour += 12
    if period == "am" and hour == 12:
        hour = 0
    return datetime.strptime(f"{hour:02d}:{minute:02d}", "%H:%M").strftime("%I:%M %p").lstrip("0")


def assistant_parse_date_mentions(question: str) -> list[date]:
    today = date.today()
    mentions: list[tuple[int, date]] = []
    for match in re.finditer(
        r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,\s*(\d{4}))?",
        question,
        re.I,
    ):
        month = MONTH_NAME_TO_NUMBER.get(match.group(1).lower())
        day = int(match.group(2))
        year = int(match.group(3) or today.year)
        if month:
            try:
                parsed = date(year, month, day)
                if not match.group(3) and parsed < today:
                    parsed = date(year + 1, month, day)
                mentions.append((match.start(), parsed))
            except ValueError:
                continue
    for match in re.finditer(r"\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b", question):
        month = int(match.group(1))
        day = int(match.group(2))
        year_raw = match.group(3)
        year = today.year
        if year_raw:
            year = int(year_raw)
            if year < 100:
                year += 2000
        try:
            parsed = date(year, month, day)
            if not year_raw and parsed < today:
                parsed = date(year + 1, month, day)
            mentions.append((match.start(), parsed))
        except ValueError:
            continue
    ordered: list[date] = []
    seen: set[str] = set()
    for _position, parsed in sorted(mentions, key=lambda item: item[0]):
        key = parsed.isoformat()
        if key not in seen:
            ordered.append(parsed)
            seen.add(key)
    return ordered


def assistant_detect_car_type(question: str) -> str:
    lower = question.lower()
    if re.search(r"\b(suv|crossover)\b", lower):
        return "SUV"
    if re.search(r"\b(sedan)\b", lower):
        return "Sedan"
    if re.search(r"\b(minivan|van|voyager|pacifica)\b", lower):
        return "Van"
    if re.search(r"\b(electric|ev|bolt)\b", lower):
        return "Electric"
    if re.search(r"\b(hybrid)\b", lower):
        return "Hybrid"
    return ""


def assistant_detect_location(question: str) -> str:
    lower = question.lower()
    locations = get_inventory_locations()
    if "airport" in lower or "den" in lower:
        for location in locations:
            normalized = normalize_location_label(location)
            if "airport" in normalized or normalized == "den":
                return location
    for location in locations:
        normalized = normalize_location_label(location)
        if normalized and normalized in normalize_location_label(question):
            return location
    return ""


def assistant_booking_search_request(question: str) -> dict[str, object] | None:
    lower = question.lower()
    if not any(term in lower for term in ("book", "available", "availability", "cheapest", "cheap", "car", "cars", "suv", "sedan", "pickup", "return")):
        return None
    date_mentions = assistant_parse_date_mentions(question)
    if not date_mentions:
        return None
    pickup_date = date_mentions[0]
    return_date = date_mentions[1] if len(date_mentions) > 1 else None
    pickup_segment = question
    return_segment = ""
    return_match = re.search(r"\b(return|drop[\s-]?off|to)\b", question, re.I)
    if return_match:
        pickup_segment = question[:return_match.start()]
        return_segment = question[return_match.start():]
    pickup_time = assistant_parse_time(pickup_segment, "") if assistant_time_match(pickup_segment) else ""
    return_time = assistant_parse_time(return_segment, "") if return_segment and assistant_time_match(return_segment) else ""
    pickup_location = assistant_detect_location(question)
    missing_fields: list[str] = []
    if not pickup_time:
        missing_fields.append("pickup time")
    if return_date is None:
        missing_fields.append("return date")
    if not return_time:
        missing_fields.append("return time")
    if missing_fields:
        return {
            "pickup_date": pickup_date.isoformat(),
            "return_date": return_date.isoformat() if return_date else "",
            "pickup_time": pickup_time,
            "return_time": return_time,
            "days": "",
            "car_type": assistant_detect_car_type(question),
            "pickup_location": pickup_location,
            "return_location": pickup_location,
            "missing_fields": missing_fields,
        }
    try:
        normalized = normalize_booking_window(
            3,
            pickup_date.isoformat(),
            return_date.isoformat(),
            pickup_time,
            return_time,
            strict=True,
        )
    except ValueError:
        return None
    pickup_iso, return_iso, pickup_time, return_time, days, _start, _end = normalized
    return {
        "pickup_date": pickup_iso,
        "return_date": return_iso,
        "pickup_time": pickup_time,
        "return_time": return_time,
        "days": days,
        "car_type": assistant_detect_car_type(question),
        "pickup_location": pickup_location,
        "return_location": pickup_location,
    }


def assistant_car_checkout_url(car_id: object, request: dict[str, object] | None = None) -> str:
    params = {"car_id": str(car_id)}
    if request:
        for key in ("days", "pickup_date", "return_date", "pickup_time", "return_time", "pickup_location", "return_location"):
            value = request.get(key)
            if value:
                params[key] = str(value)
    return f"/manage-booking?{urllib.parse.urlencode(params)}"


def assistant_car_matches_request(car: sqlite3.Row, request: dict[str, object] | None) -> bool:
    if not request:
        return True
    desired_type = str(request.get("car_type") or "").casefold()
    if desired_type:
        haystack = " ".join(
            str(row_value(car, key) or "")
            for key in ("name", "category", "type", "fuel_type")
        ).casefold()
        if desired_type == "van":
            if "van" not in haystack and "minivan" not in haystack:
                return False
        elif desired_type not in haystack:
            return False
    requested_location = str(request.get("pickup_location") or "")
    if requested_location:
        requested_key = normalize_location_label(requested_location)
        location_keys = [normalize_location_label(location) for location in split_inventory_locations(row_value(car, "location"))]
        if requested_key and requested_key not in location_keys:
            return False
    return True


def assistant_car_context(limit: int = 5, request: dict[str, object] | None = None) -> list[dict[str, object]]:
    if request and request.get("missing_fields"):
        return []
    cars = [
        car for car in get_cars()
        if str(row_value(car, "status") or "").upper().strip() == "AVAILABLE"
        and assistant_car_matches_request(car, request)
    ]
    cars.sort(key=lambda car: float(row_value(car, "daily_price") or 0))
    return [
        {
            "id": row_value(car, "id"),
            "name": row_value(car, "name"),
            "category": row_value(car, "category"),
            "fuel": row_value(car, "fuel_type"),
            "daily_price": float(row_value(car, "daily_price") or 0),
            "seats": row_value(car, "seats"),
            "bags": row_value(car, "bags"),
            "location": primary_inventory_location(row_value(car, "location")),
            "status": row_value(car, "status"),
            "image_url": row_value(car, "image_url"),
            "image_alt": vehicle_image_alt(car),
            "select_url": assistant_car_checkout_url(row_value(car, "id"), request),
        }
        for car in cars[:limit]
    ]


def assistant_result_cards(context: dict[str, object]) -> list[dict[str, str]]:
    booking_request = context.get("booking_request") if isinstance(context.get("booking_request"), dict) else None
    cars = context.get("cars") if isinstance(context.get("cars"), list) else []
    if not booking_request or booking_request.get("missing_fields") or not cars:
        return []
    cards: list[dict[str, str]] = []
    for index, car in enumerate(cars[:3]):
        if not isinstance(car, dict):
            continue
        name = str(car.get("name") or "FairFares car")
        category = str(car.get("category") or "Rental car")
        price = format_money(float(car.get("daily_price") or 0))
        cards.append(
            {
                "title": name,
                "subtitle": f"{category} - {price}/day",
                "badge": "Cheapest" if index == 0 else "Available",
                "image": optimized_static_image_url(str(car.get("image_url") or "/static/img/booking-confirmation-promise.png")),
                "alt": str(car.get("image_alt") or f"{name} rental car"),
                "href": str(car.get("select_url") or "/manage-booking"),
            }
        )
    return cards


