def option_label(options: tuple[tuple[str, str], ...], value: str, default: str = "") -> str:
    value = (value or "").strip()
    for option_value, label in options:
        if option_value == value:
            return label
    return default


def option_value_or_default(options: tuple[tuple[str, str], ...], value: object, default: str = "") -> str:
    clean_value = str(value or "").strip()
    allowed = {option_value for option_value, _label in options}
    return clean_value if clean_value in allowed else default


def clean_text_value(value: object, max_length: int) -> str:
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]+", " ", str(value or ""))
    text = re.sub(r"[ \t\r\f\v]+", " ", text).strip()
    return text[:max_length]


def clean_multiline_text_value(value: object, max_length: int) -> str:
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]+", " ", str(value or ""))
    text = re.sub(r"[ \t\r\f\v]+", " ", text).strip()
    return text[:max_length]


def clean_account_name(value: object) -> str:
    return clean_text_value(value, 120)


def valid_account_password(value: object) -> bool:
    password = str(value or "")
    return 8 <= len(password) <= MAX_PASSWORD_LENGTH


def validate_account_fields(name: object, email: object, phone: object, password: object) -> tuple[str, str, str, str]:
    clean_name = clean_account_name(name)
    clean_email = normalize_email(email)
    clean_phone = clean_text_value(phone, 40)
    if len(clean_name) < 2:
        return clean_name, clean_email, clean_phone, "Enter a name with at least 2 characters."
    if not valid_contact_email(clean_email):
        return clean_name, clean_email, clean_phone, "Enter a valid email address."
    if not valid_contact_phone(clean_phone):
        return clean_name, clean_email, clean_phone, "Enter a valid phone number."
    if not valid_account_password(password):
        return clean_name, clean_email, clean_phone, f"Password must be between 8 and {MAX_PASSWORD_LENGTH} characters."
    return clean_name, clean_email, clean_phone, ""


def valid_contact_email(value: str) -> bool:
    return bool(re.fullmatch(r"[^@\s]{1,120}@[^@\s]{1,180}\.[^@\s]{2,24}", value or ""))


def valid_contact_phone(value: str) -> bool:
    return 7 <= len(normalize_phone(value)) <= 15


def clean_social_url(value: object) -> str:
    text = clean_text_value(value, 240)
    if not text:
        return ""
    parsed = urllib.parse.urlparse(text)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    return text


def render_select_options(options: tuple[tuple[str, str], ...], selected: str = "") -> str:
    return "\n".join(
        f'<option value="{escape(value)}"{" selected" if value == selected else ""}>{escape(label)}</option>'
        for value, label in options
    )


def render_accommodation_subnav_links(selected_category: str = "") -> str:
    links: list[str] = []
    for href, label, category in ACCOMMODATION_SUBNAV_LINKS:
        if category:
            url = f"/accommodations?property_type={urllib.parse.quote(category)}#housing-posts"
            active = " active" if category == selected_category else ""
            links.append(f'<a class="housing-subnav-link{active}" href="{url}" data-filter-category="{escape(category)}">{escape(label)}</a>')
        else:
            links.append(f'<button class="housing-subnav-link" type="button" data-open-location>{escape(label)}</button>')
    return "\n".join(links)


def render_accommodation_place_chips(values: tuple[str, ...], selected_area: str = "") -> str:
    return "\n".join(
        f'<button type="button" class="housing-place-chip{" active" if value == selected_area else ""}" data-place="{escape(value)}">{escape(value)}</button>'
        for value in values
    )


def render_accommodation_metro_list(selected_metro: str = "") -> str:
    return "\n".join(
        f'<button type="button" class="housing-location-row{" active" if value == selected_metro else ""}" data-metro="{escape(value)}">{escape(label)}</button>'
        for value, label in accommodation_metro_filter_options()
        if value
    )


def slugify_location_key(value: str) -> str:
    value = (value or "").strip().lower()
    value = re.sub(r"[^a-z0-9]+", "-", value)
    return value.strip("-") or "location"


def split_city_state(value: str) -> tuple[str, str]:
    parts = [part.strip() for part in (value or "").split(",") if part.strip()]
    if len(parts) >= 2:
        return parts[0], parts[1].upper()[:2]
    return (parts[0] if parts else "", "")


def normalize_accommodation_place_label(value: str) -> str:
    value = re.sub(r"\s+", " ", (value or "").strip())
    value = re.sub(r",\s*US$", "", value, flags=re.IGNORECASE)
    return value


def dedupe_repeated_location_label(value: str) -> str:
    value = normalize_accommodation_place_label(value)
    if not value:
        return ""
    half = len(value) // 2
    if len(value) % 2 == 0 and value[:half].strip().lower() == value[half:].strip().lower():
        return value[:half].strip()
    return value


def static_accommodation_point(value: str) -> tuple[float, float]:
    label = normalize_accommodation_place_label(value).lower()
    if not label:
        return (0.0, 0.0)
    candidates = [label]
    if "," in label:
        candidates.append(label.split(",", 1)[0].strip())
    for candidate in candidates:
        if candidate in ACCOMMODATION_STATIC_POINTS:
            return ACCOMMODATION_STATIC_POINTS[candidate]
    return (0.0, 0.0)


def accommodation_metro_name_from_place(value: str) -> str:
    city, state = split_city_state(value)
    if city and state:
        return f"{city} Metro Area"
    if city:
        return city if "metro" in city.lower() or city.lower() in {"bay area", "new jersey"} else f"{city} Metro Area"
    return "Denver Metro Area"


def upsert_accommodation_metro(
    con: sqlite3.Connection,
    name: str,
    *,
    country: str = "US",
    state: str = "",
    center_city: str = "",
    lat: float = 0,
    lng: float = 0,
    source: str = "STATIC_FALLBACK",
    raw: dict[str, object] | None = None,
) -> int:
    name = normalize_accommodation_place_label(name) or "Denver Metro Area"
    if not center_city:
        center_city, parsed_state = split_city_state(name.replace(" Metro Area", ""))
        state = state or parsed_state
    metro_key = slugify_location_key(f"{country}-{state}-{name}")
    con.execute(
        """
        INSERT INTO accommodation_metros
            (metro_key, name, country, state, center_city, lat, lng, source, raw_json, last_refreshed_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        ON CONFLICT(metro_key) DO UPDATE SET
            name = excluded.name,
            country = excluded.country,
            state = COALESCE(NULLIF(excluded.state, ''), accommodation_metros.state),
            center_city = COALESCE(NULLIF(excluded.center_city, ''), accommodation_metros.center_city),
            lat = CASE WHEN excluded.lat != 0 THEN excluded.lat ELSE accommodation_metros.lat END,
            lng = CASE WHEN excluded.lng != 0 THEN excluded.lng ELSE accommodation_metros.lng END,
            source = excluded.source,
            raw_json = excluded.raw_json,
            last_refreshed_at = CURRENT_TIMESTAMP,
            updated_at = CURRENT_TIMESTAMP
        """,
        (metro_key, name, country, state, center_city, lat, lng, source, json.dumps(raw or {})),
    )
    row = con.execute("SELECT id FROM accommodation_metros WHERE metro_key = ?", (metro_key,)).fetchone()
    return int(row["id"])


def upsert_accommodation_local_area(
    con: sqlite3.Connection,
    metro_id: int,
    name: str,
    *,
    city: str = "",
    state: str = "",
    zip_code: str = "",
    place_type: str = "LOCALITY",
    lat: float = 0,
    lng: float = 0,
    radius_miles: float = 60,
    source: str = "STATIC_FALLBACK",
    raw: dict[str, object] | None = None,
) -> None:
    name = normalize_accommodation_place_label(name or zip_code)
    if not name:
        return
    if not city or not state:
        parsed_city, parsed_state = split_city_state(name)
        city = city or parsed_city
        state = state or parsed_state
    place_key = slugify_location_key(f"{metro_id}-{place_type}-{zip_code or name}")
    con.execute(
        """
        INSERT INTO accommodation_local_areas
            (metro_id, place_key, name, city, state, zip_code, place_type, lat, lng, radius_miles, source, raw_json, last_refreshed_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        ON CONFLICT(place_key) DO UPDATE SET
            metro_id = excluded.metro_id,
            name = excluded.name,
            city = COALESCE(NULLIF(excluded.city, ''), accommodation_local_areas.city),
            state = COALESCE(NULLIF(excluded.state, ''), accommodation_local_areas.state),
            zip_code = COALESCE(NULLIF(excluded.zip_code, ''), accommodation_local_areas.zip_code),
            place_type = excluded.place_type,
            lat = CASE WHEN excluded.lat != 0 THEN excluded.lat ELSE accommodation_local_areas.lat END,
            lng = CASE WHEN excluded.lng != 0 THEN excluded.lng ELSE accommodation_local_areas.lng END,
            radius_miles = excluded.radius_miles,
            source = excluded.source,
            raw_json = excluded.raw_json,
            last_refreshed_at = CURRENT_TIMESTAMP,
            updated_at = CURRENT_TIMESTAMP
        """,
        (metro_id, place_key, name, city, state, zip_code, place_type, lat, lng, radius_miles, source, json.dumps(raw or {})),
    )


def seed_accommodation_location_cache(con: sqlite3.Connection) -> None:
    for metro_name, data in ACCOMMODATION_METRO_GROUPS.items():
        sample_place = next(iter(data.get("suggested", ()) or (metro_name,)), metro_name)
        _, state = split_city_state(str(sample_place))
        metro_lat, metro_lng = static_accommodation_point(metro_name)
        if not metro_lat or not metro_lng:
            metro_lat, metro_lng = static_accommodation_point(str(sample_place))
        metro_id = upsert_accommodation_metro(con, metro_name, state=state, lat=metro_lat, lng=metro_lng, source="STATIC_FALLBACK", raw={"seed": True})
        for place in data.get("suggested", ()):
            city, place_state = split_city_state(str(place))
            place_lat, place_lng = static_accommodation_point(str(place))
            upsert_accommodation_local_area(con, metro_id, str(place), city=city, state=place_state or state, place_type="LOCALITY", lat=place_lat, lng=place_lng)
        for zip_code in data.get("zips", ()):
            upsert_accommodation_local_area(con, metro_id, str(zip_code), zip_code=str(zip_code), state=state, place_type="ZIP")
    for metro_name, _label in ACCOMMODATION_METRO_FILTERS:
        if metro_name:
            metro_lat, metro_lng = static_accommodation_point(metro_name)
            upsert_accommodation_metro(con, metro_name, lat=metro_lat, lng=metro_lng, source="STATIC_FALLBACK", raw={"seed": True})


def accommodation_metro_filter_options() -> tuple[tuple[str, str], ...]:
    try:
        with db() as con:
            rows = con.execute("SELECT name FROM accommodation_metros ORDER BY name ASC").fetchall()
    except sqlite3.Error:
        rows = []
    options = [("", "Metros")]
    seen = {""}
    for row in rows:
        name = row_value(row, "name")
        if name and name not in seen:
            options.append((name, name))
            seen.add(name)
    for value, label in ACCOMMODATION_METRO_FILTERS:
        if value and value not in seen:
            options.append((value, label))
            seen.add(value)
    return tuple(options)


def cached_accommodation_metro_for_place(place: str) -> str:
    place = normalize_accommodation_place_label(place)
    if not place:
        return ""
    try:
        with db() as con:
            exact = con.execute(
                """
                SELECT metro.name
                FROM accommodation_local_areas area
                JOIN accommodation_metros metro ON metro.id = area.metro_id
                WHERE lower(area.name) = lower(?) OR area.zip_code = ?
                LIMIT 1
                """,
                (place, place),
            ).fetchone()
            if exact:
                return row_value(exact, "name")
            city = place.split(",")[0].strip()
            city_match = con.execute(
                """
                SELECT metro.name
                FROM accommodation_local_areas area
                JOIN accommodation_metros metro ON metro.id = area.metro_id
                WHERE lower(area.city) = lower(?)
                LIMIT 1
                """,
                (city,),
            ).fetchone()
            return row_value(city_match, "name") if city_match else ""
    except sqlite3.Error:
        return ""


def google_accommodation_geocode(query: str) -> dict[str, object] | None:
    api_key = os.environ.get("GOOGLE_PLACES_API_KEY", "").strip() or os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()
    query = (query or "").strip()
    if not api_key or not query:
        return None
    params = urllib.parse.urlencode({"address": query, "key": api_key})
    try:
        payload = google_api_get(f"https://maps.googleapis.com/maps/api/geocode/json?{params}")
    except Exception:
        return None
    if payload.get("status") != "OK":
        return None
    results = payload.get("results") or []
    return results[0] if results and isinstance(results[0], dict) else None


def google_accommodation_nearby_areas(query: str, lat: float, lng: float) -> list[dict[str, object]]:
    api_key = os.environ.get("GOOGLE_PLACES_API_KEY", "").strip()
    if not api_key or not query or not lat or not lng:
        return []
    places: list[dict[str, object]] = []
    seen: set[str] = set()
    for text_query in (f"cities near {query}", f"neighborhoods near {query}", f"apartments and neighborhoods near {query}"):
        params = {
            "query": text_query,
            "key": api_key,
            "location": f"{lat},{lng}",
            "radius": "96560",
        }
        try:
            payload = google_api_get(f"https://maps.googleapis.com/maps/api/place/textsearch/json?{urllib.parse.urlencode(params)}")
        except Exception:
            continue
        if payload.get("status") not in {"OK", "ZERO_RESULTS"}:
            continue
        for place in payload.get("results") or []:
            if not isinstance(place, dict):
                continue
            name = normalize_accommodation_place_label(str(place.get("name") or ""))
            if not name or name.lower() in seen:
                continue
            seen.add(name.lower())
            places.append(place)
            if len(places) >= 18:
                return places
    return places


def clean_google_place_prediction(description: str) -> str:
    description = normalize_accommodation_place_label(description)
    description = re.sub(r",\s*(USA|United States)$", "", description, flags=re.I).strip()
    return dedupe_repeated_location_label(description)


def google_accommodation_place_suggestions(city: str, area: str = "", limit: int = 10) -> list[str]:
    api_key = os.environ.get("GOOGLE_PLACES_API_KEY", "").strip()
    city = normalize_accommodation_place_label(city)
    area = normalize_accommodation_place_label(area)
    city_root = city.split(",", 1)[0].strip().lower()
    if not api_key or not city or not area or area.lower() == city_root or area.lower() == city.lower():
        return []
    # Keep the user's place text intact. The city coordinates below are only a
    # proximity bias for neighborhood-style queries; appending the pickup city
    # here turned destinations such as "Cincinnati" into "Cincinnati Denver, CO".
    input_text = area or city
    geocode = google_accommodation_geocode(city)
    params: dict[str, str] = {
        "input": input_text,
        "key": api_key,
        "components": "country:us",
    }
    geometry = geocode.get("geometry") if isinstance(geocode, dict) else {}
    location = geometry.get("location") if isinstance(geometry, dict) else {}
    if isinstance(location, dict) and location.get("lat") and location.get("lng"):
        params["location"] = f"{location.get('lat')},{location.get('lng')}"
        params["radius"] = "96560"
    try:
        payload = google_api_get(f"https://maps.googleapis.com/maps/api/place/autocomplete/json?{urllib.parse.urlencode(params)}")
    except Exception:
        return []
    if payload.get("status") not in {"OK", "ZERO_RESULTS"}:
        return []
    suggestions: list[str] = []
    seen: set[str] = set()
    blocked_types = {"hospital", "stadium", "local_government_office"}
    for prediction in payload.get("predictions") or []:
        if not isinstance(prediction, dict):
            continue
        types = set(str(item) for item in (prediction.get("types") or []))
        if types & blocked_types:
            continue
        label = clean_google_place_prediction(str(prediction.get("description") or ""))
        if not label or label.lower() in seen:
            continue
        seen.add(label.lower())
        suggestions.append(label)
        if len(suggestions) >= limit:
            break
    return suggestions


def keep_mobile_accommodation_suggestion(label: str) -> bool:
    label = (label or "").strip()
    if not label:
        return False
    return not re.search(
        r"\b(public works|department|dept\.?|hospital|stadium|network|health center|convention center|airport|"
        r"library|car rental|hertz|tavern|market|mural|city council|city & county building|mayor|office|"
        r"pavilion|city o' city|cuernavaca|comedy works|hilton|hotel|improper city)\b",
        label,
        re.I,
    )


def accommodation_city_suggestions(query: str, limit: int = 8) -> list[str]:
    """Return verified U.S. city/state autocomplete labels from Places and cache."""
    query = normalize_accommodation_place_label(query)
    if len(query) < 2:
        return []
    limit = max(1, min(int(limit or 8), 12))
    suggestions: list[str] = []
    seen: set[str] = set()

    api_key = os.environ.get("GOOGLE_PLACES_API_KEY", "").strip() or os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()
    if api_key:
        params = urllib.parse.urlencode({"input": query, "types": "(cities)", "components": "country:us", "key": api_key})
        try:
            payload = google_api_get(f"https://maps.googleapis.com/maps/api/place/autocomplete/json?{params}")
        except Exception:
            payload = {}
        if payload.get("status") in {"OK", "ZERO_RESULTS"}:
            for prediction in payload.get("predictions") or []:
                if not isinstance(prediction, dict):
                    continue
                label = clean_google_place_prediction(str(prediction.get("description") or ""))
                if not re.fullmatch(r"[A-Za-z][A-Za-z .'-]{1,49},\s*[A-Za-z]{2}", label):
                    continue
                key = label.lower()
                if key not in seen:
                    seen.add(key)
                    suggestions.append(label)
                if len(suggestions) >= limit:
                    return suggestions

    try:
        with db() as con:
            cached = con.execute(
                """
                SELECT DISTINCT area.city, area.state
                FROM accommodation_local_areas area
                JOIN accommodation_metros metro ON metro.id = area.metro_id
                WHERE LOWER(area.city) LIKE LOWER(?)
                  AND UPPER(COALESCE(metro.country, 'US')) IN ('US', 'USA')
                  AND LENGTH(TRIM(area.state)) = 2
                ORDER BY CASE WHEN LOWER(area.city) = LOWER(?) THEN 0 ELSE 1 END, area.city
                LIMIT ?
                """,
                (f"{query.split(',', 1)[0].strip()}%", query.split(",", 1)[0].strip(), limit),
            ).fetchall()
        for row in cached:
            label = f"{str(row['city']).strip()}, {str(row['state']).strip().upper()}"
            if label.lower() not in seen:
                seen.add(label.lower())
                suggestions.append(label)
            if len(suggestions) >= limit:
                break
    except sqlite3.Error:
        pass
    return suggestions


def refresh_accommodation_location_cache(query: str, *, force: bool = False) -> str:
    query = normalize_accommodation_place_label(query)
    if not query:
        return ""
    cached = cached_accommodation_metro_for_place(query)
    if cached and not force and not re.fullmatch(r"\d{5}", query):
        return cached
    geocode = google_accommodation_geocode(query)
    if not geocode:
        return cached
    address_components = geocode.get("address_components") or []
    city = ""
    state = ""
    country = "US"
    zip_code = ""
    if isinstance(address_components, list):
        for component in address_components:
            if not isinstance(component, dict):
                continue
            types = set(component.get("types") or [])
            if "locality" in types or ("postal_town" in types and not city):
                city = str(component.get("long_name") or "")
            elif "administrative_area_level_1" in types:
                state = str(component.get("short_name") or "")
            elif "country" in types:
                country = str(component.get("short_name") or "US")
            elif "postal_code" in types:
                zip_code = str(component.get("long_name") or "")
    formatted = normalize_accommodation_place_label(str(geocode.get("formatted_address") or query))
    if not city:
        city, parsed_state = split_city_state(formatted)
        state = state or parsed_state
    geometry = geocode.get("geometry") if isinstance(geocode.get("geometry"), dict) else {}
    location = geometry.get("location") if isinstance(geometry.get("location"), dict) else {}
    lat = float(location.get("lat") or 0)
    lng = float(location.get("lng") or 0)
    metro_name = accommodation_metro_name_from_place(f"{city or query}, {state}" if state else city or query)
    try:
        with db() as con:
            metro_id = upsert_accommodation_metro(
                con,
                metro_name,
                country=country,
                state=state,
                center_city=city or query,
                lat=lat,
                lng=lng,
                source="GOOGLE_GEOCODE",
                raw=geocode,
            )
            locality_label = f"{city}, {state}" if city and state else formatted
            upsert_accommodation_local_area(
                con,
                metro_id,
                locality_label,
                city=city,
                state=state,
                zip_code=zip_code if re.fullmatch(r"\d{5}", query) else "",
                place_type="ZIP" if re.fullmatch(r"\d{5}", query) else "LOCALITY",
                lat=lat,
                lng=lng,
                source="GOOGLE_GEOCODE",
                raw=geocode,
            )
            for place in google_accommodation_nearby_areas(city or query, lat, lng):
                place_name = normalize_accommodation_place_label(str(place.get("name") or ""))
                place_geometry = place.get("geometry") if isinstance(place.get("geometry"), dict) else {}
                place_location = place_geometry.get("location") if isinstance(place_geometry.get("location"), dict) else {}
                place_lat = float(place_location.get("lat") or 0)
                place_lng = float(place_location.get("lng") or 0)
                upsert_accommodation_local_area(
                    con,
                    metro_id,
                    f"{place_name}, {state}" if state and "," not in place_name else place_name,
                    city=place_name,
                    state=state,
                    place_type="LOCALITY",
                    lat=place_lat,
                    lng=place_lng,
                    source="GOOGLE_PLACES",
                    raw=place,
                )
    except sqlite3.OperationalError as exc:
        if "locked" not in str(exc).lower():
            raise
        return cached or metro_name
    return metro_name


def accommodation_location_terms(search_metro: str) -> list[str]:
    search_metro = (search_metro or "").strip()
    if not search_metro:
        return []
    terms = [search_metro.replace(" Metro Area", "").strip(), search_metro]
    try:
        with db() as con:
            rows = con.execute(
                """
                SELECT area.name, area.city, area.zip_code
                FROM accommodation_local_areas area
                JOIN accommodation_metros metro ON metro.id = area.metro_id
                WHERE metro.name = ?
                ORDER BY CASE area.place_type WHEN 'ZIP' THEN 2 ELSE 1 END, area.name ASC
                """,
                (search_metro,),
            ).fetchall()
    except sqlite3.Error:
        rows = []
    for row in rows:
        for key in ("name", "city", "zip_code"):
            value = row_value(row, key).strip()
            if value:
                terms.append(value.split(",")[0].strip() if key != "zip_code" else value)
    return [term for term in dict.fromkeys(terms) if term]


def distance_miles_between(lat1: float, lng1: float, lat2: float, lng2: float) -> float:
    radius = 3958.7613
    d_lat = math.radians(lat2 - lat1)
    d_lng = math.radians(lng2 - lng1)
    a = (
        math.sin(d_lat / 2) ** 2
        + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(d_lng / 2) ** 2
    )
    return radius * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))


def google_directions_key() -> str:
    return (
        os.environ.get("GOOGLE_DIRECTIONS_API_KEY", "").strip()
        or os.environ.get("GOOGLE_ROUTES_API_KEY", "").strip()
        or os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()
        or os.environ.get("GOOGLE_PLACES_API_KEY", "").strip()
    )


def google_route_totals(points: list[dict[str, float]]) -> tuple[float, int] | None:
    api_key = google_directions_key()
    clean_points = [
        {"lat": float(point.get("lat") or 0), "lng": float(point.get("lng") or 0)}
        for point in points
        if float(point.get("lat") or 0) and float(point.get("lng") or 0)
    ]
    if not api_key or len(clean_points) < 2:
        return None
    origin = clean_points[0]
    destination = clean_points[-1]
    params: dict[str, str] = {
        "origin": f"{origin['lat']},{origin['lng']}",
        "destination": f"{destination['lat']},{destination['lng']}",
        "mode": "driving",
        "key": api_key,
    }
    if len(clean_points) > 2:
        params["waypoints"] = "|".join(f"{point['lat']},{point['lng']}" for point in clean_points[1:-1])
    try:
        payload = google_api_get(f"https://maps.googleapis.com/maps/api/directions/json?{urllib.parse.urlencode(params)}")
    except Exception:
        return None
    if str(payload.get("status") or "").upper() != "OK":
        return None
    routes = payload.get("routes")
    if not isinstance(routes, list) or not routes:
        return None
    legs = routes[0].get("legs") if isinstance(routes[0], dict) else None
    if not isinstance(legs, list):
        return None
    meters = 0
    seconds = 0
    for leg in legs:
        if not isinstance(leg, dict):
            continue
        distance = leg.get("distance") if isinstance(leg.get("distance"), dict) else {}
        duration = leg.get("duration") if isinstance(leg.get("duration"), dict) else {}
        meters += int(distance.get("value") or 0)
        seconds += int(duration.get("value") or 0)
    if meters <= 0:
        return None
    return (meters / 1609.344, int(math.ceil(seconds / 60.0)) if seconds else 0)


def accommodation_location_point(query: str, search_metro: str = "", allow_refresh: bool = True) -> dict[str, object]:
    query = normalize_accommodation_place_label(query)
    if not query and search_metro:
        query = normalize_accommodation_place_label(search_metro)
    if not query:
        return {}
    # Prefer an exact built-in place before broad cache matching. For example,
    # a cache row for "Miamisburg, OH" must never satisfy "Miami, Florida".
    static_lat, static_lng = static_accommodation_point(query)
    if static_lat and static_lng:
        return {"label": query, "metro": search_metro, "lat": static_lat, "lng": static_lng, "source": "static"}
    try:
        with db() as con:
            row = con.execute(
                """
                SELECT area.name, area.city, area.zip_code, area.lat, area.lng, metro.name AS metro_name, metro.lat AS metro_lat, metro.lng AS metro_lng
                FROM accommodation_local_areas area
                JOIN accommodation_metros metro ON metro.id = area.metro_id
                WHERE lower(area.name) = lower(?) OR area.zip_code = ?
                ORDER BY CASE WHEN area.lat != 0 AND area.lng != 0 THEN 0 ELSE 1 END
                LIMIT 1
                """,
                (query, query),
            ).fetchone()
            # For an unqualified search, match the structured city field only.
            # Substring matching makes Miami collide with Miamisburg.
            if not row and "," not in query and not re.search(r"\b\d{5}(?:-\d{4})?\b", query):
                city = query.split(",")[0].strip()
                row = con.execute(
                    """
                    SELECT area.name, area.city, area.zip_code, area.lat, area.lng, metro.name AS metro_name, metro.lat AS metro_lat, metro.lng AS metro_lng
                    FROM accommodation_local_areas area
                    JOIN accommodation_metros metro ON metro.id = area.metro_id
                    WHERE lower(area.city) = lower(?)
                    ORDER BY CASE WHEN area.lat != 0 AND area.lng != 0 THEN 0 ELSE 1 END
                    LIMIT 1
                    """,
                    (city,),
                ).fetchone()
            if row and float(row["lat"] or 0) and float(row["lng"] or 0):
                return {
                    "label": row_value(row, "name") or query,
                    "metro": row_value(row, "metro_name"),
                    "lat": float(row["lat"] or 0),
                    "lng": float(row["lng"] or 0),
                    "source": "cache",
                }
            if row:
                static_lat, static_lng = static_accommodation_point(row_value(row, "name") or row_value(row, "city") or query)
                if static_lat and static_lng:
                    return {
                        "label": row_value(row, "name") or query,
                        "metro": row_value(row, "metro_name"),
                        "lat": static_lat,
                        "lng": static_lng,
                        "source": "static",
                    }
            static_lat, static_lng = static_accommodation_point(query)
            if static_lat and static_lng:
                return {"label": query, "metro": search_metro, "lat": static_lat, "lng": static_lng, "source": "static"}
            metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", (search_metro or query,)).fetchone()
            if metro and float(metro["lat"] or 0) and float(metro["lng"] or 0):
                return {
                    "label": row_value(metro, "center_city") or row_value(metro, "name") or query,
                    "metro": row_value(metro, "name"),
                    "lat": float(metro["lat"] or 0),
                    "lng": float(metro["lng"] or 0),
                    "source": "metro",
                }
            if metro:
                static_lat, static_lng = static_accommodation_point(row_value(metro, "name") or query)
                if static_lat and static_lng:
                    return {
                        "label": row_value(metro, "center_city") or row_value(metro, "name") or query,
                        "metro": row_value(metro, "name"),
                        "lat": static_lat,
                        "lng": static_lng,
                        "source": "static",
                    }
    except sqlite3.Error:
        pass
    static_lat, static_lng = static_accommodation_point(query)
    if static_lat and static_lng:
        return {"label": query, "metro": search_metro, "lat": static_lat, "lng": static_lng, "source": "static"}
    if allow_refresh:
        metro_name = refresh_accommodation_location_cache(query)
        if metro_name:
            return accommodation_location_point(query, metro_name, allow_refresh=False)
    return {"label": query, "metro": search_metro, "lat": 0, "lng": 0, "source": "needs_geocode"}


def accommodation_address_label(values: sqlite3.Row | dict[str, object], fallback: str = "") -> str:
    """Return the most precise, browser-geocodable label available for a post."""
    street = row_value(values, "street_address")
    city = row_value(values, "city")
    zip_code = row_value(values, "zip_code")
    if street:
        parts: list[str] = []
        for value in (street, city, zip_code):
            value = value.strip()
            if value and value.lower() not in {part.lower() for part in parts}:
                parts.append(value)
        return ", ".join(parts)
    return (
        row_value(values, "city_area_zip")
        or row_value(values, "area_or_apartment")
        or row_value(values, "work_school_location")
        or city
        or zip_code
        or fallback
    ).strip()


def accommodation_form_location_query(form: dict[str, str]) -> str:
    """Build an unambiguous geocoding query instead of geocoding a street alone."""
    street = (form.get("street_address") or "").strip()
    if street:
        return accommodation_address_label(
            {
                "street_address": street,
                "city": (form.get("city") or "").strip(),
                "zip_code": (form.get("zip_code") or "").strip(),
            }
        )
    return (
        (form.get("primary_neighborhood") or "").strip()
        or (form.get("apartment_name") or "").strip()
        or (form.get("city_area_zip") or "").strip()
        or (form.get("area_or_apartment") or "").strip()
        or (form.get("work_school_location") or "").strip()
        or (form.get("city") or "").strip()
        or (form.get("zip_code") or "").strip()
    )


def accommodation_post_map_payload(posts: list[sqlite3.Row], selected_location: str, search_metro: str) -> dict[str, object]:
    center = accommodation_location_point(selected_location, search_metro)
    if not float(center.get("lat") or 0) or not float(center.get("lng") or 0):
        center = accommodation_location_point(search_metro or "Denver, CO", search_metro)
    payload_posts: list[dict[str, object]] = []
    center_lat = float(center.get("lat") or 0)
    center_lng = float(center.get("lng") or 0)
    post_ids = [int(row_value(row, "id") or 0) for row in posts[:80] if int(row_value(row, "id") or 0)]
    images_by_post: dict[int, list[str]] = {post_id: [] for post_id in post_ids}
    if post_ids:
        placeholders = ",".join("?" for _ in post_ids)
        try:
            with db() as con:
                image_rows = con.execute(
                    f"""
                    SELECT post_id, image_url
                    FROM accommodation_post_images
                    WHERE post_id IN ({placeholders})
                    ORDER BY post_id ASC, sort_order ASC, id ASC
                    """,
                    post_ids,
                ).fetchall()
            for image_row in image_rows:
                image_url = public_upload_url(row_value(image_row, "image_url"))
                post_id = int(row_value(image_row, "post_id") or 0)
                if image_url and post_id in images_by_post:
                    images_by_post[post_id].append(image_url)
        except sqlite3.Error:
            images_by_post = {post_id: [] for post_id in post_ids}
    for row in posts[:80]:
        post_id = int(row_value(row, "id") or 0)
        image_urls = images_by_post.get(post_id, [])
        preview_image = public_upload_url(row_value(row, "preview_image_url"))
        if preview_image and preview_image not in image_urls:
            image_urls.insert(0, preview_image)
        location_label = accommodation_address_label(row, selected_location)
        lat = float(row_value(row, "lat") or 0)
        lng = float(row_value(row, "lng") or 0)
        point_source = "post"
        # Older records may have been geocoded from only the street name. Let
        # Google Maps resolve the full saved address in the browser so those
        # pins are corrected without trusting potentially stale coordinates.
        if row_value(row, "street_address") and os.environ.get("GOOGLE_MAPS_API_KEY", "").strip():
            lat = 0
            lng = 0
            point_source = "full_address_geocode"
        elif not lat or not lng:
            point = accommodation_location_point(location_label, search_metro, allow_refresh=False)
            lat = float(point.get("lat") or 0)
            lng = float(point.get("lng") or 0)
            point_source = str(point.get("source") or "needs_geocode")
        distance = distance_miles_between(center_lat, center_lng, lat, lng) if center_lat and center_lng and lat and lng else None
        payload_posts.append(
            {
                "id": row_value(row, "public_id"),
                "title": row_value(row, "title"),
                "description": row_value(row, "description"),
                "mode": accommodation_mode_label(row),
                "category": option_label(ACCOMMODATION_CATEGORIES, row_value(row, "category"), "Housing"),
                "location": location_label,
                "area": row_value(row, "area_or_apartment"),
                "workLocation": row_value(row, "work_school_location"),
                "moveIn": row_value(row, "move_in_date"),
                "bedrooms": int(row_value(row, "bedroom_count") or 0),
                "bathrooms": int(row_value(row, "bathroom_count") or 0),
                "accommodates": int(row_value(row, "accommodates") or 0),
                "roommates": int(row_value(row, "roommate_count") or 0),
                "bathroomType": option_label((("shared", "Shared Bath"), ("private", "Private Bath"), ("private_shared", "Private/Shared Bath")), row_value(row, "bathroom_type"), row_value(row, "bathroom_type")),
                "genderPreference": option_label(ACCOMMODATION_GENDER_OPTIONS, row_value(row, "gender_preference"), "Open"),
                "leaseTerm": option_label(ACCOMMODATION_LEASE_TERMS, row_value(row, "lease_term"), "Flexible"),
                "deposit": float(row_value(row, "deposit") or 0),
                "daysAvailable": row_value(row, "days_available"),
                "vegetarianPreference": row_value(row, "vegetarian_preference"),
                "smokingPolicy": row_value(row, "smoking_policy"),
                "petFriendly": row_value(row, "pet_friendly"),
                "amenities": [item.strip() for item in row_value(row, "amenities").split(",") if item.strip()],
                "flags": {
                    "privateBath": bool(int(row_value(row, "private_bath") or 0)),
                    "furnished": bool(int(row_value(row, "furnished") or 0)),
                    "parking": bool(int(row_value(row, "parking") or 0)),
                    "utilitiesIncluded": bool(int(row_value(row, "utilities_included") or 0)),
                },
                "images": image_urls[:4],
                "lat": lat,
                "lng": lng,
                "radius": int(float(row_value(row, "radius_miles") or 0)),
                "rent": format_accommodation_rent(row),
                "rentValue": float(row_value(row, "rent_min") or row_value(row, "rent_max") or 0),
                "distance": round(distance, 1) if distance is not None else None,
                "source": point_source,
            }
        )
    return {
        "center": {
            "label": center.get("label") or selected_location or search_metro or "Denver, CO",
            "lat": center_lat,
            "lng": center_lng,
        },
        "posts": payload_posts,
        "mapsEnabled": bool(os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()),
    }


def account_deletion_payload(row: sqlite3.Row | dict[str, object] | None) -> dict[str, object] | None:
    if not row:
        return None
    return {
        "requestId": row_value(row, "request_id"),
        "status": row_value(row, "status"),
        "requestedAt": row_value(row, "requested_at"),
        "deletionDueAt": row_value(row, "deletion_due_at"),
        "completedAt": row_value(row, "completed_at"),
        "retainedDataSummary": row_value(row, "retained_data_summary"),
    }


def create_account_deletion_request(user_id: int, email: str, source: str) -> dict[str, object]:
    with db() as con:
        existing = con.execute(
            "SELECT * FROM account_deletion_requests WHERE user_id = ? AND status IN ('PENDING', 'IN_PROGRESS') ORDER BY id DESC LIMIT 1",
            (user_id,),
        ).fetchone()
        if existing:
            return account_deletion_payload(existing) or {}
        request_id = f"DEL-{datetime.now(UTC).strftime('%Y%m%d')}-{secrets.token_hex(4).upper()}"
        due_at = (datetime.now(UTC) + timedelta(days=30)).strftime("%Y-%m-%d %H:%M:%S")
        con.execute(
            "INSERT INTO account_deletion_requests (request_id, user_id, email_snapshot, source, deletion_due_at) VALUES (?, ?, ?, ?, ?)",
            (request_id, user_id, normalize_email(email), clean_text_value(source, 20).upper() or "MOBILE", due_at),
        )
        row = con.execute("SELECT * FROM account_deletion_requests WHERE request_id = ?", (request_id,)).fetchone()
    subject = f"FairFares account deletion request {request_id}"
    text_body = (
        f"We received your FairFares account deletion request {request_id}.\n\n"
        f"The request is due for completion by {due_at} UTC. FairFares will delete or de-identify account data that is not legally required for bookings, payments, safety, tax, insurance, fraud prevention, or disputes.\n\n"
        "If you did not make this request, contact hello@fairfare.space immediately."
    )
    html_body = "<p>" + escape(text_body).replace("\n", "<br>") + "</p>"
    if normalize_email(email):
        send_with_resend(normalize_email(email), subject, text_body, html_body)
    send_operational_alert(
        f"account-deletion:{user_id}",
        "Account deletion request received",
        severity="warning",
        details=[f"Request: {request_id}", f"User ID: {user_id}", f"Source: {source}", f"Due: {due_at} UTC"],
    )
    return account_deletion_payload(row) or {}


def mobile_user_payload(user: sqlite3.Row | dict[str, object] | None) -> dict[str, object] | None:
    if not user:
        return None
    return {
        "id": int(row_value(user, "id") or 0),
        "name": row_value(user, "name"),
        "email": row_value(user, "email"),
        "phone": row_value(user, "phone"),
        "dateOfBirth": row_value(user, "date_of_birth"),
        "role": row_value(user, "role") or "CUSTOMER",
        "isAdmin": bool(int(row_value(user, "is_admin") or 0)),
        "isVerified": bool(int(row_value(user, "is_verified") or 0)),
        "phoneVerified": bool(row_value(user, "phone_verified_at")),
        "chatPhoneDiscoverable": bool(int(row_value(user, "chat_phone_discoverable") or 0)),
        "promotionalNotificationsEnabled": bool(int(row_value(user, "promo_email_opt_in") or 0)),
        "profilePhotoUrl": row_value(user, "profile_photo_url"),
    }


def accommodation_post_image_urls(post_id: int, preview_image: str = "", limit: int = 4) -> list[str]:
    image_urls: list[str] = []
    if post_id:
        try:
            with db() as con:
                image_rows = con.execute(
                    """
                    SELECT image_url
                    FROM accommodation_post_images
                    WHERE post_id = ?
                    ORDER BY sort_order ASC, id ASC
                    LIMIT ?
                    """,
                    (post_id, max(1, min(int(limit or 4), 4))),
                ).fetchall()
            image_urls = [row_value(image_row, "image_url") for image_row in image_rows if row_value(image_row, "image_url")]
        except sqlite3.Error:
            image_urls = []
    if preview_image and preview_image not in image_urls:
        image_urls.insert(0, preview_image)
    return [public_upload_url(image_url) for image_url in image_urls[:4] if image_url]


def mobile_housing_post_payload(row: sqlite3.Row) -> dict[str, object]:
    images = accommodation_post_image_urls(int(row_value(row, "id") or 0), row_value(row, "preview_image_url"), limit=4)
    preview_image = images[0] if images else ""
    return {
        "id": row_value(row, "public_id"),
        "title": row_value(row, "title"),
        "description": row_value(row, "description"),
        "mode": row_value(row, "post_mode"),
        "modeLabel": accommodation_mode_label(row),
        "category": row_value(row, "category"),
        "categoryLabel": option_label(ACCOMMODATION_CATEGORIES, row_value(row, "category"), "Housing"),
        "location": row_value(row, "city_area_zip") or row_value(row, "city") or "Location open",
        "area": row_value(row, "area_or_apartment") or row_value(row, "primary_neighborhood"),
        "workLocation": row_value(row, "work_school_location"),
        "moveIn": row_value(row, "move_in_date"),
        "rent": format_accommodation_rent(row),
        "rentValue": float(row_value(row, "rent_min") or row_value(row, "rent_max") or 0),
        "radiusMiles": int(float(row_value(row, "radius_miles") or 0)),
        "distanceMiles": round(float(row_value(row, "distance_miles") or 0), 1) if row_value(row, "distance_miles") not in {"", None} else None,
        "lat": float(row_value(row, "lat") or 0),
        "lng": float(row_value(row, "lng") or 0),
        "imageUrl": preview_image,
        "images": images,
        "posterName": row_value(row, "owner_name") or row_value(row, "contact_name") or "FairFares member",
        "posterEmail": normalize_email(row_value(row, "contact_email")),
        "posterUserId": int(row_value(row, "user_id") or 0),
        "daysLeft": accommodation_days_left(row),
        "expiryLabel": accommodation_expiry_label(row),
        "roommateIntent": bool(int(row_value(row, "roommate_intent") or 0)),
        "genderPreference": option_label(ACCOMMODATION_GENDER_OPTIONS, row_value(row, "gender_preference"), "Open"),
        "leaseTerm": option_label(ACCOMMODATION_LEASE_TERMS, row_value(row, "lease_term"), "Flexible"),
        "bathroomType": option_label((("shared", "Shared Bath"), ("private", "Private Bath"), ("private_shared", "Private/Shared Bath")), row_value(row, "bathroom_type"), row_value(row, "bathroom_type")),
        "accommodates": int(row_value(row, "accommodates") or 0),
        "roommateCount": int(row_value(row, "roommate_count") or 0),
        "amenities": [item.strip() for item in row_value(row, "amenities").split(",") if item.strip()],
    }


RIDE_TYPE_LABELS = {
    "SCHEDULED_REQUEST": "Scheduled ride",
    "GENERAL_REQUEST": "Ride request",
    "CARPOOL_REQUEST": "Find carpool",
    "CARPOOL_OFFER": "Offer a ride",
}

RIDE_TYPES = set(RIDE_TYPE_LABELS)
RIDE_ROLES = {"RIDER", "DRIVER"}


def ride_public_id() -> str:
    return f"FRD-{secrets.token_hex(4).upper()}"


def normalize_ride_type(value: object) -> str:
    clean = str(value or "").strip().upper()
    aliases = {
        "SCHEDULED": "SCHEDULED_REQUEST",
        "REQUEST": "GENERAL_REQUEST",
        "GENERAL": "GENERAL_REQUEST",
        "NEED_RIDE": "GENERAL_REQUEST",
        "FIND_CARPOOL": "CARPOOL_REQUEST",
        "CARPOOL": "CARPOOL_REQUEST",
        "OFFER": "CARPOOL_OFFER",
        "DRIVE": "CARPOOL_OFFER",
        "PROVIDE_RIDE": "CARPOOL_OFFER",
    }
    clean = aliases.get(clean, clean)
    return clean if clean in RIDE_TYPES else "GENERAL_REQUEST"


def ride_role_for_type(ride_type: str) -> str:
    return "DRIVER" if ride_type == "CARPOOL_OFFER" else "RIDER"


def ride_point(query: str, city: str = "", *, allow_refresh: bool = True) -> dict[str, object]:
    clean_query = normalize_accommodation_place_label(query)
    clean_city = normalize_accommodation_place_label(city)
    if not clean_query:
        return accommodation_location_point(clean_city, allow_refresh=allow_refresh)

    qualified_pattern = r"\b(university|college|airport|international|amtrak|terminal)\b"
    looks_qualified = bool(
        "," in clean_query
        or re.search(r"\b[A-Z]{2}\b", clean_query)
        or re.search(r"\b\d{5}(?:-\d{4})?\b", clean_query)
        or re.search(qualified_pattern, clean_query, flags=re.IGNORECASE)
    )
    scoped_query = f"{clean_query}, {clean_city}" if clean_city and clean_city.lower() not in clean_query.lower() else clean_query
    candidates = [clean_query, scoped_query] if looks_qualified else [scoped_query, clean_query]
    seen: set[str] = set()
    fallback: dict[str, object] = {}
    for candidate in candidates:
        candidate = normalize_accommodation_place_label(candidate)
        if not candidate or candidate.lower() in seen:
            continue
        seen.add(candidate.lower())
        point = accommodation_location_point(candidate, allow_refresh=allow_refresh)
        if not fallback:
            fallback = point
        if float(point.get("lat") or 0) and float(point.get("lng") or 0):
            return point
    return fallback


def google_reverse_location_label(lat: float, lng: float) -> str:
    maps_key = (
        os.environ.get("GOOGLE_GEOCODING_API_KEY", "").strip()
        or os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()
        or os.environ.get("GOOGLE_PLACES_API_KEY", "").strip()
    )
    if not maps_key or not lat or not lng:
        return ""
    params = urllib.parse.urlencode(
        {
            "latlng": f"{lat:.7f},{lng:.7f}",
            "key": maps_key,
            "result_type": "street_address|premise|subpremise|establishment|route",
        }
    )
    try:
        payload = google_api_get(f"https://maps.googleapis.com/maps/api/geocode/json?{params}")
    except Exception as exc:
        print(f"Ride reverse geocode fallback failed: {type(exc).__name__}: {exc}")
        return ""
    if str(payload.get("status") or "").upper() != "OK":
        return ""
    results = payload.get("results") if isinstance(payload.get("results"), list) else []
    for result in results:
        if not isinstance(result, dict):
            continue
        formatted = normalize_accommodation_place_label(str(result.get("formatted_address") or ""))
        if formatted:
            return dedupe_repeated_location_label(formatted)
    return ""


def ride_display_label(raw_label: str, resolved_point: dict[str, object], city: str = "") -> str:
    fallback = dedupe_repeated_location_label(raw_label)
    resolved = dedupe_repeated_location_label(str(resolved_point.get("label") or ""))
    city_label = normalize_accommodation_place_label(city)
    city_root = city_label.split(",", 1)[0].strip().lower()
    if fallback and resolved and city_root and resolved.lower() == city_root and fallback.lower() != city_root:
        return fallback
    return resolved or fallback or city_label or "Location open"


def ride_place_icon_source(label: str) -> str:
    label = (label or "").lower()
    if "airport" in label or "(den)" in label:
        return "airport"
    if "station" in label or "rtd" in label or "amtrak" in label:
        return "transit"
    if "apartment" in label or "apt" in label:
        return "home"
    return "place"


def ride_place_suggestions(city: str, query: str = "", limit: int = 10) -> list[dict[str, object]]:
    city = normalize_accommodation_place_label(city or "Denver, CO")
    query = normalize_accommodation_place_label(query)
    city_point = ride_point(city, allow_refresh=False)
    labels: list[tuple[str, str]] = []

    def add_label(label: str, source: str) -> None:
        clean = dedupe_repeated_location_label(normalize_accommodation_place_label(label))
        if not clean:
            return
        if any(existing.lower() == clean.lower() for existing, _ in labels):
            return
        labels.append((clean, source))

    normalized_query = re.sub(r"[^a-z0-9]+", " ", query.lower()).strip()
    if re.search(r"\b(unin|unio|union)\b", normalized_query):
        add_label("Union Station, 1701 Wynkoop St, Denver, CO", "autocorrect")
        add_label("Denver Union Station, 1701 Wynkoop St, Denver, CO", "autocorrect")

    google_query = query
    if google_query:
        for label in google_accommodation_place_suggestions(city, google_query, limit=limit * 2):
            add_label(label, "google")

    fallback_places = [
        "Denver International Airport (DEN), 8500 Pena Blvd, Denver, CO",
        "Union Station, 1701 Wynkoop St, Denver, CO",
        "Denver Union Station, 1701 Wynkoop St, Denver, CO",
        "300 East Seventeenth Apartments, 300 E 17th Ave, Denver, CO",
        "2523 W Houstoun Waring Cir, Littleton, CO",
        "1855 W Union Ave, Englewood, CO",
        "Tracks, 3500 Walnut St, Denver, CO",
        "Larimer Lounge, 2721 Larimer St, Denver, CO",
    ]
    for label in fallback_places:
        normalized_label = re.sub(r"[^a-z0-9]+", " ", label.lower())
        if not normalized_query:
            add_label(label, "recent")
        elif normalized_query in normalized_label:
            add_label(label, "fallback")
        elif "unin" in normalized_query and "union station" in normalized_label:
            add_label(label, "fallback")

    suggestions: list[dict[str, object]] = []
    for label, source in labels:
        try:
            point = ride_point(label, city, allow_refresh=False)
        except sqlite3.OperationalError as exc:
            if "locked" not in str(exc).lower():
                raise
            point = {"label": label, "lat": 0, "lng": 0}
        lat = float(point.get("lat") or 0)
        lng = float(point.get("lng") or 0)
        city_lat = float(city_point.get("lat") or 0)
        city_lng = float(city_point.get("lng") or 0)
        distance = round(distance_miles_between(city_lat, city_lng, lat, lng), 1) if lat and lng and city_lat and city_lng else None
        parts = [part.strip() for part in label.split(",") if part.strip()]
        suggestions.append(
            {
                "label": label,
                "main": parts[0] if parts else label,
                "secondary": ", ".join(parts[1:]) if len(parts) > 1 else city,
                "distanceMiles": distance,
                "lat": lat,
                "lng": lng,
                "source": source,
                "icon": ride_place_icon_source(label),
            }
        )
        if len(suggestions) >= max(1, min(int(limit or 10), 20)):
            break
    return suggestions


def ride_allowed_detour_miles(row: sqlite3.Row | dict[str, object]) -> float:
    try:
        max_detour_minutes = int(float(row_value(row, "max_detour_minutes") or row_value(row, "maxDetourMinutes") or 0))
    except (TypeError, ValueError):
        max_detour_minutes = 0
    try:
        max_pickup_distance = float(row_value(row, "max_pickup_distance_miles") or row_value(row, "maxPickupDistanceMiles") or 0)
    except (TypeError, ValueError):
        max_pickup_distance = 0
    minute_based_miles = max_detour_minutes / 2.0 if max_detour_minutes else 0
    configured_miles = max(minute_based_miles, max_pickup_distance or 0)
    return round(min(50.0, max(8.0, configured_miles)), 1)


def ride_detour_minutes_from_miles(miles: object) -> int | None:
    try:
        value = float(miles)
    except (TypeError, ValueError):
        return None
    if value < 0:
        value = 0
    return int(math.ceil(value * 2.0))


def ride_coordinate_value(row: sqlite3.Row | dict[str, object], *keys: str) -> float:
    for key in keys:
        value = row_value(row, key)
        if value in {"", None}:
            continue
        try:
            return float(value)
        except (TypeError, ValueError):
            continue
    return 0.0


def ride_route_direction_compatible(
    row: sqlite3.Row | dict[str, object],
    origin_point: dict[str, object],
    destination_point: dict[str, object],
) -> bool:
    """Reject reverse/perpendicular trips before they can become route matches."""
    driver_origin_lat = ride_coordinate_value(row, "origin_lat", "originLat")
    driver_origin_lng = ride_coordinate_value(row, "origin_lng", "originLng")
    driver_dest_lat = ride_coordinate_value(row, "destination_lat", "destinationLat")
    driver_dest_lng = ride_coordinate_value(row, "destination_lng", "destinationLng")
    query_origin_lat = float(origin_point.get("lat") or 0)
    query_origin_lng = float(origin_point.get("lng") or 0)
    query_dest_lat = float(destination_point.get("lat") or 0)
    query_dest_lng = float(destination_point.get("lng") or 0)
    if not all((driver_origin_lat, driver_origin_lng, driver_dest_lat, driver_dest_lng, query_origin_lat, query_origin_lng, query_dest_lat, query_dest_lng)):
        return False

    reference_lat = math.radians((driver_origin_lat + driver_dest_lat + query_origin_lat + query_dest_lat) / 4.0)
    longitude_scale = max(0.2, math.cos(reference_lat))

    def projected(lat: float, lng: float) -> tuple[float, float]:
        return (lng * longitude_scale, lat)

    driver_start = projected(driver_origin_lat, driver_origin_lng)
    driver_end = projected(driver_dest_lat, driver_dest_lng)
    rider_start = projected(query_origin_lat, query_origin_lng)
    rider_end = projected(query_dest_lat, query_dest_lng)
    driver_vector = (driver_end[0] - driver_start[0], driver_end[1] - driver_start[1])
    rider_vector = (rider_end[0] - rider_start[0], rider_end[1] - rider_start[1])
    driver_length = math.hypot(*driver_vector)
    rider_length = math.hypot(*rider_vector)
    if driver_length <= 1e-6 or rider_length <= 1e-6:
        return False
    direction_cosine = (driver_vector[0] * rider_vector[0] + driver_vector[1] * rider_vector[1]) / (driver_length * rider_length)
    driver_miles = distance_miles_between(driver_origin_lat, driver_origin_lng, driver_dest_lat, driver_dest_lng)
    rider_miles = distance_miles_between(query_origin_lat, query_origin_lng, query_dest_lat, query_dest_lng)
    # Local trips can turn through a street grid. Longer trips must still move
    # broadly in the same direction as the listed route.
    if min(driver_miles, rider_miles) >= 20 and direction_cosine < 0.25:
        return False
    denominator = driver_length * driver_length
    start_progress = ((rider_start[0] - driver_start[0]) * driver_vector[0] + (rider_start[1] - driver_start[1]) * driver_vector[1]) / denominator
    end_progress = ((rider_end[0] - driver_start[0]) * driver_vector[0] + (rider_end[1] - driver_start[1]) * driver_vector[1]) / denominator
    # Permit a small pickup-navigation backtrack, but never enough to turn a
    # reversed local trip into a valid match.
    progress_tolerance = max(0.05, min(0.25, 2.0 / max(driver_miles, 1.0)))
    return end_progress + progress_tolerance >= start_progress


def ride_route_detour_details(
    row: sqlite3.Row | dict[str, object],
    origin_point: dict[str, object],
    destination_point: dict[str, object],
    allow_google: bool = True,
) -> dict[str, object]:
    driver_origin_lat = ride_coordinate_value(row, "origin_lat", "originLat")
    driver_origin_lng = ride_coordinate_value(row, "origin_lng", "originLng")
    driver_dest_lat = ride_coordinate_value(row, "destination_lat", "destinationLat")
    driver_dest_lng = ride_coordinate_value(row, "destination_lng", "destinationLng")
    query_origin_lat = float(origin_point.get("lat") or 0)
    query_origin_lng = float(origin_point.get("lng") or 0)
    query_dest_lat = float(destination_point.get("lat") or 0)
    query_dest_lng = float(destination_point.get("lng") or 0)
    if not all((driver_origin_lat, driver_origin_lng, driver_dest_lat, driver_dest_lng, query_origin_lat, query_origin_lng, query_dest_lat, query_dest_lng)):
        return {"miles": None, "minutes": None, "source": "missing"}
    driver_origin = {"lat": driver_origin_lat, "lng": driver_origin_lng}
    driver_destination = {"lat": driver_dest_lat, "lng": driver_dest_lng}
    query_origin = {"lat": query_origin_lat, "lng": query_origin_lng}
    query_destination = {"lat": query_dest_lat, "lng": query_dest_lng}
    direct_driver_distance = distance_miles_between(driver_origin_lat, driver_origin_lng, driver_dest_lat, driver_dest_lng)
    straight_route_with_rider = (
        distance_miles_between(driver_origin_lat, driver_origin_lng, query_origin_lat, query_origin_lng)
        + distance_miles_between(query_origin_lat, query_origin_lng, query_dest_lat, query_dest_lng)
        + distance_miles_between(query_dest_lat, query_dest_lng, driver_dest_lat, driver_dest_lng)
    )
    straight_extra_miles = round(max(0.0, straight_route_with_rider - direct_driver_distance), 1)
    if allow_google:
        direct_route = google_route_totals([driver_origin, driver_destination])
        route_with_rider = google_route_totals([driver_origin, query_origin, query_destination, driver_destination])
        if direct_route and route_with_rider:
            google_extra_miles = round(max(0.0, route_with_rider[0] - direct_route[0]), 1)
            # The waypoint path cannot be shorter than its three great-circle
            # legs. Compare that lower bound with the actual direct road route;
            # comparing it with the straight direct leg would overstate detours
            # when the direct road itself must bend around terrain.
            geometry_lower_bound = round(max(0.0, straight_route_with_rider - direct_route[0]), 1)
            extra_miles = max(google_extra_miles, geometry_lower_bound)
            extra_minutes = max(0, int(route_with_rider[1] - direct_route[1]), ride_detour_minutes_from_miles(geometry_lower_bound) or 0)
            return {"miles": extra_miles, "minutes": extra_minutes, "source": "GOOGLE_DIRECTIONS"}
    extra_miles = straight_extra_miles
    return {"miles": extra_miles, "minutes": ride_detour_minutes_from_miles(extra_miles), "source": "ESTIMATE"}


def ride_route_detour_miles(
    row: sqlite3.Row | dict[str, object],
    origin_point: dict[str, object],
    destination_point: dict[str, object],
    allow_google: bool = True,
) -> float | None:
    miles = ride_route_detour_details(row, origin_point, destination_point, allow_google=allow_google).get("miles")
    return float(miles) if miles is not None else None


def ride_score(
    row: sqlite3.Row,
    origin_point: dict[str, object],
    destination_point: dict[str, object],
    pickup_date: str = "",
    pickup_time: str = "",
    allow_google: bool = True,
) -> int:
    score = 55
    origin_lat = float(row_value(row, "origin_lat") or 0)
    origin_lng = float(row_value(row, "origin_lng") or 0)
    dest_lat = float(row_value(row, "destination_lat") or 0)
    dest_lng = float(row_value(row, "destination_lng") or 0)
    query_origin_lat = float(origin_point.get("lat") or 0)
    query_origin_lng = float(origin_point.get("lng") or 0)
    query_dest_lat = float(destination_point.get("lat") or 0)
    query_dest_lng = float(destination_point.get("lng") or 0)
    if origin_lat and origin_lng and query_origin_lat and query_origin_lng:
        pickup_distance = distance_miles_between(query_origin_lat, query_origin_lng, origin_lat, origin_lng)
        score += max(0, 20 - int(pickup_distance * 2))
    if dest_lat and dest_lng and query_dest_lat and query_dest_lng:
        drop_distance = distance_miles_between(query_dest_lat, query_dest_lng, dest_lat, dest_lng)
        score += max(0, 15 - int(drop_distance * 2))
    route_deviation = ride_route_detour_miles(row, origin_point, destination_point, allow_google=allow_google)
    if route_deviation is not None:
        score += max(0, 20 - int(route_deviation))
    if pickup_date and pickup_date == row_value(row, "pickup_date"):
        score += 5
    if pickup_time and pickup_time == row_value(row, "pickup_time"):
        score += 5
    if row_value(row, "ride_type") == "CARPOOL_OFFER":
        score += 5
    return max(0, min(score, 100))


def ride_route_match_metrics(
    row: sqlite3.Row,
    origin_point: dict[str, object],
    destination_point: dict[str, object],
    allow_google: bool = True,
) -> dict[str, object]:
    origin_lat = float(row_value(row, "origin_lat") or 0)
    origin_lng = float(row_value(row, "origin_lng") or 0)
    dest_lat = float(row_value(row, "destination_lat") or 0)
    dest_lng = float(row_value(row, "destination_lng") or 0)
    query_origin_lat = float(origin_point.get("lat") or 0)
    query_origin_lng = float(origin_point.get("lng") or 0)
    query_dest_lat = float(destination_point.get("lat") or 0)
    query_dest_lng = float(destination_point.get("lng") or 0)
    pickup_distance = (
        round(distance_miles_between(query_origin_lat, query_origin_lng, origin_lat, origin_lng), 1)
        if origin_lat and origin_lng and query_origin_lat and query_origin_lng
        else None
    )
    dropoff_distance = (
        round(distance_miles_between(query_dest_lat, query_dest_lng, dest_lat, dest_lng), 1)
        if dest_lat and dest_lng and query_dest_lat and query_dest_lng
        else None
    )
    route_deviation_details = ride_route_detour_details(row, origin_point, destination_point, allow_google=allow_google)
    route_deviation = route_deviation_details.get("miles")
    route_deviation_minutes = route_deviation_details.get("minutes")
    if route_deviation is None:
        known_distances = [distance for distance in (pickup_distance, dropoff_distance) if distance is not None]
        route_deviation = round(max(known_distances), 1) if known_distances else None
        route_deviation_minutes = ride_detour_minutes_from_miles(route_deviation)
    return {
        "pickupDistanceMiles": pickup_distance,
        "dropoffDistanceMiles": dropoff_distance,
        "routeDeviationMiles": route_deviation,
        "routeDeviationMinutes": route_deviation_minutes,
        "routeDeviationSource": route_deviation_details.get("source"),
        "directionCompatible": ride_route_direction_compatible(row, origin_point, destination_point),
    }


def ride_route_match_is_valid(
    row: sqlite3.Row | dict[str, object],
    metrics: dict[str, object],
    maximum_miles: float | None = None,
) -> bool:
    """Apply one route acceptance rule everywhere a carpool match is made."""
    route_deviation = metrics.get("routeDeviationMiles")
    if route_deviation is None or not bool(metrics.get("directionCompatible")):
        return False
    allowed_miles = ride_allowed_detour_miles(row)
    if maximum_miles is not None:
        allowed_miles = min(allowed_miles, max(0.0, float(maximum_miles)))
    try:
        return float(route_deviation) <= allowed_miles
    except (TypeError, ValueError):
        return False


def ride_effective_trip_date(row: sqlite3.Row | dict[str, object]) -> date | None:
    value = (row_value(row, "pickup_date") or row_value(row, "start_date") or "").strip()
    if not value:
        return None
    try:
        return date.fromisoformat(value[:10])
    except ValueError:
        return None


def ride_post_expired(row: sqlite3.Row | dict[str, object]) -> bool:
    trip_date = ride_effective_trip_date(row)
    return bool(trip_date and trip_date < datetime.now(FAIRFARES_TZ).date())


def ride_effective_status(row: sqlite3.Row | dict[str, object]) -> str:
    status = (row_value(row, "status") or "ACTIVE").strip().upper()
    if ride_post_expired(row) and status in {"ACTIVE", "OPEN", "PENDING", "LISTED"}:
        return "EXPIRED"
    return status


def mobile_ride_payload(
    row: sqlite3.Row,
    origin_point: dict[str, object] | None = None,
    destination_point: dict[str, object] | None = None,
    allow_google_routes: bool = True,
) -> dict[str, object]:
    origin_point = origin_point or {}
    destination_point = destination_point or {}
    route_metrics = ride_route_match_metrics(row, origin_point, destination_point, allow_google=allow_google_routes)
    expired = ride_post_expired(row)
    status = ride_effective_status(row)
    owner_user_id = int(row_value(row, "user_id") or 0)
    owner_name = row_value(row, "owner_name")
    if not owner_name and owner_user_id:
        try:
            with db() as con:
                owner = con.execute("SELECT name FROM users WHERE id = ? LIMIT 1", (owner_user_id,)).fetchone()
            owner_name = row_value(owner, "name") if owner else ""
        except sqlite3.Error:
            owner_name = ""
    return {
        "id": row_value(row, "public_id"),
        "type": row_value(row, "ride_type"),
        "typeLabel": RIDE_TYPE_LABELS.get(row_value(row, "ride_type"), "Ride"),
        "role": row_value(row, "rider_role"),
        "ownerUserId": owner_user_id,
        "ownerName": owner_name,
        "title": row_value(row, "title"),
        "origin": row_value(row, "origin_label"),
        "originLat": float(row_value(row, "origin_lat") or 0) or None,
        "originLng": float(row_value(row, "origin_lng") or 0) or None,
        "destination": row_value(row, "destination_label"),
        "destinationLat": float(row_value(row, "destination_lat") or 0) or None,
        "destinationLng": float(row_value(row, "destination_lng") or 0) or None,
        "city": row_value(row, "city_label"),
        "pickupDate": row_value(row, "pickup_date") or row_value(row, "start_date"),
        "pickupTime": row_value(row, "pickup_time"),
        "startDate": row_value(row, "start_date"),
        "endDate": row_value(row, "end_date"),
        "daysOfWeek": [item.strip() for item in row_value(row, "days_of_week").split(",") if item.strip()],
        "seats": int(row_value(row, "seats") or 1),
        "luggage": row_value(row, "luggage"),
        "accessibility": row_value(row, "accessibility"),
        "maxDetourMinutes": int(row_value(row, "max_detour_minutes") or 0),
        "maxPickupDistanceMiles": float(row_value(row, "max_pickup_distance_miles") or 0),
        "departureFlexMinutes": int(row_value(row, "departure_flex_minutes") or 0),
        "contributionPerSeat": float(row_value(row, "contribution_per_seat") or 0),
        "approvalRequired": bool(int(row_value(row, "approval_required") or 0)),
        "preferences": row_value(row, "preferences"),
        "notes": row_value(row, "notes"),
        "status": status,
        "statusLabel": status.replace("_", " ").title(),
        "isExpired": expired,
        "distanceMiles": route_metrics.get("pickupDistanceMiles"),
        "pickupDistanceMiles": route_metrics.get("pickupDistanceMiles"),
        "dropoffDistanceMiles": route_metrics.get("dropoffDistanceMiles"),
        "routeDeviationMiles": route_metrics.get("routeDeviationMiles"),
        "routeDeviationMinutes": route_metrics.get("routeDeviationMinutes"),
        "routeDeviationSource": route_metrics.get("routeDeviationSource"),
        "directionCompatible": bool(route_metrics.get("directionCompatible")),
        "matchScore": ride_score(row, origin_point, destination_point, allow_google=allow_google_routes),
        "createdAt": row_value(row, "created_at"),
    }


def ride_pickup_pin(request_public_id: str, driver_user_id: int) -> str:
    secret = application_secret()
    raw = f"{request_public_id}:{driver_user_id}:{secret}".encode("utf-8")
    value = int(hashlib.sha256(raw).hexdigest()[:8], 16) % 10000
    return f"{value:04d}"


def mobile_ride_driver_profile_payload(row: sqlite3.Row | None) -> dict[str, object]:
    if not row:
        return {
            "exists": False,
            "reviewStatus": "NOT_STARTED",
            "serviceTypes": [],
            "availabilityDays": [],
            "readyForOffers": False,
            "missing": [
                "Vehicle make/model",
                "License plate and state",
                "Insurance provider",
                "Service types",
            ],
        }
    service_types = [item.strip() for item in row_value(row, "service_types").split(",") if item.strip()]
    availability_days = [item.strip() for item in row_value(row, "availability_days").split(",") if item.strip()]
    missing = []
    if not row_value(row, "vehicle_make_model"):
        missing.append("Vehicle make/model")
    if not row_value(row, "license_plate") or not row_value(row, "license_state"):
        missing.append("License plate and state")
    if not row_value(row, "insurance_provider"):
        missing.append("Insurance provider")
    if not service_types:
        missing.append("Service types")
    review_status = row_value(row, "review_status") or "PENDING_REVIEW"
    return {
        "exists": True,
        "vehicleMakeModel": row_value(row, "vehicle_make_model"),
        "vehicleYear": row_value(row, "vehicle_year"),
        "vehicleColor": row_value(row, "vehicle_color"),
        "licensePlate": row_value(row, "license_plate"),
        "licenseState": row_value(row, "license_state"),
        "insuranceProvider": row_value(row, "insurance_provider"),
        "insurancePolicyLast4": row_value(row, "insurance_policy_last4"),
        "serviceTypes": service_types,
        "availabilityDays": availability_days,
        "availabilityStartTime": row_value(row, "availability_start_time"),
        "availabilityEndTime": row_value(row, "availability_end_time"),
        "seatCount": int(row_value(row, "seat_count") or 4),
        "luggageSpace": row_value(row, "luggage_space"),
        "maxDetourMinutes": int(row_value(row, "max_detour_minutes") or 15),
        "maxPickupDistanceMiles": float(row_value(row, "max_pickup_distance_miles") or 10),
        "reviewStatus": review_status,
        "reviewNotes": row_value(row, "review_notes"),
        "readyForOffers": not missing and review_status in {"PENDING_REVIEW", "APPROVED"},
        "missing": missing,
        "updatedAt": row_value(row, "updated_at"),
    }


def get_ride_driver_profile(user_id: int) -> dict[str, object]:
    with db() as con:
        row = con.execute("SELECT * FROM ride_driver_profiles WHERE user_id = ? LIMIT 1", (user_id,)).fetchone()
    return mobile_ride_driver_profile_payload(row)


def mobile_ride_posts(
    city: str = "",
    ride_type: str = "",
    origin: str = "",
    destination: str = "",
    limit: int = 30,
    origin_lat: float = 0,
    origin_lng: float = 0,
    destination_lat: float = 0,
    destination_lng: float = 0,
    offset: int = 0,
) -> list[dict[str, object]]:
    city = normalize_accommodation_place_label(city or "Denver, CO")
    ride_type = normalize_ride_type(ride_type) if ride_type else ""
    if origin_lat and origin_lng:
        origin_point = accommodation_location_point(origin or city, city, allow_refresh=False)
        if not origin_point or not float(origin_point.get("lat") or 0) or not float(origin_point.get("lng") or 0):
            origin_point = {"label": origin or city, "lat": float(origin_lat), "lng": float(origin_lng), "source": "CLIENT"}
    else:
        origin_point = ride_point(origin, city) if origin else ride_point(city)
    if destination_lat and destination_lng:
        destination_point = accommodation_location_point(destination, city, allow_refresh=False)
        if not destination_point or not float(destination_point.get("lat") or 0) or not float(destination_point.get("lng") or 0):
            destination_point = {"label": destination, "lat": float(destination_lat), "lng": float(destination_lng), "source": "CLIENT"}
    else:
        destination_point = ride_point(destination, city) if destination else {}
    if origin_lat and origin_lng:
        supplied_origin = {"lat": float(origin_lat), "lng": float(origin_lng)}
        resolved_origin_lat = float(origin_point.get("lat") or 0)
        resolved_origin_lng = float(origin_point.get("lng") or 0)
        discrepancy = (
            distance_miles_between(resolved_origin_lat, resolved_origin_lng, supplied_origin["lat"], supplied_origin["lng"])
            if resolved_origin_lat and resolved_origin_lng
            else 0
        )
        if not resolved_origin_lat or not resolved_origin_lng or discrepancy <= 75:
            origin_point = {**origin_point, **supplied_origin}
    if destination_lat and destination_lng:
        supplied_destination = {"lat": float(destination_lat), "lng": float(destination_lng)}
        resolved_destination_lat = float(destination_point.get("lat") or 0)
        resolved_destination_lng = float(destination_point.get("lng") or 0)
        discrepancy = (
            distance_miles_between(
                resolved_destination_lat,
                resolved_destination_lng,
                supplied_destination["lat"],
                supplied_destination["lng"],
            )
            if resolved_destination_lat and resolved_destination_lng
            else 0
        )
        if not resolved_destination_lat or not resolved_destination_lng or discrepancy <= 75:
            destination_point = {**destination_point, **supplied_destination}
    clauses = ["ride_posts.status = 'ACTIVE'"]
    values: list[object] = []
    route_search = bool(origin and destination)
    if ride_type:
        clauses.append("ride_posts.ride_type = ?")
        values.append(ride_type)
    # A rider may join and leave anywhere along a longer route. Restricting a
    # two-ended search to the offer's city label would discard valid midway
    # matches before route deviation can be calculated.
    if city and not route_search:
        city_root = city.split(",", 1)[0].strip()
        clauses.append("(lower(ride_posts.city_label) LIKE lower(?) OR lower(ride_posts.origin_label) LIKE lower(?) OR lower(ride_posts.destination_label) LIKE lower(?))")
        values.extend([f"%{city_root}%", f"%{city_root}%", f"%{city_root}%"])
    sql = f"""
        SELECT ride_posts.*, users.name AS owner_name
        FROM ride_posts
        LEFT JOIN users ON users.id = ride_posts.user_id
        WHERE {' AND '.join(clauses)}
        ORDER BY datetime(ride_posts.created_at) DESC
        LIMIT ? OFFSET ?
    """
    page_limit = max(1, min(int(limit or 30), 50))
    page_offset = max(0, int(offset or 0))
    candidate_limit = 250 if route_search else page_limit
    candidate_offset = 0 if route_search else page_offset
    values.extend([candidate_limit, candidate_offset])
    with db() as con:
        rows = con.execute(sql, values).fetchall()
    # Search results must not fan out into sequential Google Directions calls.
    # Fast coordinate estimates shortlist candidates; dispatch performs the
    # detailed route validation when a rider actually requests a match.
    payloads = [mobile_ride_payload(row, origin_point, destination_point, allow_google_routes=False) for row in rows]
    if origin or destination:
        if route_search:
            route_filtered = []
            for item in payloads:
                # A two-ended search is only a match when its route can actually
                # be evaluated. Missing metrics must not become an automatic hit.
                if ride_route_match_is_valid(item, item):
                    route_filtered.append(item)
            payloads = route_filtered
        payloads.sort(key=lambda item: (-int(item.get("matchScore") or 0), float(item.get("routeDeviationMiles") or 9999), float(item.get("distanceMiles") or 9999)))
    if route_search:
        payloads = payloads[page_offset:page_offset + page_limit]
    return payloads


def create_ride_instances(con: sqlite3.Connection, ride_post_id: int, start_date: str, end_date: str, days_of_week: str, pickup_time: str) -> None:
    if not start_date or not days_of_week:
        return
    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        return
    try:
        end = datetime.strptime(end_date, "%Y-%m-%d").date() if end_date else start + timedelta(days=30)
    except ValueError:
        end = start + timedelta(days=30)
    end = min(end, start + timedelta(days=120))
    selected_days = {item.strip().lower()[:3] for item in days_of_week.split(",") if item.strip()}
    day_names = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
    current = start
    while current <= end:
        if day_names[current.weekday()] in selected_days:
            con.execute(
                """
                INSERT OR IGNORE INTO ride_instances (ride_post_id, instance_date, pickup_time)
                VALUES (?, ?, ?)
                """,
                (ride_post_id, current.isoformat(), pickup_time),
            )
        current += timedelta(days=1)


def create_ride_dispatch_notifications(con: sqlite3.Connection, request_row: sqlite3.Row, requester_user_id: int) -> dict[str, object]:
    if row_value(request_row, "ride_type") not in {"SCHEDULED_REQUEST", "GENERAL_REQUEST", "CARPOOL_REQUEST"}:
        return {"notifiedCount": 0, "nearestRadius": 0, "radiusBuckets": []}
    request_lat = float(row_value(request_row, "origin_lat") or 0)
    request_lng = float(row_value(request_row, "origin_lng") or 0)
    request_dest_lat = float(row_value(request_row, "destination_lat") or 0)
    request_dest_lng = float(row_value(request_row, "destination_lng") or 0)
    if not request_lat or not request_lng:
        return {"notifiedCount": 0, "nearestRadius": 0, "radiusBuckets": []}
    request_origin_point = {"lat": request_lat, "lng": request_lng, "label": row_value(request_row, "origin_label")}
    request_destination_point = {"lat": request_dest_lat, "lng": request_dest_lng, "label": row_value(request_row, "destination_label")}
    today_iso = datetime.now(FAIRFARES_TZ).date().isoformat()
    driver_rows = con.execute(
        """
        SELECT *
        FROM ride_posts
        WHERE status = 'ACTIVE'
          AND ride_type = 'CARPOOL_OFFER'
          AND user_id != ?
          AND origin_lat != 0
          AND origin_lng != 0
          AND substr(COALESCE(NULLIF(pickup_date, ''), NULLIF(start_date, '')), 1, 10) >= ?
        """,
        (requester_user_id, today_iso),
    ).fetchall()
    buckets: list[dict[str, object]] = []
    notified_count = 0
    nearest_radius = 0
    notified_driver_user_ids: list[int] = []
    for radius in (10, 20, 30, 50):
        bucket_count = 0
        for driver in driver_rows:
            metrics = ride_route_match_metrics(driver, request_origin_point, request_destination_point)
            pickup_distance = float(metrics.get("pickupDistanceMiles") or 0)
            route_deviation_raw = metrics.get("routeDeviationMiles")
            route_deviation = float(route_deviation_raw) if route_deviation_raw is not None else 9999.0
            if not ride_route_match_is_valid(driver, metrics, maximum_miles=float(radius)):
                continue
            dropoff_distance = float(metrics.get("dropoffDistanceMiles") or 0)
            route_deviation_minutes = int(metrics.get("routeDeviationMinutes") or 0)
            cursor = con.execute(
                """
                INSERT OR IGNORE INTO ride_dispatch_notifications
                (request_ride_post_id, driver_ride_post_id, driver_user_id, radius_miles, distance_miles, dropoff_distance_miles, route_deviation_miles, route_deviation_minutes)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    int(row_value(request_row, "id") or 0),
                    int(row_value(driver, "id") or 0),
                    int(row_value(driver, "user_id") or 0),
                    radius,
                    round(pickup_distance, 2),
                    round(dropoff_distance, 2),
                    round(route_deviation, 2),
                    route_deviation_minutes,
                ),
            )
            if cursor.rowcount:
                bucket_count += 1
                notified_driver_user_ids.append(int(row_value(driver, "user_id") or 0))
        if bucket_count and not nearest_radius:
            nearest_radius = radius
        notified_count += bucket_count
        buckets.append({"radiusMiles": radius, "notifiedCount": bucket_count})
        if bucket_count:
            break
    return {
        "notifiedCount": notified_count,
        "nearestRadius": nearest_radius,
        "radiusBuckets": buckets,
        "driverUserIds": [user_id for user_id in dict.fromkeys(notified_driver_user_ids) if user_id],
    }


def apply_ride_dispatch_action(user_id: int, ride_public_id: str, action: str) -> tuple[int, dict[str, object]]:
    ride_public_id = clean_text_value(ride_public_id, 40)
    action = clean_text_value(action, 40).upper()
    allowed_actions = {"ACCEPT", "DECLINE", "EN_ROUTE", "ARRIVED", "COMPLETED"}
    if action not in allowed_actions:
        return 400, {"ok": False, "error": "Unsupported ride action."}
    with db() as con:
        request_row = con.execute("SELECT * FROM ride_posts WHERE public_id = ? LIMIT 1", (ride_public_id,)).fetchone()
        if not request_row:
            return 404, {"ok": False, "error": "Ride request was not found."}
        if ride_post_expired(request_row):
            return 409, {"ok": False, "error": "This ride date has passed."}
        notification = con.execute(
            """
            SELECT *
            FROM ride_dispatch_notifications
            WHERE request_ride_post_id = ?
              AND driver_user_id = ?
            LIMIT 1
            """,
            (int(row_value(request_row, "id") or 0), user_id),
        ).fetchone()
        if not notification:
            return 403, {"ok": False, "error": "This ride request is not assigned to your driver account."}
        current_status = str(row_value(notification, "status") or "PENDING").upper()
        next_status = "DECLINED" if action == "DECLINE" else "ACCEPTED" if action == "ACCEPT" else action
        valid_transitions = {
            "PENDING": {"ACCEPTED", "DECLINED"},
            "ACCEPTED": {"EN_ROUTE", "COMPLETED"},
            "EN_ROUTE": {"ARRIVED", "COMPLETED"},
            "ARRIVED": {"COMPLETED"},
            "COMPLETED": set(),
            "DECLINED": set(),
            "EXPIRED": set(),
        }
        if next_status not in valid_transitions.get(current_status, set()):
            return 409, {"ok": False, "error": f"Cannot change ride request from {current_status} to {next_status}."}
        con.execute(
            """
            UPDATE ride_dispatch_notifications
            SET status = ?, responded_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            (next_status, int(row_value(notification, "id") or 0)),
        )
        if next_status == "ACCEPTED":
            con.execute(
                """
                UPDATE ride_dispatch_notifications
                SET status = 'EXPIRED', responded_at = COALESCE(responded_at, CURRENT_TIMESTAMP)
                WHERE request_ride_post_id = ?
                  AND id != ?
                  AND status = 'PENDING'
                """,
                (int(row_value(request_row, "id") or 0), int(row_value(notification, "id") or 0)),
            )
            con.execute("UPDATE ride_posts SET status = 'ACCEPTED' WHERE id = ?", (int(row_value(request_row, "id") or 0),))
        elif next_status == "COMPLETED":
            con.execute("UPDATE ride_posts SET status = 'COMPLETED' WHERE id = ?", (int(row_value(request_row, "id") or 0),))
        updated = con.execute(
            """
            SELECT requests.*,
                   notifications.status AS dispatch_status,
                   notifications.radius_miles AS dispatch_nearest_radius,
                   notifications.distance_miles AS dispatch_distance_miles,
                   notifications.dropoff_distance_miles AS dispatch_dropoff_distance_miles,
                   notifications.route_deviation_miles AS dispatch_route_deviation_miles,
                   notifications.route_deviation_minutes AS dispatch_route_deviation_minutes,
                   notifications.notified_at AS dispatch_notified_at,
                   notifications.responded_at AS dispatch_responded_at
            FROM ride_dispatch_notifications notifications
            JOIN ride_posts requests ON requests.id = notifications.request_ride_post_id
            WHERE notifications.id = ?
            LIMIT 1
            """,
            (int(row_value(notification, "id") or 0),),
        ).fetchone()
        requester_user_id = int(row_value(request_row, "user_id") or 0)
        route_label = " → ".join(
            value for value in (
                clean_text_value(row_value(request_row, "origin_label") or row_value(request_row, "origin"), 90),
                clean_text_value(row_value(request_row, "destination_label") or row_value(request_row, "destination"), 90),
            ) if value
        )
        driver_profile = con.execute(
            "SELECT license_plate, license_state FROM ride_driver_profiles WHERE user_id = ? LIMIT 1",
            (user_id,),
        ).fetchone()
        vehicle_number = " ".join(
            value for value in (
                clean_text_value(row_value(driver_profile, "license_state"), 12) if driver_profile else "",
                clean_text_value(row_value(driver_profile, "license_plate"), 24) if driver_profile else "",
            ) if value
        )
    status_titles = {
        "ACCEPTED": "Carpool request accepted",
        "DECLINED": "Carpool request declined",
        "EN_ROUTE": "Your carpool driver is en route",
        "ARRIVED": "Your carpool driver has arrived",
        "COMPLETED": "Carpool ride completed",
    }
    send_mobile_push_for_users(
        [requester_user_id],
        status_titles.get(next_status, "Carpool request updated"),
        (f"Vehicle: {vehicle_number}. {route_label}" if next_status == "ARRIVED" and vehicle_number else route_label) or "Open FairFares to review your carpool activity.",
        {"type": "CARPOOL_STATUS", "rideId": ride_public_id, "status": next_status, "target": "activity"},
    )
    response = mobile_ride_payload(updated) if updated else mobile_ride_payload(request_row)
    response["activityRole"] = "DRIVER_NOTIFICATION"
    response["dispatchStatus"] = next_status
    response["dispatchNearestRadius"] = int(row_value(updated, "dispatch_nearest_radius") or row_value(notification, "radius_miles") or 0) if updated else int(row_value(notification, "radius_miles") or 0)
    response["pickupDistanceMiles"] = float(row_value(updated, "dispatch_distance_miles") or row_value(notification, "distance_miles") or 0) if updated else float(row_value(notification, "distance_miles") or 0)
    response["distanceMiles"] = response["pickupDistanceMiles"]
    response["dropoffDistanceMiles"] = float(row_value(updated, "dispatch_dropoff_distance_miles") or row_value(notification, "dropoff_distance_miles") or 0) if updated else float(row_value(notification, "dropoff_distance_miles") or 0)
    response["routeDeviationMiles"] = float(row_value(updated, "dispatch_route_deviation_miles") or row_value(notification, "route_deviation_miles") or 0) if updated else float(row_value(notification, "route_deviation_miles") or 0)
    response["routeDeviationMinutes"] = int(row_value(updated, "dispatch_route_deviation_minutes") or row_value(notification, "route_deviation_minutes") or 0) if updated else int(row_value(notification, "route_deviation_minutes") or 0)
    if next_status in {"ACCEPTED", "EN_ROUTE", "ARRIVED", "COMPLETED"}:
        response["pickupPin"] = ride_pickup_pin(ride_public_id, user_id)
    return 200, {"ok": True, "ride": response}


def mobile_car_payload(row: sqlite3.Row | dict[str, object]) -> dict[str, object]:
    public_fields = (
        "id", "name", "brand", "model", "year", "category", "type", "fuel_type",
        "seats", "bags", "doors", "transmission", "daily_price", "badge",
        "features", "location", "image_url", "booked_from_date", "booked_from_time", "booked_until_date", "booked_until_time",
        "listing_source", "review_status", "available_from_date", "available_to_date",
    )
    return {field: row_value(row, field) for field in public_fields}


def mobile_booking_payload(row: sqlite3.Row | dict[str, object]) -> dict[str, object]:
    breakdown = booking_price_breakdown(row)
    return {
        "id": row_value(row, "booking_id") or row_value(row, "id"),
        "carId": int(row_value(row, "car_id") or 0),
        "carName": row_value(row, "car_name"),
        "category": row_value(row, "category"),
        "pickupLocation": row_value(row, "pickup_location"),
        "pickupDate": row_value(row, "pickup_date"),
        "pickupTime": row_value(row, "pickup_time"),
        "returnLocation": row_value(row, "dropoff_location"),
        "returnDate": row_value(row, "dropoff_date"),
        "returnTime": row_value(row, "dropoff_time"),
        "days": int(row_value(row, "days") or 0),
        "dailyPrice": float(row_value(row, "daily_price") or 0),
        "total": breakdown.get("total"),
        "holdAmount": breakdown.get("booking_hold"),
        "dueAtPickup": breakdown.get("due_at_pickup"),
        "savings": breakdown.get("savings"),
        "status": row_value(row, "booking_status"),
        "paymentStatus": row_value(row, "payment_status"),
        "depositStatus": row_value(row, "security_deposit_status") or "NOT_AUTHORIZED",
        "depositAmount": float(row_value(row, "security_deposit_amount") or SECURITY_DEPOSIT_AMOUNT),
        "holdRemainingSeconds": booking_hold_remaining_seconds(row),
    }


def mobile_rental_upgrade_options(row: sqlite3.Row | dict[str, object]) -> list[dict[str, object]]:
    current_car_id = int(row_value(row, "car_id") or 0)
    requested_start = parse_booking_datetime(row_value(row, "pickup_date"), row_value(row, "pickup_time"))
    requested_end = parse_booking_datetime(row_value(row, "dropoff_date"), row_value(row, "dropoff_time"))
    days = int(row_value(row, "days") or 1)
    options: list[dict[str, object]] = []
    for car in get_cars():
        car_id = int(row_value(car, "id") or 0)
        if not car_id or car_id == current_car_id:
            continue
        if active_booking_conflict_for_car(car_id, requested_start, requested_end, int(row_value(row, "id") or 0)):
            continue
        daily = float(row_value(car, "daily_price") or 0)
        low, high = daily_price_range(daily)
        breakdown = rental_price_breakdown(daily, days, 0, 0)
        options.append(
            {
                "id": car_id,
                "name": row_value(car, "name"),
                "category": row_value(car, "category"),
                "dailyRange": f"${low}-{high}/day est.",
                "estimatedTotalLabel": format_money(breakdown["total"]),
            }
        )
    return options


def mobile_housing_post_summary(row: sqlite3.Row) -> dict[str, object]:
    return {
        "id": row_value(row, "public_id") or str(row_value(row, "id")),
        "title": row_value(row, "title"),
        "status": row_value(row, "visibility_status") or "ACTIVE",
        "expiryLabel": accommodation_expiry_label(row),
        "modeLabel": accommodation_mode_label(row),
        "categoryLabel": option_label(ACCOMMODATION_CATEGORIES, row_value(row, "category"), "Housing"),
        "location": row_value(row, "city_area_zip") or row_value(row, "area_or_apartment") or "Location open",
        "rent": format_accommodation_rent(row),
    }


def mobile_support_ticket_summary(row: sqlite3.Row) -> dict[str, object]:
    return {
        "ticketId": row_value(row, "ticket_id"),
        "topic": row_value(row, "topic") or "Support",
        "status": row_value(row, "status").replace("_", " ").title(),
        "priority": row_value(row, "priority") or "P3",
        "bookingId": row_value(row, "public_booking_id") or "No booking",
    }


def mobile_rental_service_booking_payload(
    row: sqlite3.Row | dict[str, object],
    origin: str = "",
    user_id: int | None = None,
    *,
    include_document_bodies: bool = False,
) -> dict[str, object]:
    payload = mobile_booking_payload(row)
    breakdown = booking_price_breakdown(row)
    booking_id = row_value(row, "booking_id") or row_value(row, "id")
    latest_transaction = None
    document_sets: list[dict[str, object]] = []
    support_tickets: list[dict[str, object]] = []
    housing_posts: list[dict[str, object]] = []
    service_user = None
    stats = {
        "upcoming": 0,
        "past": 0,
        "saved": 0,
        "housingActive": 0,
        "housingExpired": 0,
        "supportOpen": 0,
    }
    active_booking_id = int(row_value(row, "id") or 0)
    if user_id:
        user_bookings = get_bookings_for_user(user_id)
        saved_cars = get_saved_cars_for_user(user_id)
        stats["upcoming"] = sum(1 for booking in user_bookings if row_value(booking, "booking_status") not in {"CANCELLED", "RETURNED", "EXPIRED_HOLD"})
        stats["past"] = sum(1 for booking in user_bookings if row_value(booking, "booking_status") in {"CANCELLED", "RETURNED", "EXPIRED_HOLD"})
        stats["saved"] = len(saved_cars)
        document_sets = get_user_document_sets(user_id, active_booking_id, include_docs=include_document_bodies)
        if not include_document_bodies:
            document_sets = [item for item in document_sets if int(item.get("id") or 0) == active_booking_id]
        support_rows = get_support_tickets_for_user(user_id)
        support_tickets = [mobile_support_ticket_summary(ticket) for ticket in support_rows]
        stats["supportOpen"] = sum(1 for ticket in support_rows if row_value(ticket, "status") not in {"RESOLVED", "CLOSED"})
        post_rows = get_accommodation_posts_for_user(user_id)
        stats["housingActive"] = sum(1 for post in post_rows if row_value(post, "visibility_status") == "ACTIVE" and accommodation_expiry_label(post) != "Expired")
        stats["housingExpired"] = sum(1 for post in post_rows if accommodation_expiry_label(post) == "Expired")
        housing_posts = [mobile_housing_post_summary(post) for post in post_rows[:12]]
        with db() as con:
            service_user = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
    with db() as con:
        latest_transaction = con.execute(
            """
            SELECT invoice_number, invoice_pdf_url
            FROM transactions
            WHERE booking_id = ?
            ORDER BY id DESC
            LIMIT 1
            """,
            (int(row_value(row, "id") or 0),),
        ).fetchone()
    manage_url = f"/manage-booking?booking_id={urllib.parse.quote(str(booking_id))}"
    if origin:
        manage_url = f"{origin.rstrip('/')}{manage_url}"
    refund_amount, refund_note = booking_refund_estimate(row)
    current_doc = next((item for item in document_sets if int(item.get("id") or 0) == active_booking_id), None)
    documents_locked = bool(current_doc.get("locked")) if current_doc else row_value(row, "booking_status") not in {"PICKED_UP", "RETURNED", "CANCELLED"}
    payload.update(
        {
            "statusLabel": booking_status_label(row_value(row, "booking_status"), row_value(row, "payment_status")),
            "paymentLabel": payment_status_label(row_value(row, "payment_status")),
            "depositLabel": str(row_value(row, "security_deposit_status") or "NOT_AUTHORIZED").replace("_", " ").title(),
            "totalLabel": format_money(breakdown.get("total")),
            "dueNowLabel": format_money(breakdown.get("booking_hold")),
            "dueAtPickupLabel": format_money(breakdown.get("due_at_pickup")),
            "invoiceNumber": row_value(latest_transaction, "invoice_number") if latest_transaction else "",
            "invoiceUrl": row_value(latest_transaction, "invoice_pdf_url") if latest_transaction else "",
            "manageUrl": manage_url,
            "locations": get_inventory_locations(),
            "upgradeOptions": mobile_rental_upgrade_options(row),
            "refund": {
                "amount": refund_amount,
                "amountLabel": format_money(refund_amount),
                "note": refund_note,
            },
            "documents": document_sets,
            "documentsLocked": documents_locked,
            "documentsLockedMessage": (current_doc or {}).get("lockMessage") or "Documents can be retrieved once pickup is completed.",
            "liveStatus": live_status_for_booking(row),
            "student": {
                "email": row_value(service_user, "student_email") if service_user else "",
                "id": row_value(service_user, "student_id") if service_user else "",
                "verified": str(row_value(service_user, "student_verified") or "0") in {"1", "true", "True"},
                "statusLabel": "Student verified" if service_user and str(row_value(service_user, "student_verified") or "0") in {"1", "true", "True"} else "Student Verification Pending",
                "discountLabel": "10% OFF" if service_user and str(row_value(service_user, "student_verified") or "0") in {"1", "true", "True"} else "0% OFF",
            },
            "stats": stats,
            "housingPosts": housing_posts,
            "supportTickets": support_tickets,
        }
    )
    return payload


def mobile_rental_policy_payload(row: sqlite3.Row | dict[str, object] | None = None) -> dict[str, object]:
    timeline = cancellation_policy_timeline(row) if row else {
        "day_label": "Calculated after pickup date",
        "cutoff_copy": "Cancel before the 24-hour pickup cutoff for automatic review when eligible.",
        "day_ticks": [],
    }
    return {
        "securityDepositAmount": SECURITY_DEPOSIT_AMOUNT,
        "securityDepositCopy": SECURITY_DEPOSIT_RELEASE_COPY,
        "additionalDriverDailyFee": ADDITIONAL_DRIVER_DAILY_FEE,
        "holdMinutes": BOOKING_HOLD_MINUTES,
        "fullPaymentDiscountAmount": FULL_PAYMENT_DISCOUNT_AMOUNT,
        "cancellation": timeline,
        "bullets": [
            "Bring a valid driver license and proof of insurance before vehicle release.",
            "Pay 10% now to hold the car, or pay in full for faster pickup and eligible savings.",
            "Pickup balance, refundable deposit authorization, tolls, fuel, cleaning, tickets, and damage are reviewed by policy.",
        ],
    }


def mobile_rental_quote_payload(row: sqlite3.Row | dict[str, object]) -> dict[str, object]:
    breakdown = booking_price_breakdown(row)
    return {
        "booking": mobile_booking_payload(row),
        "breakdown": {
            "daily": breakdown.get("daily"),
            "effectiveDaily": breakdown.get("effective_daily"),
            "days": breakdown.get("days"),
            "standardBase": breakdown.get("standard_base"),
            "base": breakdown.get("base"),
            "durationDiscountLabel": breakdown.get("duration_discount_label"),
            "durationDiscountAmount": breakdown.get("duration_discount_amount"),
            "additionalDriverFeeAmount": breakdown.get("additional_driver_fee_amount"),
            "taxFeeAmount": breakdown.get("tax_fee_amount"),
            "taxFeeLines": [{"label": label, "amount": amount} for label, amount in breakdown.get("tax_fee_lines", [])],
            "discountAmount": breakdown.get("discount_amount"),
            "total": breakdown.get("total"),
            "holdAmount": breakdown.get("booking_hold"),
            "dueAtPickup": breakdown.get("due_at_pickup"),
            "marketTotal": breakdown.get("market_total"),
            "savings": breakdown.get("savings"),
            "fullPaymentTotal": full_payment_total(breakdown.get("total")),
        },
        "policy": mobile_rental_policy_payload(row),
        "checkoutUrl": "/manage-booking",
    }


def mobile_housing_posts(
    city: str = "",
    area: str = "",
    need: str = "",
    category: str = "",
    gender: str = "",
    budget: str = "",
    radius: float = 0,
    limit: int = 30,
    center_lat: float = 0,
    center_lng: float = 0,
    offset: int = 0,
) -> list[dict[str, object]]:
    expire_accommodation_posts(force=False)
    clauses = [
        "visibility_status = 'ACTIVE'",
        "(expires_at IS NULL OR expires_at = '' OR datetime(expires_at) > datetime('now'))",
        "COALESCE(source_label, '') != 'SAMPLE_DATA'",
    ]
    values: list[object] = []
    if need == "need_place":
        clauses.append("post_mode = 'HAVE_PLACE'")
    elif need == "have_place":
        clauses.append("post_mode = 'NEED_PLACE'")
    elif need == "need_roommates":
        clauses.append("(post_mode = 'HAVE_PLACE' OR roommate_intent = 1)")
    if category:
        clauses.append("category = ?")
        values.append(category)
    if gender:
        clauses.append("(gender_preference = ? OR gender_preference IN ('open', 'no_preference'))")
        values.append(gender)
    budget_value = float_from_value(budget)
    if budget_value:
        clauses.append("(rent_max = 0 OR rent_max <= ? OR rent_min <= ?)")
        values.extend([budget_value, budget_value])
    search_term_groups: list[list[str]] = []
    raw_search_terms = () if (area or "").strip() else (city,)
    for raw_term in raw_search_terms:
        term = (raw_term or "").strip()
        if not term:
            continue
        candidates = {term, term.replace(", ", ","), term.replace(",", ", ")}
        if "," in term:
            candidates.add(term.split(",", 1)[0].strip())
        group = [candidate for candidate in candidates if candidate]
        if group:
            search_term_groups.append(group)
    search_fields = (
        "city_area_zip",
        "area_or_apartment",
        "work_school_location",
        "description",
        "street_address",
        "city",
        "zip_code",
        "primary_neighborhood",
        "apartment_name",
    )
    def row_matches_terms(row: sqlite3.Row, terms: list[str]) -> bool:
        if not terms:
            return False
        haystack = " ".join(row_value(row, field) for field in search_fields).lower()
        return any(term.lower() in haystack for term in terms if term)

    for group in search_term_groups:
        term_clauses = []
        for term in group:
            pattern = f"%{term}%"
            term_clauses.append("(" + " OR ".join(f"{field} LIKE ?" for field in search_fields) + ")")
            values.extend([pattern] * len(search_fields))
        clauses.append("(" + " OR ".join(term_clauses) + ")")
    limit = max(1, min(int(limit or 30), 50))
    offset = max(0, int(offset or 0))
    # Area searches need a bounded candidate window for distance ranking. Plain
    # city searches can page directly in SQLite.
    sql_limit = min(100, offset + limit) if area else limit
    sql_offset = 0 if area else offset
    where_sql = " AND ".join(clauses)
    with db() as con:
        rows = con.execute(
            f"""
            WITH first_images AS (
                SELECT post_id, image_url
                FROM (
                    SELECT post_id, image_url,
                           ROW_NUMBER() OVER (PARTITION BY post_id ORDER BY sort_order ASC, id ASC) AS image_rank
                    FROM accommodation_post_images
                )
                WHERE image_rank = 1
            )
            SELECT accommodation_posts.*,
                   users.name AS owner_name,
                   first_images.image_url AS preview_image_url
            FROM accommodation_posts
            LEFT JOIN users ON users.id = accommodation_posts.user_id
            LEFT JOIN first_images ON first_images.post_id = accommodation_posts.id
            WHERE {where_sql}
            ORDER BY datetime(accommodation_posts.created_at) DESC
            LIMIT ? OFFSET ?
            """,
            (*values, sql_limit, sql_offset),
        ).fetchall()
    search_radius_miles = float_from_value(radius) or 0
    if search_radius_miles < 0:
        search_radius_miles = 0
    if search_radius_miles > 100:
        search_radius_miles = 100
    focus_query = area or city
    center = accommodation_location_point(focus_query, cached_accommodation_metro_for_place(focus_query), allow_refresh=False)
    center_lat = float(center_lat or center.get("lat") or 0)
    center_lng = float(center_lng or center.get("lng") or 0)
    area_terms: list[str] = []
    if area:
        area_terms = [area, area.replace(", ", ","), area.replace(",", ", ")]
        if "," in area:
            area_terms.append(area.split(",", 1)[0].strip())
        area_terms = [term for term in dict.fromkeys(term for term in area_terms if term)]
    city_terms: list[str] = []
    if city:
        city_terms = [city, city.replace(", ", ","), city.replace(",", ", ")]
        if "," in city:
            city_terms.append(city.split(",", 1)[0].strip())
        city_terms = [term for term in dict.fromkeys(term for term in city_terms if term)]
    ranked_payloads: list[tuple[int, float, dict[str, object]]] = []
    for row in rows:
        item = mobile_housing_post_payload(row)
        lat = float(row_value(row, "lat") or 0)
        lng = float(row_value(row, "lng") or 0)
        distance = None
        if center_lat and center_lng and lat and lng:
            distance = round(distance_miles_between(center_lat, center_lng, lat, lng), 1)
            item["distanceMiles"] = distance
        if area:
            area_match = row_matches_terms(row, area_terms)
            city_match = row_matches_terms(row, city_terms)
            nearby_limit = search_radius_miles or 60
            nearby_match = distance is not None and distance <= nearby_limit
            requested_city = (city.split(",", 1)[0] if city else "").strip().lower()
            listing_city = (row_value(row, "city").split(",", 1)[0] if row_value(row, "city") else "").strip().lower()
            selected_area_text = area.lower()
            city_consistent = (
                not requested_city
                or not listing_city
                or requested_city == listing_city
                or listing_city in selected_area_text
            )
            if center_lat and center_lng:
                # A geocoded place search is radius-bound. Text matches must not
                # bypass distance, and listings tagged to another city are excluded
                # even when their stored coordinates are stale or incorrect.
                if not nearby_match or not city_consistent:
                    continue
                rank = 0 if area_match else 1
            else:
                if not (area_match or city_match):
                    continue
                rank = 0 if area_match else 2
        else:
            rank = 0
        ranked_payloads.append((rank, float(item.get("distanceMiles") if item.get("distanceMiles") is not None else 9999), item))
    ranked_payloads.sort(key=lambda entry: (entry[0], entry[1]))
    ranked_page = ranked_payloads[offset:offset + limit] if area else ranked_payloads[:limit]
    matched_posts = [item for _, _, item in ranked_page]
    sample_limit = max(0, limit - len(matched_posts)) if offset == 0 else 0
    sample_posts = mobile_sample_housing_posts(
        city=city,
        area=area,
        need=need,
        category=category,
        gender=gender,
        budget=budget,
        radius=radius,
        center_lat=center_lat,
        center_lng=center_lng,
        limit=sample_limit,
    )
    return [*matched_posts, *sample_posts]


