def mobile_sample_housing_posts(
    city: str = "",
    area: str = "",
    need: str = "",
    category: str = "",
    gender: str = "",
    budget: str = "",
    radius: float = 0,
    center_lat: float = 0,
    center_lng: float = 0,
    limit: int = 10,
) -> list[dict[str, object]]:
    """Return location-aware FairFares housing cards after live local results."""
    if int(limit or 0) <= 0:
        return []
    with db() as con:
        sample_owner = con.execute(
            "SELECT id, name FROM users WHERE lower(email) = lower(?) AND guest_account = 0 LIMIT 1",
            (SAMPLE_HOUSING_OWNER_EMAIL,),
        ).fetchone()
    sample_owner_id = int(row_value(sample_owner, "id") or 0) if sample_owner else 0
    sample_owner_name = (
        row_value(sample_owner, "name") or SAMPLE_HOUSING_OWNER_NAME
        if sample_owner
        else SAMPLE_HOUSING_OWNER_NAME
    )
    selected_location = " ".join((area or city or "your selected location").split())[:120]
    mode = "NEED_PLACE" if need == "have_place" else "HAVE_PLACE"
    mode_label = "Looking for a place" if mode == "NEED_PLACE" else "Place available"
    selected_budget = int(float_from_value(budget) or 0)
    location_key = hashlib.sha256(f"{selected_location}|{need}|{category}".encode()).hexdigest()[:10].upper()
    move_in_base = datetime.utcnow().date() + timedelta(days=7)
    max_distance = max(0.5, min(10.0, float_from_value(radius) or 10.0))
    samples: list[dict[str, object]] = []
    for index, variant in enumerate(SAMPLE_HOUSING_VARIANTS[:max(0, min(10, int(limit or 10)))]):
        title, default_category, base_rent, bath, lease, accommodates, roommate_count, amenities = variant
        sample_category = category or default_category
        rent_value = min(base_rent, selected_budget) if selected_budget else base_rent
        rent_value = max(350, rent_value)
        image_index = index % len(SAMPLE_HOUSING_IMAGES)
        images = [SAMPLE_HOUSING_IMAGES[image_index]]
        if index == 0:
            images.append(SAMPLE_HOUSING_IMAGES[1])
        lat_offset = ((index % 5) - 2) * 0.008
        lng_offset = ((index // 5) * 0.012) - 0.006
        samples.append(
            {
                "id": f"FFH-DEMO-{location_key}-{index + 1:02d}",
                "title": title,
                "description": f"Housing option near {selected_location}. Message the FairFares poster to confirm current availability and exact details.",
                "mode": mode,
                "modeLabel": mode_label,
                "category": sample_category,
                "categoryLabel": option_label(ACCOMMODATION_CATEGORIES, sample_category, "Housing"),
                "location": selected_location,
                "area": f"Near {selected_location}",
                "workLocation": selected_location,
                "moveIn": (move_in_base + timedelta(days=index * 3)).isoformat(),
                "rent": f"${rent_value:,} / monthly",
                "rentValue": rent_value,
                "radiusMiles": 10,
                "distanceMiles": round(0.3 + ((index + 1) * max_distance / 11), 1),
                "lat": float(center_lat or 0) + lat_offset if center_lat else 0,
                "lng": float(center_lng or 0) + lng_offset if center_lng else 0,
                "imageUrl": images[0],
                "images": images,
                "posterName": sample_owner_name,
                "posterEmail": SAMPLE_HOUSING_OWNER_EMAIL,
                "posterUserId": sample_owner_id,
                "daysLeft": 30,
                "expiryLabel": "30 days left",
                "roommateIntent": bool(roommate_count),
                "genderPreference": option_label(ACCOMMODATION_GENDER_OPTIONS, gender, "Open") if gender else "Open",
                "leaseTerm": lease,
                "bathroomType": bath,
                "accommodates": accommodates,
                "roommateCount": roommate_count,
                "amenities": [item.strip() for item in amenities.split(",")],
                "sample": False,
            }
        )
    return samples


def accommodation_metro_context(search_metro: str, search_area: str) -> dict[str, str]:
    if search_area:
        refreshed = cached_accommodation_metro_for_place(search_area) or refresh_accommodation_location_cache(search_area)
        search_metro = search_metro or refreshed
    elif search_metro and search_metro not in {row[0] for row in accommodation_metro_filter_options()}:
        search_metro = refresh_accommodation_location_cache(search_metro) or search_metro
    metro_name = search_metro or "Denver Metro Area"
    try:
        with db() as con:
            metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", (metro_name,)).fetchone()
            if not metro:
                metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", ("Denver Metro Area",)).fetchone()
            if metro:
                metro_name = row_value(metro, "name", "Denver Metro Area")
                area_rows = con.execute(
                    """
                    SELECT * FROM accommodation_local_areas
                    WHERE metro_id = ?
                    ORDER BY CASE place_type WHEN 'ZIP' THEN 2 ELSE 1 END, name ASC
                    """,
                    (metro["id"],),
                ).fetchall()
            else:
                area_rows = []
    except sqlite3.Error:
        area_rows = []
    suggested = tuple(row_value(row, "name") for row in area_rows if row_value(row, "place_type") != "ZIP")[:18]
    zips = tuple(row_value(row, "zip_code") or row_value(row, "name") for row in area_rows if row_value(row, "place_type") == "ZIP")[:12]
    if not suggested:
        suggested = tuple(ACCOMMODATION_METRO_GROUPS["Denver Metro Area"]["suggested"])
    if not zips:
        zips = tuple(ACCOMMODATION_METRO_GROUPS["Denver Metro Area"]["zips"])
    return {
        "selected_location": search_area or "Denver, CO",
        "suggested_location": suggested[0] if suggested else "Denver, CO",
        "suggested_place_chips": render_accommodation_place_chips(suggested, search_area),
        "zip_chips": render_accommodation_place_chips(zips, search_area),
        "metro_list": render_accommodation_metro_list(metro_name),
        "top_city_chips": render_accommodation_place_chips(
            (
                "Austin",
                "Bay Area",
                "Chicago",
                "Dallas",
                "Los Angeles",
                "New Jersey",
                "New York",
                "Philadelphia",
                "Seattle",
                "Toronto",
                "Washington",
            ),
            search_area,
        ),
        "top_city_rows": render_accommodation_place_chips(
            (
                "San Jose, CA, US",
                "San Francisco, CA, US",
                "Chicago, IL, US",
                "New York, NY, US",
                "Edison, NJ, US",
                "Los Angeles, CA, US",
                "Houston, TX, US",
                "San Diego, CA, US",
            ),
            search_area,
        ),
    }


def accommodation_location_options(query: str, area: str = "", limit: int = 18) -> dict[str, object]:
    query = normalize_accommodation_place_label(query)
    area = normalize_accommodation_place_label(area)
    google_enabled = bool(
        os.environ.get("GOOGLE_PLACES_API_KEY", "").strip()
        or os.environ.get("GOOGLE_MAPS_API_KEY", "").strip()
    )
    autocomplete_suggestions = google_accommodation_place_suggestions(query, area, limit=limit) if google_enabled else []
    google_refreshed_metro = refresh_accommodation_location_cache(query, force=True) if google_enabled else ""
    metro_name = google_refreshed_metro or cached_accommodation_metro_for_place(query) or refresh_accommodation_location_cache(query)
    fallback_from_group = False
    if not metro_name:
        metro_name = accommodation_metro_name_from_place(query) if query else "Denver Metro Area"
    suggested: list[str] = []
    zips: list[str] = []
    try:
        with db() as con:
            metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", (metro_name,)).fetchone()
            if not metro and query:
                city = query.split(",", 1)[0].strip()
                metro = con.execute(
                    """
                    SELECT DISTINCT metro.*
                    FROM accommodation_metros metro
                    JOIN accommodation_local_areas area ON area.metro_id = metro.id
                    WHERE lower(area.name) LIKE lower(?) OR lower(area.city) = lower(?)
                    LIMIT 1
                    """,
                    (f"%{city}%", city),
                ).fetchone()
            if not metro and metro_name in ACCOMMODATION_METRO_GROUPS:
                fallback_group = ACCOMMODATION_METRO_GROUPS[metro_name]
                sample_place = next(iter(fallback_group.get("suggested", ()) or (metro_name,)), metro_name)
                _, state = split_city_state(str(sample_place))
                metro_lat, metro_lng = static_accommodation_point(metro_name)
                metro_id = upsert_accommodation_metro(con, metro_name, state=state, lat=metro_lat, lng=metro_lng, source="STATIC_FALLBACK", raw={"mobile_seed": True})
                for place in fallback_group.get("suggested", ()):
                    city, place_state = split_city_state(str(place))
                    place_lat, place_lng = static_accommodation_point(str(place))
                    upsert_accommodation_local_area(con, metro_id, str(place), city=city, state=place_state or state, place_type="LOCALITY", lat=place_lat, lng=place_lng)
                for zip_code in fallback_group.get("zips", ()):
                    upsert_accommodation_local_area(con, metro_id, str(zip_code), zip_code=str(zip_code), state=state, place_type="ZIP")
                fallback_from_group = True
                metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", (metro_name,)).fetchone()
            if not metro and not query:
                metro = con.execute("SELECT * FROM accommodation_metros WHERE name = ?", ("Denver Metro Area",)).fetchone()
            if metro:
                metro_name = row_value(metro, "name", metro_name)
                rows = con.execute(
                    """
                    SELECT name, city, state, zip_code, place_type
                    FROM accommodation_local_areas
                    WHERE metro_id = ?
                    ORDER BY CASE place_type WHEN 'ZIP' THEN 2 ELSE 1 END, name ASC
                    """,
                    (int(row_value(metro, "id") or 0),),
                ).fetchall()
                for row in rows:
                    place_type = str(row_value(row, "place_type") or "")
                    if place_type == "ZIP":
                        value = str(row_value(row, "zip_code") or row_value(row, "name") or "").strip()
                        if value and value not in zips:
                            zips.append(value)
                    else:
                        value = dedupe_repeated_location_label(str(row_value(row, "name") or "")).strip()
                        if value and keep_mobile_accommodation_suggestion(value) and value not in suggested:
                            suggested.append(value)
    except sqlite3.Error:
        suggested = []
        zips = []
    if not suggested and metro_name in ACCOMMODATION_METRO_GROUPS:
        fallback_group = ACCOMMODATION_METRO_GROUPS.get(metro_name) or ACCOMMODATION_METRO_GROUPS.get("Denver Metro Area", {})
        suggested = [str(item) for item in fallback_group.get("suggested", ())][:limit]
        zips = [str(item) for item in fallback_group.get("zips", ())][:12]
    if autocomplete_suggestions:
        merged: list[str] = []
        for value in autocomplete_suggestions + suggested:
            value = dedupe_repeated_location_label(value).strip()
            if value and keep_mobile_accommodation_suggestion(value) and value not in merged:
                merged.append(value)
        suggested = merged
    point = accommodation_location_point(query or metro_name, metro_name, allow_refresh=False)
    return {
        "ok": True,
        "metro": metro_name,
        "selectedLocation": dedupe_repeated_location_label(str(point.get("label") or query or metro_name)),
        "cities": accommodation_city_suggestions(query),
        "suggested": suggested[:limit],
        "zips": zips[:12],
        "googlePlacesEnabled": google_enabled,
        "source": "google" if google_refreshed_metro else "static" if fallback_from_group else str(point.get("source") or "cache"),
    }


def int_from_form(form: dict[str, str], key: str, default: int = 0) -> int:
    try:
        return int((form.get(key) or "").strip())
    except (TypeError, ValueError):
        return default


def float_from_form(form: dict[str, str], key: str, default: float = 0.0) -> float:
    try:
        value = (form.get(key) or "").strip().replace("$", "").replace(",", "")
        return float(value) if value else default
    except (TypeError, ValueError):
        return default


def float_from_value(value: object, default: float = 0.0) -> float:
    try:
        cleaned = str(value or "").strip().replace("$", "").replace(",", "")
        return float(cleaned) if cleaned else default
    except (TypeError, ValueError):
        return default


def checked_from_form(form: dict[str, str], key: str) -> int:
    return 1 if (form.get(key) or "").strip().lower() in {"1", "on", "true", "yes"} else 0


def format_accommodation_rent(row: sqlite3.Row | dict[str, object]) -> str:
    rent_min = float(row_value(row, "rent_min") or 0)
    rent_max = float(row_value(row, "rent_max") or 0)
    period = option_label(ACCOMMODATION_RENT_PERIODS, row_value(row, "rent_period"), "monthly").lower()
    if rent_min and rent_max and rent_min != rent_max:
        return f"${rent_min:,.0f}-${rent_max:,.0f} / {period}"
    if rent_max:
        return f"Up to ${rent_max:,.0f} / {period}"
    if rent_min:
        return f"From ${rent_min:,.0f} / {period}"
    return "Rent open"


def accommodation_mode_label(row: sqlite3.Row | dict[str, object]) -> str:
    if row_value(row, "roommate_intent") == "1":
        return "Need roommates"
    return "Need a place" if row_value(row, "post_mode") == "NEED_PLACE" else "Place available"


def accommodation_feed_action_label(row: sqlite3.Row | dict[str, object]) -> str:
    if row_value(row, "roommate_intent") == "1":
        return "Roommate request"
    return "Request made" if row_value(row, "post_mode") == "NEED_PLACE" else "Listing posted"


def accommodation_title_from_form(form: dict[str, str], mode: str, category_label: str, roommate_intent: bool = False) -> str:
    custom_title = (form.get("title") or "").strip()
    if custom_title:
        return custom_title
    area = (
        form.get("primary_neighborhood")
        or form.get("apartment_name")
        or form.get("area_or_apartment")
        or form.get("city")
        or form.get("city_area_zip")
        or form.get("work_school_location")
        or ""
    ).strip()
    if roommate_intent:
        return f"Looking for roommates{f' near {area}' if area else ''}"
    if mode == "HAVE_PLACE":
        return f"{category_label} available{f' in {area}' if area else ''}"
    target = area or "your preferred area"
    return f"Looking for {category_label.lower()} near {target}"


def render_accommodation_posts(posts: list[sqlite3.Row]) -> str:
    if not posts:
        return """
        <div class="housing-empty">
          <span>Housing board</span>
          <h3>No live FairFares housing posts yet.</h3>
          <p>Use the form above to post a room, shared rent, short stay, or roommate need.</p>
        </div>
        """
    cards: list[str] = []
    for post in posts:
        mode_label = accommodation_mode_label(post)
        category = option_label(ACCOMMODATION_CATEGORIES, row_value(post, "category"), "Housing")
        city = row_value(post, "city_area_zip") or row_value(post, "area_or_apartment") or "Area open"
        move_in = row_value(post, "move_in_date") or "Flexible"
        fit = option_label(ACCOMMODATION_GENDER_OPTIONS, row_value(post, "gender_preference"), "Open fit")
        amenities = [item.strip() for item in row_value(post, "amenities").split(",") if item.strip()]
        chips = amenities[:3]
        for key, label in (("private_bath", "Private bath"), ("furnished", "Furnished"), ("parking", "Parking")):
            if row_value(post, key) == "1":
                chips.append(label)
        chips_html = "".join(f"<span>{escape(chip)}</span>" for chip in chips[:5])
        public_id = row_value(post, "public_id")
        image_url = public_upload_url(row_value(post, "preview_image_url"))
        media_html = (
            f'<img class="housing-post-media" src="{escape(image_url)}" alt="{escape(row_value(post, "title") or "Housing listing")}" loading="lazy">'
            if image_url
            else '<div class="housing-post-media housing-post-media-empty" role="img" aria-label="Photos coming soon"><span aria-hidden="true">⌂</span><strong>Photos coming soon</strong><small>Housing preview</small></div>'
        )
        cards.append(
            f"""
            <article class="housing-post-card" data-housing-detail-id="{escape(public_id)}" tabindex="0" aria-label="View details for {escape(row_value(post, 'title'))}">
              {media_html}
              <div class="housing-post-top">
                <span class="housing-mode-badge">{escape(mode_label)}</span>
                <span>{escape(category)}</span>
              </div>
              <h3>{escape(row_value(post, "title"))}</h3>
              <p>{escape(row_value(post, "description"))}</p>
              <dl>
                <div><dt>Area</dt><dd>{escape(city)}</dd></div>
                <div><dt>Move-in</dt><dd>{escape(move_in)}</dd></div>
                <div><dt>Budget/Rent</dt><dd>{escape(format_accommodation_rent(post))}</dd></div>
                <div><dt>Fit</dt><dd>{escape(fit)}</dd></div>
              </dl>
              <div class="housing-chips">{chips_html}</div>
              <div class="housing-card-actions">
                <button class="housing-card-details" type="button" data-housing-card-details="{escape(public_id)}">View details</button>
                <button class="housing-card-action" type="button" data-chat-open data-post-id="{escape(public_id)}" data-chat-subject="{escape(row_value(post, "title"))}">Message</button>
              </div>
            </article>
            """
        )
    return "\n".join(cards)


