def festival_campaign_for_day(value: date) -> dict[str, str] | None:
    dates = dict(FESTIVAL_MOVING_DATES.get(value.year, {}))
    dates.update({"republic-day": (1, 26), "independence-day": (8, 15), "christmas": (12, 25)})
    for slug, (month, day) in dates.items():
        if (value.month, value.day) == (month, day):
            campaign = FESTIVAL_CAMPAIGNS[slug]
            return {
                "slug": slug,
                "title": f"🎉 Happy {campaign['name']} from FairFares!",
                "body": "✨ Celebrate with fairer fares—explore housing, shared rides, and rental deals near you.",
                "target": "housing",
                "image_path": f"/static/img/notifications/festivals/{campaign['image']}",
            }
    return None


def queue_promotional_campaign(campaign: dict[str, str], campaign_key: str) -> dict[str, object]:
    with db() as con:
        rows = con.execute(
            """
            SELECT DISTINCT users.id
            FROM users
            JOIN mobile_push_tokens ON mobile_push_tokens.user_id = users.id AND mobile_push_tokens.enabled = 1
            WHERE users.is_verified = 1
              AND users.promo_email_opt_in = 1
              AND users.marketing_unsubscribed_at IS NULL
              AND NOT EXISTS (
                SELECT 1 FROM mobile_promo_push_sends sends
                WHERE sends.campaign_key = ? AND sends.user_id = users.id
              )
            ORDER BY users.id
            LIMIT 2000
            """,
            (campaign_key,),
        ).fetchall()
        user_ids = [int(row_value(row, "id") or 0) for row in rows if int(row_value(row, "id") or 0)]
        if user_ids:
            con.executemany(
                "INSERT OR IGNORE INTO mobile_promo_push_sends (campaign_key, user_id) VALUES (?, ?)",
                [(campaign_key, user_id) for user_id in user_ids],
            )
    if user_ids:
        send_mobile_push_for_users(
            user_ids,
            campaign["title"],
            campaign["body"],
            {
                "type": "FAIRFARES_PROMO",
                "campaign": campaign["slug"],
                "target": campaign["target"],
                "imageUrl": f"{schema_origin()}{campaign['image_path']}",
            },
        )
    return {"sent": len(user_ids), "campaign": campaign["slug"], "status": "queued" if user_ids else "already sent"}


def run_promotional_push_automation(now: datetime | None = None) -> dict[str, object]:
    """Send at most one useful promotional push per opted-in user each week."""
    now = now or datetime.now()
    festival_campaign = festival_campaign_for_day(now.date())
    if festival_campaign:
        return queue_promotional_campaign(festival_campaign, f"festival-{festival_campaign['slug']}-{now.year}")
    week_number = int(now.strftime("%V"))
    rotation = week_number % 3
    with db() as con:
        cheapest_car = con.execute(
            """
            SELECT name, daily_price
            FROM cars
            WHERE UPPER(TRIM(status)) = 'AVAILABLE'
              AND daily_price > 0
            ORDER BY daily_price ASC, sort_order ASC, id ASC
            LIMIT 1
            """
        ).fetchone()
    if cheapest_car:
        cheapest_name = str(row_value(cheapest_car, "name") or "rental car")
        cheapest_price = float(row_value(cheapest_car, "daily_price") or 0)
        rental_title = f"🔥 Cheapest rental: {cheapest_name} from ${cheapest_price:.2f}/day"
        rental_body = "🚙 A low rate picked for you—compare your dates and grab it while this car is available."
    else:
        rental_title = "🔥 Your lowest rental deals are ready"
        rental_body = "🚙 Compare daily and weekly prices and grab the best available car for your dates."
    campaigns = {
        0: {
            "weekday": 4,
            "slug": "carpool",
            "title": "🚗 FairFares Carpool: your route could pay for itself",
            "body": "🛣️ List your carpool route, match with riders going your way, and split the travel cost.",
            "target": "carpool",
            "image_path": "/static/img/notifications/carpool-state-move.jpg",
        },
        1: {
            "weekday": 6,
            "slug": "housing",
            "title": "🏡 FairFares Housing: list your extra room",
            "body": "✨ Create a housing listing, meet nearby renters, and turn unused space into monthly savings.",
            "target": "housing",
            "image_path": "/static/img/notifications/housing-share-rent.jpg",
        },
        2: {
            "weekday": 3,
            "slug": "denver-rentals",
            "title": rental_title,
            "body": rental_body,
            "target": "rentals",
            "image_path": "/static/img/notifications/denver-rental-deals.jpg",
        },
    }
    campaign = campaigns[rotation]
    if now.weekday() != campaign["weekday"]:
        return {"sent": 0, "campaign": campaign["slug"], "status": "not scheduled today"}
    campaign_key = f"{now:%G}-W{week_number:02d}-{campaign['slug']}"
    return queue_promotional_campaign(campaign, campaign_key)


def start_promotional_push_scheduler() -> None:
    if os.environ.get("PROMOTIONAL_PUSH_AUTOMATION", "1").strip().lower() in {"0", "false", "no", "off"}:
        return

    def worker() -> None:
        while True:
            try:
                run_promotional_push_automation()
            except Exception as exc:
                print(f"Promotional push automation failed: {exc}")
            threading.Event().wait(60 * 60)

    threading.Thread(target=worker, daemon=True, name="fairfares-promotional-push").start()


def send_rental_booking_push(
    booking: sqlite3.Row | dict[str, object] | None,
    title: str,
    body: str,
    event: str,
) -> None:
    if not booking:
        return
    user_id = int(row_value(booking, "user_id") or 0)
    if not user_id:
        return
    booking_public_id = str(row_value(booking, "booking_id") or row_value(booking, "id") or "")
    send_mobile_push_for_users(
        [user_id],
        title,
        body,
        {
            "type": "RENTAL_BOOKING",
            "event": event,
            "bookingId": booking_public_id,
            "status": str(row_value(booking, "booking_status") or ""),
            "paymentStatus": str(row_value(booking, "payment_status") or ""),
            "target": "rentals",
        },
    )


def get_chat_conversations_for_user(user_id: int, limit: int = 30, offset: int = 0) -> list[dict[str, object]]:
    limit = max(1, min(int(limit or 30), 50))
    offset = max(0, int(offset or 0))
    with db() as con:
        consolidate_person_conversations(con, user_id)
        rows = con.execute(
            """
            SELECT conversations.*,
                   posts.public_id AS post_public_id,
                   posts.title AS post_title,
                   posts.category AS post_category,
                   rides.public_id AS ride_public_id,
                   rides.title AS ride_title,
                   rides.ride_type AS ride_type,
                   rides.origin_label AS ride_origin_label,
                   rides.destination_label AS ride_destination_label,
                   communities.public_id AS community_public_id,
                   communities.name AS community_name,
                   communities.kind AS community_kind,
                   communities.photo_url AS community_photo_url,
                   participant.last_read_message_id,
                   participant.muted_at,
                   participant.blocked_at,
                   (
                       SELECT COUNT(*)
                       FROM chat_messages unread_message
                       WHERE unread_message.conversation_id = conversations.id
                         AND unread_message.id > participant.last_read_message_id
                         AND unread_message.sender_id != ?
                         AND unread_message.deleted_at IS NULL
                   ) AS unread_count,
                   last_message.id AS last_message_id,
                   last_message.sender_id AS last_sender_id,
                   last_message.message_text AS last_message,
                   other_user.id AS other_user_id,
                   other_user.name AS other_name,
                   other_user.profile_photo_url AS other_photo_url,
                   MAX(other_sessions.last_seen_at) AS other_last_seen_at,
                   MAX(CASE WHEN datetime(other_sessions.last_seen_at) >= datetime('now', '-2 minutes') THEN 1 ELSE 0 END) AS other_online
            FROM chat_conversations conversations
            JOIN chat_participants participant ON participant.conversation_id = conversations.id AND participant.user_id = ?
            LEFT JOIN accommodation_posts posts ON posts.id = conversations.accommodation_post_id
            LEFT JOIN ride_posts rides ON rides.id = conversations.ride_post_id
            LEFT JOIN chat_messages last_message ON last_message.id = (
                SELECT id FROM chat_messages
                WHERE conversation_id = conversations.id AND deleted_at IS NULL
                ORDER BY id DESC LIMIT 1
            )
            LEFT JOIN chat_participants other_participant ON other_participant.conversation_id = conversations.id AND other_participant.user_id != ?
            LEFT JOIN users other_user ON other_user.id = other_participant.user_id
            LEFT JOIN sessions other_sessions ON other_sessions.user_id = other_user.id
            LEFT JOIN chat_communities communities ON communities.id = conversations.community_id
            WHERE conversations.status = 'ACTIVE'
              AND (
                  conversations.community_id IS NULL
                  OR EXISTS (
                      SELECT 1 FROM chat_community_members current_membership
                      WHERE current_membership.community_id = conversations.community_id
                        AND current_membership.user_id = ?
                  )
              )
            GROUP BY conversations.id
            ORDER BY COALESCE(datetime(conversations.last_message_at), datetime(conversations.updated_at)) DESC
            LIMIT ? OFFSET ?
            """,
            (user_id, user_id, user_id, user_id, limit, offset),
        ).fetchall()
    return [chat_row_payload(row, user_id) for row in rows]


def render_dashboard_chat_rows(conversations: list[dict[str, object]]) -> str:
    if not conversations:
        return """
        <div class="housing-dashboard-empty">
          <b>No messages yet</b>
          <span>When someone messages you about a room, rental, or roommate post, it will appear here.</span>
        </div>
        """
    rows = []
    for conversation in conversations:
        unread = int(conversation.get("unread") or 0)
        unread_badge = f'<strong>{unread} new</strong>' if unread else "<small>Read</small>"
        rows.append(
            f"""
            <button class="chat-inbox-row" type="button" data-chat-open data-conversation-id="{escape(str(conversation.get("id") or ""))}">
              <span>{escape(str(conversation.get("otherName") or "FairFares member"))}</span>
              <b>{escape(str(conversation.get("subject") or "Accommodation chat"))}</b>
              <small>{escape(str(conversation.get("lastMessage") or "No messages yet"))}</small>
              {unread_badge}
            </button>
            """
        )
    return "\n".join(rows)


def get_accommodation_posts_for_user(user_id: int) -> list[sqlite3.Row]:
    # Account/activity loads are latency-sensitive reads. Expiry housekeeping
    # is throttled so concurrent mobile refreshes do not each open a writer.
    expire_accommodation_posts(force=False)
    with db() as con:
        return con.execute(
            """
            SELECT *
            FROM accommodation_posts
            WHERE user_id = ?
            ORDER BY
                CASE visibility_status WHEN 'ACTIVE' THEN 0 ELSE 1 END,
                datetime(created_at) DESC
            LIMIT 80
            """,
            (user_id,),
        ).fetchall()


