def minify_css(content: str) -> str:
    content = re.sub(r"/\*.*?\*/", "", content, flags=re.DOTALL)
    content = re.sub(r"\s+", " ", content)
    content = re.sub(r"\s*([{}:;,>+~])\s*", r"\1", content)
    content = content.replace(";}", "}")
    return content.strip()


def minify_js(content: str) -> str:
    out: list[str] = []
    i = 0
    length = len(content)
    quote = ""
    escaped = False

    def next_non_space(index: int) -> str:
        while index < length and content[index].isspace():
            index += 1
        return content[index] if index < length else ""

    while i < length:
        char = content[i]
        nxt = content[i + 1] if i + 1 < length else ""
        if quote:
            out.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            i += 1
            continue
        if char in {"'", '"', "`"}:
            quote = char
            out.append(char)
            i += 1
            continue
        if char == "/" and nxt == "/":
            i += 2
            while i < length and content[i] not in "\r\n":
                i += 1
            continue
        if char == "/" and nxt == "*":
            i += 2
            while i + 1 < length and not (content[i] == "*" and content[i + 1] == "/"):
                i += 1
            i += 2
            continue
        if char.isspace():
            previous = out[-1] if out else ""
            following = next_non_space(i + 1)
            if previous and following and (
                previous.isalnum()
                or previous in {"_", "$"}
            ) and (
                following.isalnum()
                or following in {"_", "$"}
            ):
                out.append(" ")
            i += 1
            continue
        out.append(char)
        i += 1
    return "".join(out).strip()


def escape(value: object) -> str:
    return html.escape(str(value), quote=True)


def row_lookup(row: sqlite3.Row | dict[str, object] | None, key: str, default: object = "") -> object:
    if row is None:
        return default
    if hasattr(row, "keys") and key in row.keys():
        value = row[key]
        return default if value is None else value
    if isinstance(row, dict):
        value = row.get(key, default)
        return default if value is None else value
    return default


def vehicle_image_alt(row: sqlite3.Row | dict[str, object] | None) -> str:
    name = str(row_lookup(row, "name") or row_lookup(row, "car_name") or "FairFares rental car").strip()
    category = str(row_lookup(row, "category") or row_lookup(row, "type") or "").strip()
    location = str(row_lookup(row, "location") or row_lookup(row, "pickup_location") or "").strip()
    location_lower = location.lower()
    if "denver" in location_lower or "(den)" in location_lower:
        market = "Denver, Colorado"
    elif "colorado" in location_lower:
        market = location
    else:
        market = "Colorado"
    descriptor = f"{name} rental"
    if category and category.lower() not in name.lower():
        descriptor = f"{name} {category.lower()} rental"
    return f"{descriptor} available in {market}"


