class FairFaresHandler(SimpleHTTPRequestHandler):
    server_version = "FairFares/1.0"
    sys_version = ""

    def handle_one_request(self) -> None:
        self.request_started_at = time.perf_counter()
        self.request_id = uuid.uuid4().hex[:12]
        self.response_status = 0
        self.client_disconnected = False
        try:
            super().handle_one_request()
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError) as exc:
            # Mobile navigation, request timeouts, and closed browser tabs can
            # disconnect after the server has started writing a valid response.
            # This is a transport cancellation, not an application failure.
            self.client_disconnected = True
            self.close_connection = True
            print(json.dumps({
                "event": "client_disconnected",
                "request_id": self.request_id,
                "method": str(getattr(self, "command", "")),
                "path": urllib.parse.urlparse(str(getattr(self, "path", ""))).path[:300],
                "error_type": type(exc).__name__,
            }, separators=(",", ":")), flush=True)
        except sqlite3.OperationalError as exc:
            # A busy SQLite database is temporary capacity pressure, not an
            # unhandled application crash. Return an explicit retryable result
            # before the mobile client's request timeout expires.
            message = str(exc).lower()
            error_kind = "database_busy" if ("locked" in message or "busy" in message) else "database_operational_error"
            print(json.dumps({
                "event": error_kind,
                "request_id": self.request_id,
                "method": str(getattr(self, "command", "")),
                "path": urllib.parse.urlparse(str(getattr(self, "path", ""))).path[:300],
            }, separators=(",", ":")), flush=True)
            if int(getattr(self, "response_status", 0) or 0) == 0:
                try:
                    self.send_json(
                        {"ok": False, "retryable": True, "message": "FairFares is temporarily busy. Please try again."},
                        503,
                        {"Retry-After": "1"},
                    )
                except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                    self.client_disconnected = True
                    self.close_connection = True
            else:
                self.close_connection = True
        except Exception as exc:
            print(json.dumps({
                "event": "server_exception",
                "request_id": self.request_id,
                "method": str(getattr(self, "command", "")),
                "path": urllib.parse.urlparse(str(getattr(self, "path", ""))).path[:300],
                "error_type": type(exc).__name__,
            }, separators=(",", ":")), flush=True)
            if not getattr(self, "suppress_operational_alerts", False):
                send_operational_alert(
                    f"server-exception:{type(exc).__name__}:{urllib.parse.urlparse(str(getattr(self, 'path', ''))).path}",
                    "Unhandled backend exception",
                    severity="critical",
                    details=[
                        f"Request ID: {self.request_id}",
                        f"Method: {str(getattr(self, 'command', ''))}",
                        f"Path: {urllib.parse.urlparse(str(getattr(self, 'path', ''))).path[:300]}",
                        f"Error type: {type(exc).__name__}",
                    ],
                )
            raise
        finally:
            status = int(getattr(self, "response_status", 0) or 0)
            path = urllib.parse.urlparse(str(getattr(self, "path", ""))).path
            if path and path != "/healthz":
                duration_ms = round((time.perf_counter() - self.request_started_at) * 1000, 1)
                method = str(getattr(self, "command", ""))
                print(json.dumps({
                    "event": "http_request",
                    "request_id": self.request_id,
                    "method": method,
                    "path": path[:300],
                    "status": status,
                    "duration_ms": duration_ms,
                }, separators=(",", ":")), flush=True)
                alerts_enabled = (
                    not getattr(self, "suppress_operational_alerts", False)
                    and not getattr(self, "client_disconnected", False)
                )
                if alerts_enabled and path != "/api/health" and status >= 500:
                    send_operational_alert(
                        f"http-5xx:{method}:{path}:{status}",
                        "Backend request failed",
                        details=[
                            f"Request ID: {self.request_id}",
                            f"{method} {path}",
                            f"HTTP status: {status}",
                            f"Duration: {duration_ms} ms",
                        ],
                    )
                elif alerts_enabled and path not in {"/api/health", "/api/chat/events"} and duration_ms >= SLOW_REQUEST_THRESHOLD_MS:
                    send_operational_alert(
                        f"slow-request:{method}:{path}",
                        "Slow backend request",
                        severity="warning",
                        details=[
                            f"Request ID: {self.request_id}",
                            f"{method} {path}",
                            f"HTTP status: {status}",
                            f"Duration: {duration_ms} ms (threshold {SLOW_REQUEST_THRESHOLD_MS} ms)",
                        ],
                    )

    def send_response(self, code: int, message: str | None = None) -> None:
        self.response_status = code
        super().send_response(code, message)

    def client_ip(self) -> str:
        # Forwarded headers are trusted only when the deployment explicitly opts in.
        if os.environ.get("FAIRFARES_TRUST_PROXY", "0") == "1":
            forwarded = (self.headers.get("X-Forwarded-For") or "").split(",", 1)[0].strip()
            if forwarded:
                return forwarded[:64]
        return str(self.client_address[0] if self.client_address else "unknown")[:64]

    def is_cors_path(self, path: str) -> bool:
        return path.startswith("/api/") or path in {
            "/feedback",
            "/payment/stripe-session",
            "/identity/stripe-session",
        }

    def redirect_legacy_web_origin(self, parsed: urllib.parse.ParseResult) -> bool:
        host = (self.headers.get("Host") or "").split(":", 1)[0].lower()
        if host != "fairfares.onrender.com":
            return False
        if parsed.path.startswith(("/api/", "/static/", "/uploads/", "/.well-known/")):
            return False
        target = f"https://www.fairfare.space{parsed.path or '/'}"
        if parsed.query:
            target = f"{target}?{parsed.query}"
        self.send_response(308)
        self.send_header("Location", target)
        self.end_headers()
        return True

    def cors_allowed_origin(self) -> str:
        origin = (self.headers.get("Origin") or "").strip().rstrip("/")
        if not origin:
            return ""
        if origin in configured_cors_allowed_origins() or is_loopback_origin(origin):
            return origin
        return ""

    def do_OPTIONS(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        if self.is_cors_path(parsed.path):
            if self.headers.get("Origin") and not self.cors_allowed_origin():
                self.send_response(403)
            else:
                self.send_response(204)
            self.end_headers()
            return
        self.not_found()

    def do_HEAD(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        if parsed.path in PUBLIC_REDIRECT_ROUTES:
            self.redirect(PUBLIC_REDIRECT_ROUTES[parsed.path])
            return
        if parsed.path == "/robots.txt":
            self.send_text(self.robots_txt_body(), head_only=True)
            return
        if parsed.path == "/llms.txt":
            self.send_text(self.llms_txt_body(), content_type="text/plain; charset=utf-8", head_only=True)
            return
        if parsed.path == "/sitemap.xml":
            self.send_text(self.sitemap_xml_body(), content_type="application/xml; charset=utf-8", head_only=True)
            return
        if parsed.path.startswith("/static/"):
            self.serve_static(parsed.path)
            return
        if parsed.path.startswith("/uploads/"):
            self.serve_upload(parsed.path)
            return
        if parsed.path == "/admin/email-automation/run" and not (
            os.environ.get("EMAIL_AUTOMATION_TOKEN", "").strip()
            or os.environ.get("FAIRFARES_CRON_TOKEN", "").strip()
        ):
            self.send_json({"ok": False, "message": "Use POST for an interactive automation run."}, 405)
            return
        self.not_found()

    def do_GET(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        if self.redirect_legacy_web_origin(parsed):
            return
        if parsed.path == "/.well-known/apple-app-site-association":
            self.app_association_file("ios")
            return
        if parsed.path == "/.well-known/assetlinks.json":
            self.app_association_file("android")
            return
        if parsed.path in {"/fchat/invite", "/fchat/group"}:
            self.fchat_invite_landing(parsed)
