    def allow_post_from_same_origin(self, path: str) -> bool:
        if path in {"/stripe/webhook", "/auth/google"}:
            return True
        origin = (self.headers.get("Origin") or "").strip()
        if origin:
            if path.startswith("/api/") or path in {"/feedback", "/payment/stripe-session", "/identity/stripe-session"}:
                return bool(self.cors_allowed_origin())
            expected_host = (self.headers.get("Host") or "").split(":", 1)[0]
            return urllib.parse.urlparse(origin).hostname == expected_host
        # Native clients do not send Origin. Browser form requests still receive a
        # Referer check below; authenticated APIs use unguessable bearer tokens.
        expected_host = (self.headers.get("Host") or "").split(":", 1)[0]
        for header_name in ("Referer",):
            value = self.headers.get(header_name)
            if not value:
                continue
            parsed = urllib.parse.urlparse(value)
            if parsed.hostname and parsed.hostname != expected_host:
                return False
        return True

    def read_form(self) -> dict[str, str]:
        length = int(self.headers.get("Content-Length", "0"))
        if length > MAX_REQUEST_BODY_BYTES:
            return {}
        body = self.rfile.read(length).decode()
        parsed = urllib.parse.parse_qs(body)
        return {key: values[0].strip() for key, values in parsed.items()}

    def read_json_body(self) -> dict[str, object]:
        length = int(self.headers.get("Content-Length", "0"))
        if length <= 0:
            return {}
        if length > MAX_REQUEST_BODY_BYTES:
            return {}
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return {}
        return payload if isinstance(payload, dict) else {}

    def read_form_with_files(self) -> tuple[dict[str, str], dict[str, dict[str, object]]]:
        content_type = self.headers.get("Content-Type", "")
        if "multipart/form-data" not in content_type:
            return self.read_form(), {}
        form: dict[str, str] = {}
        files: dict[str, dict[str, object]] = {}
        length = int(self.headers.get("Content-Length", "0"))
        if length > MAX_REQUEST_BODY_BYTES:
            return {}, {}
        body = self.rfile.read(length)
        message = BytesParser(policy=EMAIL_POLICY).parsebytes(
            f"Content-Type: {content_type}\r\nMIME-Version: 1.0\r\n\r\n".encode("utf-8") + body
        )
        for part in message.iter_parts():
            if part.get_content_disposition() != "form-data":
                continue
            key = part.get_param("name", header="content-disposition")
            if not key:
                continue
            filename = part.get_filename() or ""
            if filename:
                payload = part.get_payload(decode=True) or b""
                if len(payload) <= MAX_DRIVE_UPLOAD_BYTES:
                    files[key] = {
                        "filename": Path(filename).name,
                        "mime_type": part.get_content_type() or mimetypes.guess_type(filename)[0] or "application/octet-stream",
                        "payload": payload,
                    }
                continue
            payload_text = part.get_content()
            form[key] = str(payload_text).strip()
        return form, files

    def current_user(self) -> sqlite3.Row | None:
        tokens: list[str] = []
        header = self.headers.get("Cookie", "")
        # Browsers can retain both a legacy domain cookie and a newer host-only
        # cookie with the same name. SimpleCookie keeps only one of those values,
        # which can discard the freshly issued Google sign-in session. Preserve
        # every candidate and use whichever token is active in our session store.
        for part in header.split(";"):
            name, separator, value = part.strip().partition("=")
            if separator and name == SESSION_COOKIE and value and value not in tokens:
                tokens.append(value.strip('"'))
        if not tokens:
            auth_header = (self.headers.get("Authorization") or "").strip()
            if auth_header.lower().startswith("bearer "):
                bearer_token = auth_header.split(" ", 1)[1].strip()
                if bearer_token:
                    tokens.append(bearer_token)
        if not tokens:
            return None
        authenticated_session_token = ""
        should_touch = False
        with db() as con:
            idle_cutoff = f"-{SESSION_IDLE_TIMEOUT_DAYS} days"
            absolute_cutoff = f"-{SESSION_ABSOLUTE_TIMEOUT_DAYS} days"
            placeholders = ", ".join("?" for _ in tokens)
            user = con.execute(
                f"""
                SELECT users.*, sessions.token AS authenticated_session_token FROM users
                JOIN sessions ON sessions.user_id = users.id
                WHERE sessions.token IN ({placeholders})
                  AND datetime(sessions.created_at) >= datetime('now', ?)
                  AND datetime(COALESCE(NULLIF(sessions.last_seen_at, ''), sessions.created_at)) >= datetime('now', ?)
                ORDER BY sessions.created_at DESC
                LIMIT 1
                """,
                (*tokens, absolute_cutoff, idle_cutoff),
            ).fetchone()
            if user:
                session_token = str(user["authenticated_session_token"])
                authenticated_session_token = session_token
                now = time.monotonic()
                with _SESSION_TOUCHES_LOCK:
                    last_touch = _SESSION_TOUCHES.get(session_token, 0.0)
                    should_touch = now - last_touch >= SESSION_TOUCH_INTERVAL_SECONDS
                    if should_touch:
                        _SESSION_TOUCHES[session_token] = now
                    if len(_SESSION_TOUCHES) > 10_000:
                        stale_before = now - max(SESSION_TOUCH_INTERVAL_SECONDS * 2, 3_600)
                        for token, touched_at in list(_SESSION_TOUCHES.items()):
                            if touched_at < stale_before:
                                _SESSION_TOUCHES.pop(token, None)
        # Authentication itself remains read-only. A contended activity refresh
        # must never delay login checks, conversation lists, or message sends.
        if user and should_touch:
            touch_session_last_seen_best_effort(authenticated_session_token)
        return user

    def send_html(self, body: bytes, status: int = 200, headers: dict[str, str] | None = None) -> None:
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.send_header("Expires", "0")
        for name, value in (headers or {}).items():
            self.send_header(name, value)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_json(self, payload: dict[str, object], status: int = 200, headers: dict[str, str] | None = None) -> None:
        body = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        for name, value in (headers or {}).items():
            self.send_header(name, value)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def wants_json(self) -> bool:
        accept = self.headers.get("Accept", "")
        requested_with = self.headers.get("X-Requested-With", "")
        return "application/json" in accept.lower() or requested_with == "fetch"

    def redirect(self, path: str) -> None:
        self.send_response(303)
        self.send_header("Location", path)
        self.end_headers()

    def safe_next_path(self, value: str = "") -> str:
        raw_value = (value or "").strip()
        parsed = urllib.parse.urlparse(raw_value)
        if not raw_value or parsed.scheme or parsed.netloc or not raw_value.startswith("/"):
            return ""
        if raw_value.startswith("//"):
            return ""
        return raw_value[:500]

    def current_path_with_query(self) -> str:
        return self.path if self.path.startswith("/") and not self.path.startswith("//") else "/"

    def login_url(self, next_path: str = "") -> str:
        safe_next = self.safe_next_path(next_path)
        if not safe_next:
            return "/login"
        return f"/login?next={urllib.parse.quote(safe_next, safe='')}"

    def community_join_url(self, public_id: str) -> str:
        return f"{self.public_origin()}/fchat/group?community_id={urllib.parse.quote(public_id)}"

    def community_invite_url(self, token: str) -> str:
        return f"{self.public_origin()}/fchat/invite?group_invite={urllib.parse.quote(token)}"

