    def accommodations_page(self) -> None:
        user = self.current_user()
        expire_accommodation_posts(force=False)
        parsed = urllib.parse.urlparse(self.path)
        params = urllib.parse.parse_qs(parsed.query)
        raw_search_need = (params.get("need", [""])[0] or "").strip()
        search_need = raw_search_need
        search_property_type = (params.get("property_type", [""])[0] or "").strip()
        search_metro = (params.get("metro", [""])[0] or "").strip()
        search_gender = (params.get("gender", [""])[0] or "").strip()
        search_ad_id = (params.get("ad_id", [""])[0] or "").strip()
        search_city = (params.get("city", [""])[0] or "").strip()
        search_area = (params.get("area", [""])[0] or "").strip()
        search_radius = max(0.0, min(100.0, float_from_value((params.get("radius", [""])[0] or "").strip())))
        search_move_in = (params.get("move_in", [""])[0] or "").strip()
        search_budget = (params.get("price", params.get("budget", [""]))[0] or "").strip()
        clauses = ["visibility_status = 'ACTIVE'", "(expires_at IS NULL OR expires_at = '' OR datetime(expires_at) > datetime('now'))"]
        values: list[object] = []
        if search_need == "roommate_match":
            search_need = "need_roommates"
        elif search_need in {"room_for_rent", "shared_room"}:
            search_need = "need_room_share"
        elif search_need == "apartment":
            search_need = "need_property_rent"
        elif search_need == "short_stay":
            clauses.append("(lease_term = 'short_stay' OR description LIKE '%short%' OR description LIKE '%temporary%')")
        if search_need == "need_room_share":
            clauses.append("post_mode = 'HAVE_PLACE'")
            clauses.append("category IN ('single_room', 'shared_room', 'paying_guest', 'basement_apartment')")
        elif search_need == "need_roommates":
            clauses.append("post_mode = 'NEED_PLACE'")
            clauses.append("roommate_intent = 1")
        elif search_need == "need_property_rent":
            clauses.append("post_mode = 'HAVE_PLACE'")
            clauses.append("category IN ('apartment', 'condo', 'town_house', 'single_family_home', 'basement_apartment')")
        elif search_need == "have_room_share":
            clauses.append("post_mode = 'NEED_PLACE'")
            clauses.append("category IN ('single_room', 'shared_room', 'paying_guest', 'basement_apartment')")
        elif search_need == "have_property_rent":
            clauses.append("post_mode = 'NEED_PLACE'")
            clauses.append("category IN ('apartment', 'condo', 'town_house', 'single_family_home', 'basement_apartment')")
        elif search_need == "have_commercial_rent":
            clauses.append("post_mode = 'HAVE_PLACE'")
            clauses.append("(title LIKE '%commercial%' OR description LIKE '%commercial%' OR amenities LIKE '%commercial%' OR title LIKE '%office%' OR description LIKE '%office%')")
        if search_property_type:
            clauses.append("category = ?")
            values.append(search_property_type)
        location_query = search_area or search_city
        metro_context = accommodation_metro_context(search_metro, location_query)
        if not search_metro and location_query:
            search_metro = cached_accommodation_metro_for_place(location_query)
        if search_metro:
            metro_terms = accommodation_location_terms(search_metro)
            metro_sql = " OR ".join(
                "(city_area_zip LIKE ? OR area_or_apartment LIKE ? OR work_school_location LIKE ? OR description LIKE ? OR street_address LIKE ? OR city LIKE ? OR zip_code LIKE ? OR primary_neighborhood LIKE ? OR apartment_name LIKE ?)"
                for _ in metro_terms
            )
            if metro_sql:
                clauses.append(f"({metro_sql})")
                for term in metro_terms:
                    metro_pattern = f"%{term}%"
                    values.extend([metro_pattern] * 9)
        if search_gender:
            clauses.append("(gender_preference = ? OR gender_preference IN ('open', 'no_preference'))")
            values.append(search_gender)
        if search_ad_id:
            ad_pattern = f"%{search_ad_id}%"
            clauses.append("(public_id LIKE ? OR title LIKE ? OR description LIKE ?)")
            values.extend([ad_pattern, ad_pattern, ad_pattern])
        if search_city:
            city_pattern = f"%{search_city.split(',', 1)[0].strip()}%"
            clauses.append("(city LIKE ? OR city_area_zip LIKE ? OR primary_neighborhood LIKE ? OR area_or_apartment LIKE ?)")
            values.extend([city_pattern] * 4)
        if search_area and not search_radius:
            pattern = f"%{search_area}%"
            clauses.append(
                "(city_area_zip LIKE ? OR area_or_apartment LIKE ? OR work_school_location LIKE ? OR description LIKE ? OR street_address LIKE ? OR city LIKE ? OR zip_code LIKE ? OR primary_neighborhood LIKE ? OR apartment_name LIKE ?)"
            )
            values.extend([pattern] * 9)
        if search_move_in:
            clauses.append("(move_in_date = '' OR move_in_date <= ?)")
            values.append(search_move_in)
        budget_value = float_from_form({"budget": search_budget}, "budget")
        if budget_value:
            clauses.append("(rent_max = 0 OR rent_max <= ? OR rent_min <= ?)")
            values.extend([budget_value, budget_value])
        where_sql = " AND ".join(clauses)
        with db() as con:
            posts = con.execute(
                f"""
                SELECT accommodation_posts.*,
                       (SELECT name FROM users WHERE users.id = accommodation_posts.user_id) AS owner_name,
                       (SELECT image_url FROM accommodation_post_images
                        WHERE accommodation_post_images.post_id = accommodation_posts.id
                        ORDER BY sort_order ASC, id ASC LIMIT 1) AS preview_image_url
                FROM accommodation_posts
                WHERE {where_sql}
                ORDER BY datetime(created_at) DESC
                LIMIT 80
                """,
                values,
            ).fetchall()
        search_focus = search_area or search_city or metro_context["selected_location"]
        map_payload = accommodation_post_map_payload(posts, search_focus, search_metro)
        if search_radius:
            allowed_post_ids = {
                str(item.get("id") or "")
                for item in map_payload.get("posts", [])
                if item.get("distance") is not None and float(item.get("distance") or 0) <= search_radius
            }
            posts = [row for row in posts if str(row_value(row, "public_id")) in allowed_post_ids]
            map_payload = accommodation_post_map_payload(posts, search_focus, search_metro)
        map_payload_json = json.dumps(map_payload).replace("</", "<\\/")
        chat_unread_count = 0
        if user:
            chat_unread_count = sum(
                int(conversation.get("unread") or 0)
                for conversation in get_chat_conversations_for_user(int(row_value(user, "id") or 0))
            )
        if "posted" in params:
            status_message = '<p class="housing-status success">Housing lead posted.</p>'
        elif "error" in params:
            status_message = '<p class="housing-status error">Add a category and a short description.</p>'
        else:
            status_message = ""
        post_modal_hidden = "false" if "error" in params else "true"
        body = render_template(
            "accommodations.html",
            auth_link='<a class="nav-button" href="/dashboard">Dashboard</a>' if user else '<a href="/login">Sign in / Join</a>',
            is_authenticated="true" if user else "false",
            current_user_id=escape(str(int(row_value(user, "id") or 0))),
            status_message=status_message,
            post_modal_hidden=post_modal_hidden,
            search_need_options=render_select_options(ACCOMMODATION_SEARCH_NEEDS, search_need),
            search_property_type=escape(search_property_type),
            search_property_type_options=render_select_options(ACCOMMODATION_PROPERTY_TYPE_FILTERS, search_property_type),
            search_metro_options=render_select_options(accommodation_metro_filter_options(), search_metro),
            search_gender_options=render_select_options(ACCOMMODATION_GENDER_FILTERS, search_gender),
            search_price_options=render_select_options(ACCOMMODATION_PRICE_FILTERS, search_budget),
            housing_subnav_links=render_accommodation_subnav_links(search_property_type),
            chat_unread_count=escape(str(chat_unread_count)),
            chat_unread_badge_class="" if chat_unread_count else "is-empty",
            selected_location=escape(metro_context["selected_location"]),
            mobile_listing_cards=render_mobile_accommodation_cards(posts),
            mobile_locality_cards=render_mobile_locality_cards(metro_context),
            mobile_welcome_html=render_mobile_housing_welcome(user),
            suggested_location=escape(metro_context["suggested_location"]),
            suggested_place_chips=metro_context["suggested_place_chips"],
            zip_chips=metro_context["zip_chips"],
            metro_list=metro_context["metro_list"],
            top_city_chips=metro_context["top_city_chips"],
            top_city_rows=metro_context["top_city_rows"],
            search_ad_id=escape(search_ad_id),
            search_city=escape(search_city or str(metro_context["selected_location"]).split(",", 1)[0]),
            search_area=escape(search_area),
            search_radius_options=render_select_options(ACCOMMODATION_RADIUS_OPTIONS, str(int(search_radius or 10))),
            search_move_in=escape(search_move_in),
            search_budget=escape(search_budget),
            category_options=render_select_options(ACCOMMODATION_CATEGORIES),
            radius_options=render_select_options(ACCOMMODATION_RADIUS_OPTIONS, "10"),
            rent_period_options=render_select_options(ACCOMMODATION_RENT_PERIODS, "MONTH"),
            gender_options=render_select_options(ACCOMMODATION_GENDER_OPTIONS, "open"),
            lease_term_options=render_select_options(ACCOMMODATION_LEASE_TERMS, "flexible"),
            posts_html=render_accommodation_posts(posts),
            profile_drawer_html=render_profile_drawer(user),
            map_payload_json=map_payload_json,
            maps_loader=explorer_maps_loader(),
            asset_version=ASSET_VERSION,
        )
        self.send_html(body)

    def create_accommodation_post(self) -> None:
        user = self.current_user()
        if not user:
            self.redirect("/accommodations?error=login_required#post")
            return
        form, files = self.read_form_with_files()
        for field, max_length in {
            "title": 140,
            "description": 1800,
            "street_address": 180,
            "city": 120,
            "zip_code": 20,
            "primary_neighborhood": 140,
            "apartment_name": 140,
            "city_area_zip": 160,
            "area_or_apartment": 140,
            "work_school_location": 160,
            "move_in_date": 40,
            "about_you": 900,
            "commute_preference": 180,
            "days_available": 120,
            "amenities": 700,
            "contact_name": 120,
            "contact_phone": 40,
        }.items():
            form[field] = clean_multiline_text_value(form.get(field), max_length)
        form["contact_email"] = normalize_email(form.get("contact_email") or row_value(user, "email"))
        for field in ("social_facebook", "social_x", "social_instagram", "social_youtube"):
            form[field] = clean_social_url(form.get(field))
        mode = normalize_accommodation_mode(form.get("post_mode", ""))
        category = option_value_or_default(ACCOMMODATION_CATEGORIES, form.get("category"), "")
        description = (form.get("description") or "").strip()
        contact_name = (form.get("contact_name") or row_value(user, "name")).strip()
        contact_email = (form.get("contact_email") or row_value(user, "email")).strip()
        contact_phone = (form.get("contact_phone") or row_value(user, "phone")).strip()
        if not category or not description:
            self.redirect("/accommodations?error=missing")
            return
        if not contact_name or not contact_email or not contact_phone:
            self.redirect("/accommodations?error=missing")
            return
        if not valid_contact_email(contact_email) or not valid_contact_phone(contact_phone):
            self.redirect("/accommodations?error=missing")
            return
        if mode == "HAVE_PLACE":
            required_listing_fields = (
                "title",
                "street_address",
                "city",
                "zip_code",
                "move_in_date",
                "rent_min",
                "rent_period",
                "accommodates",
                "bathroom_type",
                "lease_term",
            )
            if any(not (form.get(field) or "").strip() for field in required_listing_fields):
                self.redirect("/accommodations?error=missing")
                return
        if mode == "NEED_PLACE":
            required_request_fields = (
                "title",
                "city_area_zip",
                "zip_code",
                "move_in_date",
                "rent_min",
                "rent_period",
                "accommodates",
                "bathroom_type",
                "lease_term",
            )
            if any(not (form.get(field) or "").strip() for field in required_request_fields):
                self.redirect("/accommodations?error=missing")
                return
        public_id = accommodation_public_id()
        category_label = option_label(ACCOMMODATION_CATEGORIES, category, "Housing")
        roommate_intent = 1 if (form.get("roommate_intent") or "").strip() == "1" else 0
        title = accommodation_title_from_form(form, mode, category_label, bool(roommate_intent))
        user_id = int(row_value(user, "id") or 0) if user else None
        location_query = accommodation_form_location_query(form)
        location_point = accommodation_location_point(location_query)
        post_lat = float(location_point.get("lat") or 0)
        post_lng = float(location_point.get("lng") or 0)
        city_area_value = (form.get("city_area_zip") or "").strip()
        if mode == "HAVE_PLACE":
            city_bits = [
                (form.get("city") or "").strip(),
                (form.get("zip_code") or "").strip(),
            ]
            city_area_value = ", ".join(bit for bit in city_bits if bit) or city_area_value
        area_value = (form.get("area_or_apartment") or "").strip()
        if mode == "HAVE_PLACE":
            area_value = (
                (form.get("primary_neighborhood") or "").strip()
                or (form.get("apartment_name") or "").strip()
                or area_value
            )
        now = datetime.utcnow().isoformat(timespec="seconds")
        expires_at = accommodation_expiry_timestamp(now)
        with db() as con:
            cursor = con.execute(
                """
                INSERT INTO accommodation_posts
                (public_id, user_id, post_mode, category, title, description,
                 street_address, city, zip_code, primary_neighborhood, apartment_name,
                 city_area_zip, area_or_apartment, work_school_location, radius_miles, lat, lng,
                 move_in_date, rent_min, rent_max, rent_period, bedroom_count, bathroom_count,
                 accommodates, roommate_count, roommate_intent, about_you, bathroom_type, gender_preference,
                 commute_preference, lease_term, deposit, days_available, vegetarian_preference,
                 smoking_policy, pet_friendly, open_house_date, open_house_start, open_house_end,
                 social_facebook, social_x, social_instagram, social_youtube, amenities,
                 private_bath, furnished, parking, utilities_included,
                 contact_name, contact_phone, contact_email, visibility_status, source_label,
                 expires_at, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ACTIVE', 'USER_POST', ?, ?, ?)
                """,
                (
                    public_id,
                    user_id,
                    mode,
                    category,
                    title,
                    description,
                    (form.get("street_address") or "").strip(),
                    (form.get("city") or "").strip(),
                    (form.get("zip_code") or "").strip(),
                    (form.get("primary_neighborhood") or "").strip(),
                    (form.get("apartment_name") or "").strip(),
                    city_area_value,
                    area_value,
                    (form.get("work_school_location") or "").strip(),
                    int_from_form(form, "radius_miles", 10 if mode == "NEED_PLACE" else 0),
                    post_lat,
                    post_lng,
                    (form.get("move_in_date") or "").strip(),
                    float_from_form(form, "rent_min"),
                    float_from_form(form, "rent_max"),
                    (form.get("rent_period") or "MONTH").strip(),
                    int_from_form(form, "bedroom_count"),
                    int_from_form(form, "bathroom_count"),
                    int_from_form(form, "accommodates"),
                    int_from_form(form, "roommate_count"),
                    roommate_intent,
                    (form.get("about_you") or "").strip(),
                    (form.get("bathroom_type") or "").strip(),
                    (form.get("gender_preference") or "open").strip(),
                    (form.get("commute_preference") or "").strip(),
                    (form.get("lease_term") or "flexible").strip(),
                    float_from_form(form, "deposit"),
                    (form.get("days_available") or "").strip(),
                    (form.get("vegetarian_preference") or "").strip(),
                    (form.get("smoking_policy") or "").strip(),
                    (form.get("pet_friendly") or "").strip(),
                    (form.get("open_house_date") or "").strip(),
                    (form.get("open_house_start") or "").strip(),
                    (form.get("open_house_end") or "").strip(),
                    (form.get("social_facebook") or "").strip(),
                    (form.get("social_x") or "").strip(),
                    (form.get("social_instagram") or "").strip(),
                    (form.get("social_youtube") or "").strip(),
                    (form.get("amenities") or "").strip(),
                    checked_from_form(form, "private_bath"),
                    1 if (form.get("furnished_select") or "").strip() == "1" else checked_from_form(form, "furnished"),
                    checked_from_form(form, "parking"),
                    checked_from_form(form, "utilities_included"),
                    contact_name,
                    contact_phone,
                    contact_email,
                    expires_at,
                    now,
                    now,
                ),
            )
            post_id = int(cursor.lastrowid)
            for index in range(1, 5):
                image_url = save_file_payload_locally(
                    folder_name="accommodations",
                    file_data=files.get(f"image_{index}"),
                    fallback_name=f"{public_id.lower()}-{index}",
                    allowed_mime_types=ALLOWED_HOUSING_IMAGE_MIME_TYPES,
                    max_bytes=MAX_HOUSING_IMAGE_BYTES,
                )
                if not image_url:
                    continue
                con.execute(
                    """
                    INSERT INTO accommodation_post_images
                    (post_id, image_url, drive_file_id, sort_order, created_at)
                    VALUES (?, ?, '', ?, ?)
                    """,
                    (post_id, image_url, index, now),
                )
        self.redirect("/accommodations?posted=1#housing-posts")

    def api_chat_conversations(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to view messages."}, 401)
            return
        params = urllib.parse.parse_qs(parsed.query)
        try:
            limit = max(1, min(int(params.get("limit", ["30"])[0] or 30), 50))
            offset = max(0, int(params.get("offset", ["0"])[0] or 0))
        except ValueError:
            limit, offset = 30, 0
        conversations = get_chat_conversations_for_user(int(user["id"]), limit=limit, offset=offset)
        self.send_json({
            "ok": True,
            "conversations": conversations,
            "pagination": {
                "limit": limit,
                "offset": offset,
                "returned": len(conversations),
                "hasMore": len(conversations) == limit,
                "nextOffset": offset + len(conversations),
            },
        })

    def api_chat_communities(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        user_id = int(user["id"]) if user else None
        params = urllib.parse.parse_qs(parsed.query)
        city = (params.get("city", [""])[0] or "").strip()
        communities = get_chat_communities_for_user(user_id, city)
        for community in communities:
            if community.get("visibility") == "PUBLIC":
                community["joinUrl"] = self.community_join_url(str(community.get("id") or ""))
        self.send_json({"ok": True, "communities": communities})

    def api_chat_person_by_phone(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to find a FairFares contact."}, 401)
            return
        phone = normalize_phone((urllib.parse.parse_qs(parsed.query).get("phone") or [""])[0])
        if len(phone) < 10 or len(phone) > 15:
            self.send_json({"ok": False, "message": "Enter a complete phone number with country code."}, 400)
            return
        with db() as con:
            matches = con.execute(
                """
                SELECT id, name, phone FROM users
                WHERE chat_phone_discoverable = 1
                  AND is_verified = 1
                  AND guest_account = 0
                  AND id != ?
                """,
                (int(user["id"]),),
            ).fetchall()
            match = next((row for row in matches if normalize_phone(row_value(row, "phone")) == phone), None)
        if not match:
            self.send_json({"ok": False, "message": "No discoverable FairFares member matched that exact number."}, 404)
            return
        self.send_json({"ok": True, "person": {"id": int(match["id"]), "name": row_value(match, "name") or "FairFares member"}})

    def api_chat_people_by_contacts(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to find FairFares contacts."}, 401)
            return
        payload = self.read_json_body()
        supplied = payload.get("phoneHashes") if isinstance(payload, dict) else []
        hashes = {
            str(value).strip().lower() for value in supplied
            if isinstance(value, str) and len(str(value).strip()) == 64
        } if isinstance(supplied, list) else set()
        if not hashes or len(hashes) > 1000:
            self.send_json({"ok": False, "message": "Choose between 1 and 1,000 contact phone numbers."}, 400)
            return
        with db() as con:
            candidates = con.execute(
                """SELECT id, name, phone, profile_photo_url FROM users
                   WHERE chat_phone_discoverable = 1 AND is_verified = 1
                     AND guest_account = 0 AND id != ?""",
                (int(user["id"]),),
            ).fetchall()
        matches = []
        for candidate in candidates:
            normalized = normalize_phone(row_value(candidate, "phone"))
            variants = {normalized, normalized[-10:]} if len(normalized) >= 10 else set()
            matching_hash = next(
                (hashlib.sha256(value.encode("utf-8")).hexdigest() for value in variants
                 if hashlib.sha256(value.encode("utf-8")).hexdigest() in hashes),
                "",
            )
            if matching_hash:
                matches.append({
                    "id": int(candidate["id"]),
                    "name": row_value(candidate, "name") or "FairFares member",
                    "photoUrl": row_value(candidate, "profile_photo_url") or "",
                    "phoneHash": matching_hash,
                })
        self.send_json({"ok": True, "people": matches[:250]})

    def api_chat_messages(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to view messages."}, 401)
            return
        params = urllib.parse.parse_qs(parsed.query)
        conversation_public_id = (params.get("conversation_id", [""])[0] or "").strip()
        before_message_id = int(float_from_value(params.get("before", ["0"])[0] or "0"))
        limit = max(1, min(50, int(float_from_value(params.get("limit", ["30"])[0] or "30") or 30)))
        if not conversation_public_id:
            self.send_json({"ok": False, "message": "Conversation is required."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            community_id = int(row_value(conversation, "community_id") or 0)
            if community_id:
                sync_chat_conversation_members_from_community(con, int(conversation["id"]), community_id)
            message_params: list[object] = [conversation["id"]]
            before_clause = ""
            if before_message_id > 0:
                before_clause = "AND messages.id < ?"
                message_params.append(before_message_id)
            message_params.append(limit + 1)
            fetched_messages = con.execute(
                """
                SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                FROM chat_messages messages
                JOIN users ON users.id = messages.sender_id
                WHERE messages.conversation_id = ? AND messages.deleted_at IS NULL
                {before_clause}
                ORDER BY messages.id DESC
                LIMIT ?
                """.format(before_clause=before_clause),
                tuple(message_params),
            ).fetchall()
            has_more = len(fetched_messages) > limit
            messages = list(reversed(fetched_messages[:limit]))
            if messages:
                con.execute(
                    """
                    UPDATE chat_messages
                    SET delivered_at = COALESCE(delivered_at, CURRENT_TIMESTAMP),
                        read_at = COALESCE(read_at, CURRENT_TIMESTAMP)
                    WHERE conversation_id = ? AND sender_id != ? AND deleted_at IS NULL
                      AND (delivered_at IS NULL OR read_at IS NULL)
                    """,
                    (conversation["id"], current_user_id),
                )
                messages = con.execute(
                    """
                    SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                    FROM chat_messages messages
                    JOIN users ON users.id = messages.sender_id
                    WHERE messages.conversation_id = ?
                      AND messages.id IN ({placeholders})
                    ORDER BY messages.id ASC
                    """.format(placeholders=",".join("?" for _ in messages)),
                    (conversation["id"], *[int(row_value(message, "id") or 0) for message in messages]),
                ).fetchall()
            seen_row = con.execute(
                """
                SELECT MAX(last_read_message_id) AS seen_message_id
                FROM chat_participants
                WHERE conversation_id = ? AND user_id != ?
                """,
                (conversation["id"], current_user_id),
            ).fetchone()
            seen_message_id = int(row_value(seen_row, "seen_message_id") or 0)
            last_message_id = int(row_value(messages[-1], "id") or 0) if messages else 0
            if last_message_id:
                con.execute(
                    """
                    UPDATE chat_participants
                    SET last_read_message_id = MAX(last_read_message_id, ?)
                    WHERE conversation_id = ? AND user_id = ? AND last_read_message_id < ?
                    """,
                    (last_message_id, conversation["id"], current_user_id, last_message_id),
                )
        self.send_json(
            {
                "ok": True,
                "conversation": chat_row_payload(conversation, current_user_id),
                "messages": [chat_message_payload(message, current_user_id, seen_message_id) for message in messages],
                "hasMore": has_more,
                "nextBefore": int(row_value(messages[0], "id") or 0) if has_more and messages else 0,
            }
        )

    def api_chat_events(self, parsed: urllib.parse.ParseResult) -> None:
        """Authenticated held request for near-real-time chat delivery.

        The existing HTTP server cannot safely accept WebSocket upgrades. This
        endpoint keeps one request open briefly, returns as soon as a persisted
        message appears, and includes delivery/read receipts for recent outgoing
        messages. It preserves the same participant authorization as history.
        """
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to receive messages."}, 401)
            return
        params = urllib.parse.parse_qs(parsed.query)
        conversation_public_id = (params.get("conversation_id", [""])[0] or "").strip()
        after_message_id = max(0, int(float_from_value(params.get("after", ["0"])[0] or "0")))
        wait_seconds = min(7.5, max(0.0, float_from_value(params.get("wait", ["7"])[0] or "7")))
        if not conversation_public_id:
            self.send_json({"ok": False, "message": "Conversation is required."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            conversation_id = int(conversation["id"])

        deadline = time.monotonic() + wait_seconds
        messages: list[sqlite3.Row] = []
        receipts: list[dict[str, object]] = []
        typing: list[dict[str, object]] = []
        while True:
            with db() as con:
                messages = con.execute(
                    """
                    SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                    FROM chat_messages messages
                    JOIN users ON users.id = messages.sender_id
                    WHERE messages.conversation_id = ?
                      AND messages.id > ?
                      AND messages.deleted_at IS NULL
                    ORDER BY messages.id ASC
                    LIMIT 100
                    """,
                    (conversation_id, after_message_id),
                ).fetchall()
                incoming_ids = [int(row_value(message, "id") or 0) for message in messages if int(row_value(message, "sender_id") or 0) != current_user_id]
                if incoming_ids:
                    newest_incoming_id = max(incoming_ids)
                    con.execute(
                        """
                        UPDATE chat_messages
                        SET delivered_at = COALESCE(delivered_at, CURRENT_TIMESTAMP),
                            read_at = COALESCE(read_at, CURRENT_TIMESTAMP)
                        WHERE conversation_id = ? AND sender_id != ? AND id <= ? AND deleted_at IS NULL
                          AND (delivered_at IS NULL OR read_at IS NULL)
                        """,
                        (conversation_id, current_user_id, newest_incoming_id),
                    )
                    con.execute(
                        """
                        UPDATE chat_participants
                        SET last_read_message_id = MAX(last_read_message_id, ?)
                        WHERE conversation_id = ? AND user_id = ? AND last_read_message_id < ?
                        """,
                        (newest_incoming_id, conversation_id, current_user_id, newest_incoming_id),
                    )
                receipt_rows = con.execute(
                    """
                    SELECT id, delivered_at, read_at
                    FROM chat_messages
                    WHERE conversation_id = ? AND sender_id = ? AND id > ?
                    ORDER BY id DESC
                    LIMIT 100
                    """,
                    (conversation_id, current_user_id, max(0, after_message_id - 100)),
                ).fetchall()
                receipts = [
                    {
                        "id": int(row_value(receipt, "id") or 0),
                        "deliveredAt": row_value(receipt, "delivered_at"),
                        "readAt": row_value(receipt, "read_at"),
                        "status": "seen" if row_value(receipt, "read_at") else "delivered" if row_value(receipt, "delivered_at") else "sent",
                    }
                    for receipt in receipt_rows
                ]
                participant_rows = con.execute(
                    """SELECT participants.user_id, users.name
                       FROM chat_participants participants
                       JOIN users ON users.id = participants.user_id
                       WHERE participants.conversation_id = ? AND participants.user_id != ?""",
                    (conversation_id, current_user_id),
                ).fetchall()
            now_monotonic = time.monotonic()
            with _CHAT_TYPING_LOCK:
                expired = [key for key, expires_at in _CHAT_TYPING.items() if expires_at <= now_monotonic]
                for key in expired:
                    _CHAT_TYPING.pop(key, None)
                typing = [
                    {"userId": int(row["user_id"]), "name": row_value(row, "name") or "Someone"}
                    for row in participant_rows
                    if _CHAT_TYPING.get((conversation_id, int(row["user_id"])), 0) > now_monotonic
                ]
            if messages or typing or time.monotonic() >= deadline:
                break
            time.sleep(0.25)
        self.send_json(
            {
                "ok": True,
                "messages": [chat_message_payload(message, current_user_id) for message in messages],
                "receipts": receipts,
                "typing": typing,
                "cursor": max([after_message_id, *[int(row_value(message, "id") or 0) for message in messages]]),
            }
        )

    def api_chat_typing(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to update typing status."}, 401)
            return
        payload = self.read_json_body()
        conversation_public_id = clean_text_value(payload.get("conversationId"), 80)
        # Accept only a JSON boolean. Values such as the string "false" must
        # never be treated as an active typing indicator.
        active = payload.get("active") is True
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            conversation_id = int(conversation["id"])
        with _CHAT_TYPING_LOCK:
            now_monotonic = time.monotonic()
            expired = [entry for entry, expires_at in _CHAT_TYPING.items() if expires_at <= now_monotonic]
            for entry in expired:
                _CHAT_TYPING.pop(entry, None)
            key = (conversation_id, current_user_id)
            if active:
                _CHAT_TYPING[key] = now_monotonic + 5.0
            else:
                _CHAT_TYPING.pop(key, None)
        self.send_json({"ok": True, "active": active})

    def notify_chat_recipients(self, con: sqlite3.Connection, conversation: sqlite3.Row, sender: sqlite3.Row, message: sqlite3.Row) -> None:
        recipients = con.execute(
            """
            SELECT users.*, participants.muted_at AS chat_muted_at
            FROM chat_participants participants
            JOIN users ON users.id = participants.user_id
            WHERE participants.conversation_id = ? AND users.id != ?
            """,
            (conversation["id"], sender["id"]),
        ).fetchall()
        if row_value(conversation, "ride_public_id") or row_value(conversation, "ride_post_id"):
            conversation_url = f"{self.public_origin()}/dashboard?tab=rides#rides"
            post_title = row_value(conversation, "subject") or row_value(conversation, "ride_title") or "a FairFares ride"
        else:
            conversation_url = f"{self.public_origin()}/dashboard?tab=housing#housing"
            post_title = row_value(conversation, "subject") or row_value(conversation, "post_title") or "an accommodation request"
        push_jobs: list[tuple[str, dict[str, object]]] = []
        email_jobs: list[tuple[str, str, str, str, str, str]] = []
        stored_preview = str(row_value(message, "message_text") or "").strip()
        if row_value(message, "attachment_url"):
            notification_preview = "Sent you a secure attachment"
        elif "end-to-end encrypted message" in stored_preview.lower():
            # Never expose the encrypted-at-rest database placeholder in a
            # system notification. A plaintext preview is intentionally not
            # available to the relay server for an E2EE message.
            notification_preview = "New FChat message"
        else:
            notification_preview = stored_preview or "Sent you a message"
        for recipient in recipients:
            recipient_id = int(row_value(recipient, "id") or 0)
            preference = con.execute("SELECT chitthi_enabled FROM mobile_notification_preferences WHERE user_id = ?", (recipient_id,)).fetchone() if recipient_id else None
            chitthi_enabled = preference is None or bool(int(row_value(preference, "chitthi_enabled") or 0))
            if not row_value(recipient, "chat_muted_at") and recipient_id and chitthi_enabled:
                unread_badge = int(con.execute(
                    """
                    SELECT COUNT(*) AS unread_count
                    FROM chat_participants participant
                    JOIN chat_messages unread_message
                      ON unread_message.conversation_id = participant.conversation_id
                     AND unread_message.id > participant.last_read_message_id
                     AND unread_message.sender_id != participant.user_id
                     AND unread_message.deleted_at IS NULL
                    WHERE participant.user_id = ?
                    """,
                    (recipient_id,),
                ).fetchone()["unread_count"] or 0)
                token_rows = con.execute(
                    "SELECT token, device_id FROM mobile_push_tokens WHERE user_id = ? AND enabled = 1 ORDER BY datetime(last_seen_at) DESC LIMIT 5",
                    (recipient_id,),
                ).fetchall()
                for token_row in token_rows:
                    device_id = str(row_value(token_row, "device_id") or "")
                    envelope = con.execute(
                        "SELECT sender_public_key, preview_nonce, preview_ciphertext FROM chat_message_envelopes WHERE message_id = ? AND recipient_user_id = ? AND recipient_device_id = ? LIMIT 1",
                        (int(row_value(message, "id") or 0), recipient_id, device_id),
                    ).fetchone() if device_id else None
                    push_jobs.append((str(row_value(token_row, "token") or ""), {
                        "recipientUserId": recipient_id,
                        "recipientDeviceId": device_id,
                        "senderPublicKey": str(row_value(envelope, "sender_public_key") or "") if envelope else "",
                        "previewNonce": str(row_value(envelope, "preview_nonce") or "") if envelope else "",
                        "previewCiphertext": str(row_value(envelope, "preview_ciphertext") or "") if envelope else "",
                        "badge": unread_badge,
                    }))
            email = normalize_email(row_value(recipient, "email"))
            if not email:
                continue
            email_jobs.append(
                (
                    email,
                    str(row_value(recipient, "name") or ""),
                    str(row_value(sender, "name") or "FairFares member"),
                    str(post_title),
                    notification_preview,
                    conversation_url,
                )
            )
        if email_jobs:
            def deliver_chat_emails() -> None:
                for job in email_jobs:
                    try:
                        send_accommodation_message_email(*job)
                    except Exception as exc:
                        print(f"Chat email notification failed: {exc}")

            threading.Thread(
                target=deliver_chat_emails,
                daemon=True,
                name="fairfares-fchat-email",
            ).start()
        if push_jobs:
            sender_id = int(row_value(sender, "id") or 0)
            is_group = str(row_value(conversation, "conversation_type") or "").upper() == "GROUP" or bool(row_value(conversation, "community_id"))
            conversation_name = str(row_value(conversation, "subject") or "FChat group") if is_group else ""
            common_data = {
                "type": "FCHAT_MESSAGE",
                "conversationId": row_value(conversation, "public_id"),
                "messageId": int(row_value(message, "id") or 0),
                "senderId": sender_id,
                "senderName": row_value(sender, "name") or "FairFares member",
                "senderAvatarUrl": chat_notification_avatar_url(self.public_origin(), sender_id) if sender_id else "",
                "conversationName": conversation_name,
                "isGroup": is_group,
            }
            for token, encrypted_preview in push_jobs:
                enqueue_mobile_pushes(
                    [(int(encrypted_preview.get("recipientUserId") or 0), token)],
                    row_value(sender, "name") or "New FChat message",
                    notification_preview,
                    {**common_data, **encrypted_preview},
                )

    def api_create_chat_conversation(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to message this user."}, 401)
            return
        if "application/json" in (self.headers.get("Content-Type") or "").lower():
            raw_payload = self.read_json_body()
            form = {str(key): str(value).strip() for key, value in raw_payload.items() if value is not None}
        else:
            form = self.read_form()
        post_public_id = (form.get("post_id") or form.get("postId") or "").strip()
        ride_public_id = (form.get("ride_id") or form.get("rideId") or "").strip()
        community_public_id = (form.get("community_id") or form.get("communityId") or "").strip()
        target_user_id = int(float_from_value(form.get("target_user_id") or form.get("targetUserId") or "0"))
        open_only = str(form.get("open_only") or form.get("openOnly") or "").strip().lower() in {"1", "true", "yes", "on"}
        raw_message_text = (form.get("message") or "").strip()
        message_text = "" if open_only else raw_message_text or (
            "Hi, I am interested in this accommodation post."
            if post_public_id
            else "Hi, I am interested in this ride."
            if ride_public_id
            else ""
        )
        client_message_id = (form.get("client_message_id") or form.get("clientMessageId") or "").strip()
        if not post_public_id and not ride_public_id and not community_public_id and not target_user_id:
            self.send_json({"ok": False, "message": "Choose a housing post, ride, group, or FairFares member first."}, 400)
            return
        if len(message_text) > 2000:
            self.send_json({"ok": False, "message": "Message is too long."}, 400)
            return
        with db() as con:
            if community_public_id:
                conversation, error = get_or_create_community_conversation(con, community_public_id, user)
            elif ride_public_id:
                conversation, error = get_or_create_ride_conversation(con, ride_public_id, user)
            elif target_user_id:
                conversation, error = get_or_create_person_conversation(con, user, target_user_id)
            else:
                conversation, error = get_or_create_accommodation_conversation(con, post_public_id, user)
            if not conversation:
                self.send_json({"ok": False, "message": error or "Could not start chat."}, 400)
                return
            block_error = chat_conversation_block_error(con, conversation, int(user["id"]))
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            listing_context = chat_listing_context(
                con,
                int(user["id"]),
                post_public_id,
                ride_public_id,
            )
            context_owner_user_id = int(listing_context.get("ownerUserId", "0") or 0)
            if (post_public_id or ride_public_id) and not context_owner_user_id:
                self.send_json({"ok": False, "message": "Could not verify the listing owner for this message."}, 409)
                return
            if context_owner_user_id:
                verified_participant = con.execute(
                    "SELECT 1 FROM chat_participants WHERE conversation_id = ? AND user_id = ? LIMIT 1",
                    (conversation["id"], context_owner_user_id),
                ).fetchone()
                if not verified_participant:
                    self.send_json({"ok": False, "message": "The listing owner does not match this FChat profile."}, 409)
                    return
            message = save_chat_message(
                con,
                int(conversation["id"]),
                user,
                message_text,
                client_message_id,
                listing_context,
            ) if message_text else None
            full_conversation = get_chat_conversation_for_user(con, int(conversation["id"]), int(user["id"])) or conversation
            if message:
                con.commit()
                self.notify_chat_recipients(con, full_conversation, user, message)
            conversation_payload = chat_row_payload(full_conversation, int(user["id"]))
        self.send_json(
            {
                "ok": True,
                "conversation": conversation_payload,
                "message": chat_message_payload(message, int(user["id"])) if message else None,
            }
        )

    def api_open_feedback_conversation(self) -> None:
        """Open the configured private Chitthi inbox for product issues and ideas."""
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to message the FairFares team."}, 401)
            return
        if not CHITTHI_FEEDBACK_EMAIL:
            self.send_json({"ok": False, "message": "The issues and suggestions inbox is not configured yet."}, 503)
            return
        with db() as con:
            recipient = con.execute(
                "SELECT * FROM users WHERE LOWER(TRIM(email)) = ? LIMIT 1",
                (CHITTHI_FEEDBACK_EMAIL,),
            ).fetchone()
            if not recipient:
                self.send_json({"ok": False, "message": "The issues and suggestions inbox is not available yet."}, 503)
                return
            if int(recipient["id"]) == int(user["id"]):
                self.send_json({"ok": False, "message": "This profile receives issues and suggestions from other members."}, 400)
                return
            conversation, error = get_or_create_person_conversation(con, user, int(recipient["id"]))
            if not conversation:
                self.send_json({"ok": False, "message": error or "Could not open the issues and suggestions chat."}, 400)
                return
            full_conversation = get_chat_conversation_for_user(con, int(conversation["id"]), int(user["id"])) or conversation
            conversation_payload = chat_row_payload(full_conversation, int(user["id"]))
        self.send_json({"ok": True, "conversation": conversation_payload})

    def api_create_chat_community(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to create a group."}, 401)
            return
        form = self.read_form()
        community, error = create_chat_community(
            int(user["id"]),
            form.get("name", ""),
            form.get("kind", "GROUP"),
            form.get("description", ""),
            form.get("area", ""),
            form.get("photo", ""),
        )
        if not community:
            self.send_json({"ok": False, "message": error or "Could not create this group."}, 400)
            return
        token, invite_error = create_chat_group_invite(str(community.get("id") or ""), int(user["id"]))
        if invite_error:
            self.send_json({"ok": False, "message": invite_error}, 400)
            return
        community["joinUrl"] = self.community_invite_url(token)
