    def api_chat_e2ee_envelopes(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to read encrypted FChat."}, 401)
            return
        params = urllib.parse.parse_qs(parsed.query)
        conversation_public_id = (params.get("conversation_id") or [""])[0]
        device_id = (params.get("device_id") or [""])[0]
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, int(user["id"]))
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            rows = con.execute(
                """SELECT envelopes.message_id, envelopes.sender_public_key, envelopes.nonce, envelopes.ciphertext
                   FROM chat_message_envelopes envelopes JOIN chat_messages messages ON messages.id = envelopes.message_id
                   WHERE messages.conversation_id = ? AND envelopes.recipient_user_id = ? AND envelopes.recipient_device_id = ?""",
                (int(conversation["id"]), int(user["id"]), device_id),
            ).fetchall()
        self.send_json({"ok": True, "envelopes": [{"messageId": int(row["message_id"]), "senderPublicKey": row["sender_public_key"], "nonce": row["nonce"], "ciphertext": row["ciphertext"]} for row in rows]})

    def api_chat_e2ee_preview_envelopes(self, parsed: urllib.parse.ParseResult) -> None:
        """Return the current device's conversation-preview envelopes in one query."""
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to read encrypted FChat."}, 401)
            return
        params = urllib.parse.parse_qs(parsed.query)
        device_id = (params.get("device_id") or [""])[0].strip()
        raw_ids = (params.get("message_ids") or [""])[0].split(",")
        message_ids: list[int] = []
        for raw_id in raw_ids:
            try:
                message_id = int(raw_id)
            except (TypeError, ValueError):
                continue
            if message_id > 0 and message_id not in message_ids:
                message_ids.append(message_id)
            if len(message_ids) >= 50:
                break
        if not device_id or not message_ids:
            self.send_json({"ok": True, "envelopes": []})
            return
        placeholders = ",".join("?" for _ in message_ids)
        with db() as con:
            rows = con.execute(
                f"""SELECT envelopes.message_id, envelopes.sender_public_key, envelopes.nonce, envelopes.ciphertext
                    FROM chat_message_envelopes envelopes
                    JOIN chat_messages messages ON messages.id = envelopes.message_id
                    JOIN chat_participants members
                      ON members.conversation_id = messages.conversation_id AND members.user_id = ?
                    WHERE envelopes.recipient_user_id = ?
                      AND envelopes.recipient_device_id = ?
                      AND envelopes.message_id IN ({placeholders})""",
                (int(user["id"]), int(user["id"]), device_id, *message_ids),
            ).fetchall()
        self.send_json({"ok": True, "envelopes": [{"messageId": int(row["message_id"]), "senderPublicKey": row["sender_public_key"], "nonce": row["nonce"], "ciphertext": row["ciphertext"]} for row in rows]})

    def api_send_encrypted_chat_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to send encrypted messages."}, 401)
            return
        form = self.read_json_body()
        conversation_public_id = (form.get("conversationId") or "").strip()
        envelopes = form.get("envelopes") if isinstance(form.get("envelopes"), list) else []
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, int(user["id"]))
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            block_error = chat_conversation_block_error(con, conversation, int(user["id"]))
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            message, error = save_encrypted_chat_message(con, conversation, user, envelopes, str(form.get("clientMessageId") or ""))
            if not message:
                self.send_json({"ok": False, "message": error}, 409)
                return
            if not bool(form.get("silent")):
                con.commit()
                self.notify_chat_recipients(con, conversation, user, message)
        self.send_json({"ok": True, "message": chat_message_payload(message, int(user["id"]))}, 201)

    def api_relay_encrypted_chat_message(self) -> None:
        relay_user = self.current_user()
        if not relay_user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to relay encrypted FChat messages."}, 401)
            return
        bundle = self.read_json_body()
        message, error = accept_encrypted_chat_relay(bundle)
        if not message:
            self.send_json({"ok": False, "message": error}, 409)
            return
        with db() as con:
            conversation = con.execute("SELECT * FROM chat_conversations WHERE id = ?", (int(message["conversation_id"]),)).fetchone()
            sender = con.execute("SELECT * FROM users WHERE id = ?", (int(message["sender_id"]),)).fetchone()
            if conversation and sender:
                con.commit()
                self.notify_chat_recipients(con, conversation, sender, message)
        self.send_json({"ok": True, "messageId": int(message["id"])}, 201)

    def api_send_encrypted_chat_attachment(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to send encrypted attachments."}, 401)
            return
        payload = self.read_json_body()
        conversation_public_id = clean_text_value(payload.get("conversationId"), 80)
        ciphertext_base64 = str(payload.get("ciphertextBase64") or "")
        envelopes = payload.get("envelopes") if isinstance(payload.get("envelopes"), list) else []
        try:
            ciphertext = base64.b64decode(ciphertext_base64, validate=True)
        except (ValueError, TypeError):
            ciphertext = b""
        if not ciphertext or len(ciphertext) > MAX_CHAT_ENCRYPTED_ATTACHMENT_BYTES + 1024:
            self.send_json({"ok": False, "message": "Encrypted attachment is missing or too large."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            block_error = chat_conversation_block_error(con, conversation, current_user_id)
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            message, error = save_encrypted_chat_message(con, conversation, user, envelopes, clean_text_value(payload.get("clientMessageId"), 120))
            if not message:
                self.send_json({"ok": False, "message": error}, 409)
                return
            attachment_url = save_file_payload_locally(
                folder_name="chat", file_data={"filename": f"encrypted-{message['id']}.ffenc", "mime_type": "application/octet-stream", "payload": ciphertext},
                fallback_name=f"encrypted-{message['id']}.ffenc", allowed_mime_types={"application/octet-stream"}, max_bytes=MAX_CHAT_ENCRYPTED_ATTACHMENT_BYTES + 1024,
            )
            if not attachment_url:
                con.execute("DELETE FROM chat_message_envelopes WHERE message_id = ?", (int(message["id"]),))
                con.execute("DELETE FROM chat_messages WHERE id = ?", (int(message["id"]),))
                self.send_json({"ok": False, "message": "Could not store the encrypted attachment."}, 500)
                return
            con.execute(
                "UPDATE chat_messages SET message_type = 'ENCRYPTED_ATTACHMENT', attachment_url = ?, metadata_json = ? WHERE id = ?",
                (attachment_url, json.dumps({"encrypted": True, "size": len(ciphertext)}), int(message["id"])),
            )
            message = con.execute("SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url FROM chat_messages messages JOIN users ON users.id = messages.sender_id WHERE messages.id = ?", (int(message["id"]),)).fetchone()
            if not bool(payload.get("silent")):
                con.commit()
                self.notify_chat_recipients(con, conversation, user, message)
        self.send_json({"ok": True, "message": chat_message_payload(message, current_user_id)}, 201)

    def api_save_chat_e2ee_backup(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to back up encryption keys."}, 401)
            return
        payload = self.read_json_body()
        encrypted_payload = str(payload.get("encryptedPayload") or "")
        if len(encrypted_payload) < 100 or len(encrypted_payload) > 8000:
            self.send_json({"ok": False, "message": "Encrypted recovery backup is invalid."}, 400)
            return
        with db() as con:
            con.execute(
                """INSERT INTO chat_key_backups (user_id, encrypted_payload) VALUES (?, ?)
                   ON CONFLICT(user_id) DO UPDATE SET encrypted_payload = excluded.encrypted_payload, updated_at = CURRENT_TIMESTAMP""",
                (int(user["id"]), encrypted_payload),
            )
        self.send_json({"ok": True})

    def api_get_chat_e2ee_backup(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to recover encryption keys."}, 401)
            return
        with db() as con:
            row = con.execute("SELECT encrypted_payload, updated_at FROM chat_key_backups WHERE user_id = ?", (int(user["id"]),)).fetchone()
        self.send_json({"ok": True, "encryptedPayload": row_value(row, "encrypted_payload") if row else "", "updatedAt": row_value(row, "updated_at") if row else ""})

    def api_chat_phone_discoverability(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to change chat privacy."}, 401)
            return
        form = self.read_form()
        enabled = str(form.get("enabled") or "").strip().lower() in {"1", "true", "yes", "on"}
        if enabled and (not normalize_phone(row_value(user, "phone")) or not int(row_value(user, "is_verified") or 0)):
            self.send_json({"ok": False, "message": "Add a phone number and verify your FairFares account first."}, 400)
            return
        with db() as con:
            con.execute("UPDATE users SET chat_phone_discoverable = ? WHERE id = ?", (1 if enabled else 0, int(user["id"])))
        self.send_json({"ok": True, "enabled": enabled})

    def api_send_chat_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to send messages."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        message_text = (form.get("message") or "").strip()
        client_message_id = (form.get("client_message_id") or "").strip()
        if not conversation_public_id or not message_text:
            self.send_json({"ok": False, "message": "Conversation and message are required."}, 400)
            return
        if len(message_text) > 2000:
            self.send_json({"ok": False, "message": "Message is too long."}, 400)
            return
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, int(user["id"]))
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            community_id = int(row_value(conversation, "community_id") or 0)
            if community_id:
                sync_chat_conversation_members_from_community(con, int(conversation["id"]), community_id)
            block_error = chat_conversation_block_error(con, conversation, int(user["id"]))
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            message = save_chat_message(con, int(conversation["id"]), user, message_text, client_message_id)
            con.commit()
            self.notify_chat_recipients(con, conversation, user, message)
        self.send_json({"ok": True, "message": chat_message_payload(message, int(user["id"]))})

    def api_send_chat_attachment(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to send attachments."}, 401)
            return
        content_type = (self.headers.get("Content-Type") or "").lower()
        uploaded_file: dict[str, object] | None = None
        if "multipart/form-data" in content_type:
            form, files = self.read_form_with_files()
            payload: dict[str, object] = form
            uploaded_file = files.get("attachment") or files.get("file")
        else:
            payload = self.read_json_body()
        conversation_public_id = clean_text_value(payload.get("conversationId") or payload.get("conversation_id"), 80)
        data_url = str(payload.get("dataUrl") or payload.get("data_url") or "")
        requested_filename = clean_text_value(payload.get("fileName") or payload.get("file_name"), 140)
        requested_mime_type = clean_text_value(payload.get("mimeType") or payload.get("mime_type"), 120).lower()
        caption = clean_text_value(payload.get("caption"), 500)
        client_message_id = clean_text_value(payload.get("clientMessageId") or payload.get("client_message_id"), 120)
        if not conversation_public_id or (not data_url and not uploaded_file):
            self.send_json({"ok": False, "message": "Conversation and attachment are required."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            block_error = chat_conversation_block_error(con, conversation, current_user_id)
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            if client_message_id:
                existing = con.execute(
                    """
                    SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                    FROM chat_messages messages
                    JOIN users ON users.id = messages.sender_id
                    WHERE messages.conversation_id = ? AND messages.sender_id = ? AND messages.client_message_id = ?
                    LIMIT 1
                    """,
                    (conversation["id"], current_user_id, client_message_id),
                ).fetchone()
                if existing:
                    self.send_json({"ok": True, "message": chat_message_payload(existing, current_user_id)})
                    return
            allowed_mime_types = ALLOWED_CHAT_IMAGE_MIME_TYPES | ALLOWED_CHAT_FILE_MIME_TYPES
            if uploaded_file:
                upload_filename = clean_text_value(uploaded_file.get("filename") or requested_filename or f"chat-{conversation_public_id}", 140)
                upload_mime_type = clean_text_value(uploaded_file.get("mime_type") or requested_mime_type, 120).lower()
                upload_payload = uploaded_file.get("payload")
                upload_parts = (
                    upload_filename,
                    upload_mime_type,
                    upload_payload,
                ) if isinstance(upload_payload, bytes) and upload_payload and upload_mime_type in allowed_mime_types else None
            else:
                upload_parts = data_url_upload_parts(
                    data_url,
                    requested_filename or f"chat-{conversation_public_id}",
                    allowed_mime_types=allowed_mime_types,
                    max_bytes=MAX_CHAT_FILE_BYTES,
                )
            valid_upload = False
            if upload_parts:
                upload_filename, upload_mime_type, upload_payload = upload_parts
                if requested_mime_type and requested_mime_type != upload_mime_type:
                    upload_parts = None
                elif upload_mime_type in ALLOWED_CHAT_IMAGE_MIME_TYPES:
                    valid_upload = len(upload_payload) <= MAX_CHAT_IMAGE_BYTES and (
                        (upload_mime_type == "image/jpeg" and upload_payload.startswith(b"\xff\xd8\xff"))
                        or (upload_mime_type == "image/png" and upload_payload.startswith(b"\x89PNG\r\n\x1a\n"))
                        or (upload_mime_type == "image/webp" and len(upload_payload) >= 12 and upload_payload[:4] == b"RIFF" and upload_payload[8:12] == b"WEBP")
                    )
                elif upload_mime_type in ALLOWED_CHAT_FILE_MIME_TYPES:
                    valid_upload = valid_chat_document_payload(upload_mime_type, upload_filename, upload_payload)
            attachment_url = save_file_payload_locally(
                folder_name="chat",
                file_data={"filename": upload_filename, "mime_type": upload_mime_type, "payload": upload_payload} if upload_parts and valid_upload else None,
                fallback_name=requested_filename or f"chat-{conversation_public_id}",
                allowed_mime_types=allowed_mime_types,
                max_bytes=MAX_CHAT_FILE_BYTES,
            )
            if not attachment_url:
                self.send_json({"ok": False, "message": "Use an image up to 4 MB or a PDF, text, Word, or Excel file up to 8 MB."}, 400)
                return
            message = save_chat_message(con, int(conversation["id"]), user, caption, client_message_id)
            is_image = upload_mime_type in ALLOWED_CHAT_IMAGE_MIME_TYPES
            metadata = {"fileName": requested_filename or upload_filename, "mimeType": upload_mime_type, "size": len(upload_payload)}
            con.execute(
                "UPDATE chat_messages SET message_type = ?, attachment_url = ?, metadata_json = ? WHERE id = ?",
                ("IMAGE" if is_image else "FILE", attachment_url, json.dumps(metadata), int(message["id"])),
            )
            message = con.execute(
                """
                SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                FROM chat_messages messages JOIN users ON users.id = messages.sender_id
                WHERE messages.id = ?
                """,
                (int(message["id"]),),
            ).fetchone()
            con.commit()
            self.notify_chat_recipients(con, conversation, user, message)
        self.send_json({"ok": True, "message": chat_message_payload(message, current_user_id)}, 201)

    def api_send_chat_rich_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to send messages."}, 401)
            return
        payload = self.read_json_body()
        conversation_public_id = clean_text_value(payload.get("conversationId"), 80)
        message_type = clean_text_value(payload.get("type"), 20).upper()
        client_message_id = clean_text_value(payload.get("clientMessageId"), 120)
        raw_metadata = payload.get("metadata")
        metadata = raw_metadata if isinstance(raw_metadata, dict) else {}
        if message_type == "POLL":
            question = clean_text_value(metadata.get("question"), 240)
            options = [clean_text_value(value, 100) for value in (metadata.get("options") or []) if clean_text_value(value, 100)]
            if not question or len(options) < 2 or len(options) > 6:
                self.send_json({"ok": False, "message": "Add a poll question and 2–6 options."}, 400)
                return
            allow_multiple = bool(metadata.get("allowMultiple"))
            anonymous = bool(metadata.get("anonymous", True))
            try:
                closes_in_hours = max(0, min(168, int(metadata.get("closesInHours") or 0)))
            except (TypeError, ValueError):
                closes_in_hours = 0
            expires_at = (datetime.now(timezone.utc) + timedelta(hours=closes_in_hours)).isoformat() if closes_in_hours else ""
            clean_metadata = {"question": question, "options": options, "votes": {}, "allowMultiple": allow_multiple, "anonymous": anonymous, "expiresAt": expires_at}
            message_text = question
        elif message_type == "EVENT":
            title = clean_text_value(metadata.get("title"), 160)
            date = clean_text_value(metadata.get("date"), 40)
            time = clean_text_value(metadata.get("time"), 40)
            location = clean_text_value(metadata.get("location"), 180)
            if not title or not date:
                self.send_json({"ok": False, "message": "Event title and date are required."}, 400)
                return
            clean_metadata = {"title": title, "date": date, "time": time, "location": location}
            message_text = title
        elif message_type == "CONTACT":
            name = clean_text_value(metadata.get("name"), 120)
            phone = clean_text_value(metadata.get("phone"), 40)
            email = clean_text_value(metadata.get("email"), 180)
            if not name or (not phone and not email):
                self.send_json({"ok": False, "message": "Contact name and a phone number or email are required."}, 400)
                return
            clean_metadata = {"name": name, "phone": phone, "email": email}
            message_text = name
        else:
            self.send_json({"ok": False, "message": "Unsupported message type."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            block_error = chat_conversation_block_error(con, conversation, current_user_id)
            if block_error:
                self.send_json({"ok": False, "message": block_error}, 403)
                return
            message = save_chat_message(con, int(conversation["id"]), user, message_text, client_message_id)
            con.execute("UPDATE chat_messages SET message_type = ?, metadata_json = ? WHERE id = ?", (message_type, json.dumps(clean_metadata), int(message["id"])))
            message = con.execute("SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url FROM chat_messages messages JOIN users ON users.id = messages.sender_id WHERE messages.id = ?", (int(message["id"]),)).fetchone()
            con.commit()
            self.notify_chat_recipients(con, conversation, user, message)
        self.send_json({"ok": True, "message": chat_message_payload(message, current_user_id)}, 201)

    def api_vote_chat_poll(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to vote."}, 401)
            return
        payload = self.read_json_body()
        message_id = int(payload.get("messageId") or 0)
        option_index = int(payload.get("optionIndex") if payload.get("optionIndex") is not None else -1)
        current_user_id = int(user["id"])
        with db() as con:
            row = con.execute("SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url FROM chat_messages messages JOIN users ON users.id = messages.sender_id JOIN chat_participants participants ON participants.conversation_id = messages.conversation_id WHERE messages.id = ? AND participants.user_id = ?", (message_id, current_user_id)).fetchone()
            if not row or row_value(row, "message_type") != "POLL":
                self.send_json({"ok": False, "message": "Poll not found."}, 404)
                return
            try:
                metadata = json.loads(row_value(row, "metadata_json") or "{}")
            except json.JSONDecodeError:
                metadata = {}
            options = metadata.get("options") if isinstance(metadata.get("options"), list) else []
            if option_index < 0 or option_index >= len(options):
                self.send_json({"ok": False, "message": "Choose a valid poll option."}, 400)
                return
            expires_at = str(metadata.get("expiresAt") or "")
            if expires_at:
                try:
                    expires = datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
                    if expires.tzinfo is None:
                        expires = expires.replace(tzinfo=timezone.utc)
                    if expires <= datetime.now(timezone.utc):
                        self.send_json({"ok": False, "message": "This poll has ended."}, 409)
                        return
                except ValueError:
                    pass
            votes = metadata.get("votes") if isinstance(metadata.get("votes"), dict) else {}
            if bool(metadata.get("allowMultiple")):
                selected = votes.get(str(current_user_id)) if isinstance(votes.get(str(current_user_id)), list) else []
                selected = [int(value) for value in selected if isinstance(value, int) or str(value).isdigit()]
                if option_index in selected:
                    selected = [value for value in selected if value != option_index]
                else:
                    selected.append(option_index)
                if selected:
                    votes[str(current_user_id)] = selected
                else:
                    votes.pop(str(current_user_id), None)
            else:
                votes[str(current_user_id)] = option_index
            metadata["votes"] = votes
            con.execute("UPDATE chat_messages SET metadata_json = ? WHERE id = ?", (json.dumps(metadata), message_id))
            row = con.execute("SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url FROM chat_messages messages JOIN users ON users.id = messages.sender_id WHERE messages.id = ?", (message_id,)).fetchone()
        self.send_json({"ok": True, "message": chat_message_payload(row, current_user_id)})

    def api_chat_notification_avatar(self, parsed: urllib.parse.ParseResult) -> None:
        query = urllib.parse.parse_qs(parsed.query)
        try:
            user_id = int((query.get("user") or ["0"])[0])
            expires_at = int((query.get("expires") or ["0"])[0])
        except (TypeError, ValueError):
            self.send_error(404)
            return
        signature = str((query.get("signature") or [""])[0]).strip().lower()
        now = int(time.time())
        expected = chat_notification_avatar_signature(user_id, expires_at) if user_id > 0 and expires_at > 0 else ""
        if (
            not expected
            or not signature
            or expires_at < now
            or expires_at > now + 60 * 60
            or not hmac.compare_digest(signature, expected)
        ):
            self.send_error(404)
            return
        with db() as con:
            user = con.execute("SELECT profile_photo_url FROM users WHERE id = ? LIMIT 1", (user_id,)).fetchone()
        photo = str(row_value(user, "profile_photo_url") or "").strip() if user else ""
        upload = data_url_upload_parts(
            photo,
            f"fchat-avatar-{user_id}",
            allowed_mime_types=ALLOWED_CHAT_IMAGE_MIME_TYPES,
            max_bytes=2_000_000,
        )
        if upload:
            _, mime_type, payload = upload
            self.send_response(200)
            self.send_header("Content-Type", mime_type)
            self.send_header("Content-Length", str(len(payload)))
            self.send_header("Cache-Control", "private, max-age=600")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.end_headers()
            self.wfile.write(payload)
            return
        if photo.startswith("https://"):
            self.send_response(302)
            self.send_header("Location", photo)
            self.send_header("Cache-Control", "private, no-store")
            self.end_headers()
            return
        if photo.startswith("/"):
            self.send_response(302)
            self.send_header("Location", f"{self.public_origin().rstrip('/')}{photo}")
            self.send_header("Cache-Control", "private, no-store")
            self.end_headers()
            return
        self.send_error(404)

    def api_chat_attachment(self, message_id_value: str) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to view attachments."}, 401)
            return
        try:
            message_id = int(message_id_value)
        except (TypeError, ValueError):
            self.not_found()
            return
        with db() as con:
            message = con.execute(
                """
                SELECT messages.attachment_url
                FROM chat_messages messages
                JOIN chat_participants participants ON participants.conversation_id = messages.conversation_id
                WHERE messages.id = ? AND participants.user_id = ? AND messages.deleted_at IS NULL
                LIMIT 1
                """,
                (message_id, int(user["id"])),
            ).fetchone()
        attachment_url = row_value(message, "attachment_url") if message else ""
        parts = local_upload_parts(attachment_url) if attachment_url else None
        if not parts:
            self.not_found()
            return
        filename, mime_type, payload = parts
        self.send_response(200)
        self.send_header("Content-Type", mime_type)
        self.send_header("X-Content-Type-Options", "nosniff")
        disposition = "inline" if mime_type in ALLOWED_CHAT_IMAGE_MIME_TYPES or mime_type == "application/pdf" else "attachment"
        self.send_header("Content-Disposition", f'{disposition}; filename="{escape(filename)}"')
        self.send_header("Cache-Control", "private, no-store")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def api_edit_chat_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to edit messages."}, 401)
            return
        form = self.read_json_body()
        conversation_public_id = clean_text_value(form.get("conversationId"), 80)
        message_id = int(float_from_value(form.get("messageId")) or 0)
        envelopes = form.get("envelopes") if isinstance(form.get("envelopes"), list) else []
        if not conversation_public_id or not message_id or not envelopes:
            self.send_json({"ok": False, "message": "Conversation, message, and encrypted replacement are required."}, 400)
            return
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            message = con.execute(
                """
                SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                FROM chat_messages messages
                JOIN users ON users.id = messages.sender_id
                WHERE messages.id = ? AND messages.conversation_id = ?
                LIMIT 1
                """,
                (message_id, conversation["id"]),
            ).fetchone()
            if not message:
                self.send_json({"ok": False, "message": "Message not found."}, 404)
                return
            allowed, error = chat_message_is_editable(message, current_user_id)
            if not allowed:
                self.send_json({"ok": False, "message": error}, 403)
                return
            if str(row_value(message, "message_type") or "TEXT") != "TEXT":
                self.send_json({"ok": False, "message": "Only text messages can be edited."}, 400)
                return
            existing_envelope = con.execute("SELECT 1 FROM chat_message_envelopes WHERE message_id = ? LIMIT 1", (message_id,)).fetchone()
            if not existing_envelope:
                self.send_json({"ok": False, "message": "This message does not support secure editing."}, 400)
                return
            participant_ids = {int(row["user_id"]) for row in con.execute("SELECT user_id FROM chat_participants WHERE conversation_id = ?", (int(conversation["id"]),)).fetchall()}
            active_keys = {(int(row["user_id"]), str(row["device_id"])): str(row["public_key"]) for row in con.execute(
                "SELECT user_id, device_id, public_key FROM chat_device_keys WHERE revoked_at IS NULL AND user_id IN (%s)" % ",".join("?" * len(participant_ids)), tuple(participant_ids)
            ).fetchall()} if participant_ids else {}
            supplied = {(int(item.get("recipientUserId") or 0), str(item.get("recipientDeviceId") or "")) for item in envelopes if isinstance(item, dict)}
            if not active_keys or set(active_keys) != supplied or len(supplied) != len(envelopes):
                self.send_json({"ok": False, "message": "Encryption keys changed. Refresh the chat and try again."}, 409)
                return
            sender_public_keys = {public_key for (key_user_id, _), public_key in active_keys.items() if key_user_id == current_user_id}
            for item in envelopes:
                if not isinstance(item, dict) or str(item.get("senderPublicKey") or "") not in sender_public_keys:
                    self.send_json({"ok": False, "message": "The edited message encryption key is invalid."}, 400)
                    return
                if len(str(item.get("nonce") or "")) > 100 or len(str(item.get("ciphertext") or "")) > 12000:
                    self.send_json({"ok": False, "message": "The encrypted replacement is invalid."}, 400)
                    return
            con.execute("DELETE FROM chat_message_envelopes WHERE message_id = ?", (message_id,))
            for item in envelopes:
                con.execute(
                    """INSERT INTO chat_message_envelopes
                       (message_id, recipient_user_id, recipient_device_id, sender_public_key, nonce, ciphertext, preview_nonce, preview_ciphertext)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                    (message_id, int(item.get("recipientUserId") or 0), str(item.get("recipientDeviceId") or ""), str(item.get("senderPublicKey") or "")[:100], str(item.get("nonce") or ""), str(item.get("ciphertext") or ""), str(item.get("previewNonce") or ""), str(item.get("previewCiphertext") or "")),
                )
            con.execute(
                """
                UPDATE chat_messages
                SET message_text = ?, edited_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                ("🔒 End-to-end encrypted message", message_id),
            )
            updated = con.execute(
                """
                SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                FROM chat_messages messages
                JOIN users ON users.id = messages.sender_id
                WHERE messages.id = ?
                """,
                (message_id,),
            ).fetchone()
        self.send_json({"ok": True, "message": chat_message_payload(updated, current_user_id)})

    def api_delete_chat_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to delete messages."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        message_id = int_from_form(form, "message_id", 0)
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            message = con.execute(
                """
                SELECT messages.*, users.name AS sender_name, users.profile_photo_url AS sender_photo_url
                FROM chat_messages messages
                JOIN users ON users.id = messages.sender_id
                WHERE messages.id = ? AND messages.conversation_id = ?
                LIMIT 1
                """,
                (message_id, conversation["id"]),
            ).fetchone()
            if not message:
                self.send_json({"ok": False, "message": "Message not found."}, 404)
                return
            allowed, error = chat_message_is_editable(message, current_user_id)
            if not allowed:
                self.send_json({"ok": False, "message": error}, 403)
                return
            con.execute("UPDATE chat_messages SET deleted_at = CURRENT_TIMESTAMP WHERE id = ?", (message_id,))
        self.send_json({"ok": True, "messageId": message_id})

    def api_report_chat_message(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to report messages."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        message_id = int_from_form(form, "message_id", 0)
        reason = " ".join((form.get("reason") or "Reported from Fair Messenger").split())[:300]
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            message = con.execute(
                "SELECT id FROM chat_messages WHERE id = ? AND conversation_id = ? LIMIT 1",
                (message_id, conversation["id"]),
            ).fetchone()
            if not message:
                self.send_json({"ok": False, "message": "Message not found."}, 404)
                return
            con.execute(
                """
                INSERT INTO chat_message_reports (message_id, conversation_id, reporter_user_id, reason)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(message_id, reporter_user_id) DO UPDATE SET
                    reason = excluded.reason,
                    status = 'OPEN',
                    created_at = CURRENT_TIMESTAMP
                """,
                (message_id, conversation["id"], current_user_id, reason),
            )
            con.execute(
                "UPDATE chat_participants SET reported_at = COALESCE(reported_at, CURRENT_TIMESTAMP) WHERE conversation_id = ? AND user_id = ?",
                (conversation["id"], current_user_id),
            )
        self.send_json({"ok": True})

    def api_mute_chat_conversation(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to mute chats."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        muted = (form.get("muted") or "1").strip() != "0"
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            con.execute(
                "UPDATE chat_participants SET muted_at = CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE NULL END WHERE conversation_id = ? AND user_id = ?",
                (1 if muted else 0, conversation["id"], current_user_id),
            )
        self.send_json({"ok": True, "muted": muted})

    def api_block_chat_user(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to block members."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        target_user_id = int_from_form(form, "target_user_id", 0)
        blocked = (form.get("blocked") or "1").strip() != "0"
        reason = " ".join((form.get("reason") or "").split())[:200]
        current_user_id = int(user["id"])
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, current_user_id)
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            if row_value(conversation, "community_id"):
                self.send_json({"ok": False, "message": "Block is available for direct chats. Report group messages for admin review."}, 400)
                return
            if not target_user_id:
                row = con.execute(
                    """
                    SELECT user_id FROM chat_participants
                    WHERE conversation_id = ? AND user_id != ?
                    LIMIT 1
                    """,
                    (conversation["id"], current_user_id),
                ).fetchone()
                target_user_id = int(row_value(row, "user_id") or 0)
            if not target_user_id or target_user_id == current_user_id:
                self.send_json({"ok": False, "message": "Choose a member to block."}, 400)
                return
            if blocked:
                con.execute(
                    """
                    INSERT INTO chat_user_blocks (blocker_user_id, blocked_user_id, reason)
                    VALUES (?, ?, ?)
                    ON CONFLICT(blocker_user_id, blocked_user_id) DO UPDATE SET
                        reason = excluded.reason,
                        lifted_at = NULL,
                        created_at = CURRENT_TIMESTAMP
                    """,
                    (current_user_id, target_user_id, reason),
                )
                con.execute(
                    "UPDATE chat_participants SET blocked_at = CURRENT_TIMESTAMP WHERE conversation_id = ? AND user_id = ?",
                    (conversation["id"], current_user_id),
                )
            else:
                con.execute(
                    "UPDATE chat_user_blocks SET lifted_at = CURRENT_TIMESTAMP WHERE blocker_user_id = ? AND blocked_user_id = ? AND lifted_at IS NULL",
                    (current_user_id, target_user_id),
                )
                con.execute(
                    "UPDATE chat_participants SET blocked_at = NULL WHERE conversation_id = ? AND user_id = ?",
                    (conversation["id"], current_user_id),
                )
        self.send_json({"ok": True, "blocked": blocked, "targetUserId": target_user_id})

    def api_mark_chat_read(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to update messages."}, 401)
            return
        form = self.read_form()
        conversation_public_id = (form.get("conversation_id") or "").strip()
        last_message_id = int_from_form(form, "last_message_id", 0)
        with db() as con:
            conversation = get_chat_conversation_by_public_id(con, conversation_public_id, int(user["id"]))
            if not conversation:
                self.send_json({"ok": False, "message": "Conversation not found."}, 404)
                return
            if not last_message_id:
                row = con.execute(
                    "SELECT id FROM chat_messages WHERE conversation_id = ? ORDER BY id DESC LIMIT 1",
                    (conversation["id"],),
                ).fetchone()
                last_message_id = int(row_value(row, "id") or 0)
            con.execute(
                """
                UPDATE chat_participants
                SET last_read_message_id = MAX(last_read_message_id, ?)
                WHERE conversation_id = ? AND user_id = ? AND last_read_message_id < ?
                """,
                (last_message_id, conversation["id"], user["id"], last_message_id),
            )
        self.send_json({"ok": True})

