    def google_web_signin_markup(self, csrf_token: str = "") -> str:
        client_id = os.environ.get("GOOGLE_WEB_CLIENT_ID", "").strip()
        if not client_id:
            return '<p class="google-signin-unavailable">Google sign-in is not configured yet.</p>'
        return f"""
        <div class="google-signin" aria-label="Continue with Google">
          <script>
            function fairfaresGoogleSignIn(response) {{
              if (!response || !response.credential) return;
              const form = document.createElement("form");
              form.method = "POST";
              form.action = "/auth/google";
              const consent = document.querySelector('input[name="consent_accepted"]');
              if (consent && !consent.checked) {{
                consent.focus();
                alert("You must agree to the Terms of Service and Community Guidelines and acknowledge the Privacy Policy.");
                return;
              }}
              const fields = {{credential: response.credential, fairfares_google_csrf: "{escape(csrf_token)}", consent_accepted: consent?.checked ? "1" : "0"}};
              Object.entries(fields).forEach(([name, value]) => {{
                const input = document.createElement("input");
                input.type = "hidden";
                input.name = name;
                input.value = value;
                form.appendChild(input);
              }});
              document.body.appendChild(form);
              form.submit();
            }}
          </script>
          <script src="https://accounts.google.com/gsi/client" async defer></script>
          <div id="g_id_onload"
               data-client_id="{escape(client_id)}"
               data-callback="fairfaresGoogleSignIn"
               data-ux_mode="popup"
               data-auto_prompt="false"></div>
          <div class="g_id_signin"
               data-type="standard"
               data-shape="rectangular"
               data-theme="outline"
               data-text="continue_with"
               data-size="large"
               data-logo_alignment="left"
               data-width="320"></div>
        </div>
        """

