    def web_google_auth(self) -> None:
        form = self.read_form()
        consented, consented_at = consent_values(form)
        action_key = auth_action_rate_limit_key(self.client_ip(), "web-google")
        if auth_action_retry_after(action_key):
            self.login_page("Too many sign-in attempts. Please wait and try again.")
            return
        record_auth_action(action_key)
        credential = form.get("credential", "").strip()
        submitted_csrf = form.get("g_csrf_token", "").strip()
        submitted_fairfares_csrf = form.get("fairfares_google_csrf", "").strip()
        cookie_jar = cookies.SimpleCookie()
        try:
            cookie_jar.load(self.headers.get("Cookie", ""))
        except cookies.CookieError:
            cookie_jar = cookies.SimpleCookie()
        csrf_cookie = cookie_jar.get("g_csrf_token")
        cookie_csrf = csrf_cookie.value if csrf_cookie else ""
        fairfares_csrf_cookie = cookie_jar.get("fairfares_google_csrf")
        cookie_fairfares_csrf = fairfares_csrf_cookie.value if fairfares_csrf_cookie else ""
        google_csrf_valid = bool(
            submitted_csrf
            and cookie_csrf
            and secrets.compare_digest(submitted_csrf, cookie_csrf)
        )
        fairfares_csrf_valid = bool(
            submitted_fairfares_csrf
            and cookie_fairfares_csrf
            and secrets.compare_digest(submitted_fairfares_csrf, cookie_fairfares_csrf)
        )
        if not credential or len(credential) > 20_000 or not (google_csrf_valid or fairfares_csrf_valid):
            self.login_page("Google sign-in could not be validated. Please try again.")
            return
        try:
            claims = verify_google_identity_token(credential)
        except RuntimeError as exc:
            self.login_page(str(exc))
            return
        except ValueError as exc:
            self.login_page(str(exc))
            return
        subject = clean_text_value(claims.get("sub"), 255)
        email = normalize_email(claims.get("email") or "")
        display_name = clean_text_value(claims.get("name"), 120) or (email.split("@", 1)[0] if email else "FairFares member")
        if not subject or not email:
            self.login_page("Google did not provide the account information FairFares needs.")
            return
        try:
            with db() as con:
                identity = con.execute(
                    "SELECT user_id FROM auth_identities WHERE provider = 'google' AND provider_subject = ?",
                    (subject,),
                ).fetchone()
                user = con.execute("SELECT * FROM users WHERE id = ?", (int(identity["user_id"]),)).fetchone() if identity else None
                if not user:
                    existing = find_user_by_email(con, email)
                    if (not existing or int(row_value(existing, "guest_account") or 0)) and not consented:
                        self.signup_page("Agree to the Terms, Community Guidelines, and acknowledge the Privacy Policy before creating an account.")
                        return
                    if existing:
                        user_id = int(existing["id"])
                        if int(row_value(existing, "guest_account") or 0):
                            con.execute(
                                "UPDATE users SET name = ?, guest_account = 0, is_verified = 1, verified_at = CURRENT_TIMESTAMP, consented_at = ?, terms_version = ?, privacy_version = ?, community_guidelines_version = ? WHERE id = ?",
                                (display_name, consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION, user_id),
                            )
                    else:
                        con.execute(
                            "INSERT INTO users (name, email, password_hash, is_verified, verified_at, consented_at, terms_version, privacy_version, community_guidelines_version) VALUES (?, ?, ?, 1, CURRENT_TIMESTAMP, ?, ?, ?, ?)",
                            (display_name, email, hash_password(secrets.token_urlsafe(48)), consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION),
                        )
                        user_id = int(con.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
                    con.execute(
                        "INSERT INTO auth_identities (user_id, provider, provider_subject, provider_email) VALUES (?, 'google', ?, ?)",
                        (user_id, subject, email),
                    )
                else:
                    user_id = int(user["id"])
                    con.execute(
                        "UPDATE auth_identities SET provider_email = ?, updated_at = CURRENT_TIMESTAMP WHERE provider = 'google' AND provider_subject = ?",
                        (email, subject),
                    )
            self.set_session(user_id, "/")
        except sqlite3.IntegrityError:
            self.login_page("This Google account is already linked to another FairFares account.")

    def login(self) -> None:
        form = self.read_form()
        identifier = (form.get("email", "") or "").strip()
        submitted_password = str(form.get("password") or "")
        next_path = self.safe_next_path(form.get("next", ""))
        rate_key = login_rate_limit_key(self.client_ip(), identifier)
        account_rate_key = login_account_rate_limit_key(identifier)
        retry_after = max(login_retry_after(rate_key), login_retry_after(account_rate_key))
        if retry_after:
            google_csrf = secrets.token_urlsafe(32)
            secure = "; Secure" if self.public_origin().startswith("https://") else ""
            self.send_response(429)
            self.send_header("Retry-After", str(retry_after))
            body = render_template(
                "auth.html", mode="Log in", submit_label="Log In", action="/login",
                switch_url="/signup", switch_label="Create account",
                intro_text="Welcome back. Log in to continue.",
                error=escape("Too many login attempts. Please wait and try again."),
                next_field="", name_field="", identifier_label="Email or Phone Number",
                identifier_type="text", identifier_autocomplete="username",
                identifier_placeholder="Enter your email or phone", password_autocomplete="current-password",
                consent_field="",
                google_signin=self.google_web_signin_markup(google_csrf),
            )
            self.send_header(
                "Set-Cookie",
                f"fairfares_google_csrf={google_csrf}; HttpOnly; SameSite=Lax; Path=/auth/google; Max-Age=600{secure}",
            )
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        with db() as con:
            user = find_user_by_login_identifier(con, identifier)
        if not user:
            record_login_failure(rate_key)
            record_login_failure(account_rate_key)
            log_login_failure(identifier, "user_not_found")
            self.login_page("That email and password did not match.", next_path)
            return
        if len(submitted_password) > MAX_PASSWORD_LENGTH or not verify_password(submitted_password, user["password_hash"]):
            record_login_failure(rate_key)
            record_login_failure(account_rate_key)
            log_login_failure(identifier, "password_mismatch")
            self.login_page("That email and password did not match.", next_path)
            return
        if not user["is_verified"]:
            token = create_verification(user["id"], user["email"])
            link = self.activation_url(token)
            outbox_file, delivery_status = send_activation_email(user["email"], user["name"], link)
            self.activation_pending_page(
                user["email"],
                outbox_file,
                link,
                "Your account is not activated yet, so we sent a fresh activation link.",
                delivery_status,
            )
            return
        clear_login_failures(rate_key)
        clear_login_failures(account_rate_key)
        if password_hash_needs_upgrade(row_value(user, "password_hash")):
            with db() as con:
                con.execute("UPDATE users SET password_hash = ? WHERE id = ?", (hash_password(submitted_password), user["id"]))
        self.set_session(user["id"], next_path)

    def signup(self) -> None:
        form = self.read_form()
        action_key = auth_action_rate_limit_key(self.client_ip(), "web-signup")
        if auth_action_retry_after(action_key):
            self.signup_page("Too many signup attempts. Please wait and try again.")
            return
        record_auth_action(action_key)
        consented, consented_at = consent_values(form)
        if not consented:
            self.signup_page("You must agree to the Terms of Service and Community Guidelines and acknowledge the Privacy Policy.")
            return
        password = form.get("password", "")
        name, email, phone, validation_error = validate_account_fields(
            form.get("name"), form.get("email"), form.get("phone"), password
        )
        referral_code = re.sub(r"[^A-Za-z0-9_-]", "", str(form.get("referral_code") or ""))[:80]
        if validation_error:
            self.signup_page(validation_error)
            return
        try:
            with db() as con:
                existing_email_user = find_user_by_email(con, email)
                if existing_email_user and not int(existing_email_user["guest_account"] or 0):
                    raise sqlite3.IntegrityError
                guest = existing_email_user if existing_email_user else None
                if not guest and phone:
                    guest = con.execute(
                        "SELECT * FROM users WHERE phone = ? AND guest_account = 1 ORDER BY id DESC LIMIT 1",
                        (phone,),
                    ).fetchone()
                if guest:
                    email_owner = find_user_by_email(con, email)
                    if email_owner and email_owner["id"] == guest["id"]:
                        email_owner = None
                    if email_owner:
                        raise sqlite3.IntegrityError
                    con.execute(
                        """
                        UPDATE users
                        SET name = ?,
                            email = ?,
                            phone = COALESCE(NULLIF(?, ''), phone),
                            password_hash = ?,
                            is_verified = 0,
                            guest_account = 0,
                            consented_at = ?, terms_version = ?, privacy_version = ?, community_guidelines_version = ?
                        WHERE id = ?
                        """,
                        (name, email, phone, hash_password(password), consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION, guest["id"]),
                    )
                    user_id = guest["id"]
                else:
                    con.execute(
                        "INSERT INTO users (name, email, phone, password_hash, is_verified, consented_at, terms_version, privacy_version, community_guidelines_version) VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?)",
                        (name, email, phone, hash_password(password), consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION),
                    )
                    user_id = con.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
        except sqlite3.IntegrityError:
            self.signup_page("An account with that email already exists.")
            return
        attach_referral_rewards_to_user(user_id, email, phone, name)
        if referral_code:
            record_referral_signup(referral_code, user_id, email, name)
        token = create_verification(user_id, email)
        link = self.activation_url(token)
        outbox_file, delivery_status = send_activation_email(email, name, link)
        message = "We sent an activation link to your email."
        if not delivery_status.startswith("sent"):
            message = "Your activation link is ready, but the email provider did not deliver it."
        self.activation_pending_page(email, outbox_file, link, message, delivery_status)

    def activate_account(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        query = urllib.parse.parse_qs(parsed.query)
        token = query.get("token", [""])[0]
        if not token:
            self.activation_message_page("Activation link missing", "Please use the activation link from your FairFares email.")
            return
        with db() as con:
            verification = con.execute(
                """
                SELECT email_verifications.*, users.is_verified
                FROM email_verifications
                JOIN users ON users.id = email_verifications.user_id
                WHERE token = ? AND purpose = 'ACCOUNT'
                """,
                (token,),
            ).fetchone()
            if not verification:
                self.activation_message_page("Activation link invalid", "That activation link is not valid. Try signing in to receive a fresh link.")
                return
            if verification["used_at"] and verification["is_verified"]:
                self.activation_message_page("Account already activated", "Your FairFares account is already active.", "Go to Login", "/login")
                return
            con.execute(
                """
                UPDATE users
                SET is_verified = 1,
                    verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP)
                WHERE id = ?
                """,
                (verification["user_id"],),
            )
            con.execute("UPDATE email_verifications SET used_at = CURRENT_TIMESTAMP WHERE token = ?", (token,))
        self.set_session(verification["user_id"])

    def forgot_password_page(self) -> None:
        self.send_html(
            render_template(
                "forgot_password.html",
                error="",
            )
        )

    def forgot_password(self) -> None:
        form = self.read_form()
        email = normalize_email(form.get("email", ""))

        action_key = auth_action_rate_limit_key(self.client_ip(), "forgot-password")
        if auth_action_retry_after(action_key):
            self.send_html(render_template("forgot_password.html", error="Too many requests. Please wait and try again."))
            return
        record_auth_action(action_key)

        if not email or "@" not in email:
            self.send_html(
                render_template(
                    "forgot_password.html",
                    error="Please enter a valid email address.",
                )
            )
            return

        with db() as con:
            user = find_user_by_email(con, email)

        if user:
            token = create_verification(user["id"], email, purpose="PASSWORD_RESET")
            link = self.reset_password_url(token)
            outbox_file, delivery_status = send_password_reset_email(email, user["name"], link)

        self.send_html(
            render_template(
                "forgot_password_sent.html",
                email=escape(email),
            )
        )

    def reset_password_page(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        query = urllib.parse.parse_qs(parsed.query)
        token = query.get("token", [""])[0]

        if not token:
            self.activation_message_page(
                "Reset link missing",
                "Please request a fresh password reset link.",
                "Request New Link",
                "/forgot-password",
            )
            return

        with db() as con:
            verification = con.execute(
                """
                SELECT email_verifications.*, users.email
                FROM email_verifications
                JOIN users ON users.id = email_verifications.user_id
                WHERE token = ? AND purpose = 'PASSWORD_RESET' AND used_at IS NULL
                """,
                (token,),
            ).fetchone()

        if not verification:
            self.activation_message_page(
                "Reset link invalid",
                "That password reset link is no longer valid. Request a fresh link and use the newest email.",
                "Request New Link",
                "/forgot-password",
            )
            return

        created_time = datetime.fromisoformat(verification["created_at"])
        expires_at = created_time + timedelta(minutes=30)
        if datetime.now(UTC).replace(tzinfo=None) > expires_at:
            self.activation_message_page(
                "Reset link expired",
                "Your password reset link has expired. Please request a new one.",
                "Request New Link",
                "/forgot-password",
            )
            return

        self.send_html(
            render_template(
                "reset_password.html",
                token=escape(token),
                error="",
            )
        )

    def reset_password(self) -> None:
        form = self.read_form()
        token = form.get("token", "").strip()
        new_password = form.get("password", "")

        if not token or not valid_account_password(new_password):
            self.send_html(
                render_template(
                    "reset_password.html",
                    token=escape(token),
                    error=f"Password must be between 8 and {MAX_PASSWORD_LENGTH} characters.",
                )
            )
            return

        with db() as con:
            verification = con.execute(
                """
                SELECT email_verifications.*, users.id
                FROM email_verifications
                JOIN users ON users.id = email_verifications.user_id
                WHERE token = ? AND purpose = 'PASSWORD_RESET' AND used_at IS NULL
                """,
                (token,),
            ).fetchone()

        if not verification:
            self.activation_message_page(
                "Reset link invalid",
                "That password reset link is no longer valid. Request a fresh link and use the newest email.",
                "Request New Link",
                "/forgot-password",
            )
            return

        created_time = datetime.fromisoformat(verification["created_at"])
        expires_at = created_time + timedelta(minutes=30)
        if datetime.now(UTC).replace(tzinfo=None) > expires_at:
            self.activation_message_page(
                "Reset link expired",
                "Your password reset link has expired. Please request a new one.",
                "Request New Link",
                "/forgot-password",
            )
            return

        with db() as con:
            con.execute(
                "UPDATE users SET password_hash = ? WHERE id = ?",
                (hash_password(new_password), verification["user_id"]),
            )
            con.execute("UPDATE email_verifications SET used_at = CURRENT_TIMESTAMP WHERE token = ?", (token,))
            con.execute("DELETE FROM sessions WHERE user_id = ?", (verification["user_id"],))

        self.activation_message_page(
            "Password reset successful",
            "Your password has been reset. You can now sign in with your new password.",
            "Go to Login",
            "/login"
        )

    def update_user_booking(self) -> None:
        user = self.current_user()
        if not user:
            self.not_found()
            return
        form = self.read_form()
        booking = get_booking_for_user_by_identifier(user["id"], form.get("booking_id")) or get_booking_for_user(user["id"])
        if not booking:
            self.not_found()
            return
        if row_value(booking, "booking_status") in {"RETURNED", "CANCELLED", "EXPIRED_HOLD"}:
            self.send_json({"ok": False, "message": "Past bookings are read-only. You can still download their invoices and documents."}, 409)
            return
        if row_value(booking, "booking_status") in {"MODIFIED", "CANCELLATION_REQUESTED"}:
            self.send_json({"ok": False, "message": "This booking already has a pending request. Cancel or wait for that review before submitting another change."}, 409)
            return
        if not booking_customer_tools_unlocked(booking):
            self.send_json(
                {"ok": False, "message": "Pay the 10% hold or full balance before modifying pickup or return details."},
                403,
            )
            return
        new_pickup_date = form.get("pickup_date") or booking["pickup_date"]
        new_pickup_time = form.get("pickup_time") or booking["pickup_time"]
        new_return_date = form.get("return_date") or booking["dropoff_date"]
        new_return_time = form.get("return_time") or booking["dropoff_time"]
        new_pickup_location = form.get("pickup_location") or booking["pickup_location"]
        new_dropoff_location = form.get("dropoff_location") or booking["dropoff_location"]
        requested_vehicle = (form.get("vehicle") or "").strip()
        requested_car = get_car_by_name(requested_vehicle)
        if requested_vehicle and not requested_car:
            self.send_json({"ok": False, "message": "Selected vehicle is no longer available."}, 400)
            return
        requested_start = parse_booking_datetime(new_pickup_date, new_pickup_time)
        requested_end = parse_booking_datetime(new_return_date, new_return_time)
        if requested_start and requested_end and requested_end <= requested_start:
            self.send_json({"ok": False, "message": "Return date and time must be after pickup date and time."}, 400)
            return
        if requested_car and requested_car["id"] != booking["car_id"]:
            active_booking = active_booking_conflict_for_car(
                requested_car["id"],
                requested_start,
                requested_end,
                exclude_booking_id=booking["id"],
            )
            active_return = parse_booking_datetime(active_booking["dropoff_date"], active_booking["dropoff_time"]) if active_booking else None
            if requested_start and active_return and requested_start < active_return:
                self.send_json(
                    {
                        "ok": False,
                        "message": f"{requested_car['name']} is available after {active_return.strftime('%-I:%M %p') if os.name != 'nt' else active_return.strftime('%I:%M %p').lstrip('0')} on {active_return.strftime('%b %d, %Y')}.",
                    },
                    409,
                )
                return
        current_pickup_iso = display_date_to_input(booking["pickup_date"], new_pickup_date)
        current_return_iso = display_date_to_input(booking["dropoff_date"], new_return_date)
        changes = []
        if new_pickup_date != current_pickup_iso or new_pickup_time != booking["pickup_time"]:
            changes.append(f"Pickup changed to {format_booking_date(new_pickup_date, new_pickup_date)} at {new_pickup_time}")
        if new_return_date != current_return_iso or new_return_time != booking["dropoff_time"]:
            changes.append(f"Return changed to {format_booking_date(new_return_date, new_return_date)} at {new_return_time}")
        if new_pickup_location != booking["pickup_location"]:
            changes.append(f"Pickup location changed to {new_pickup_location}")
        if new_dropoff_location != booking["dropoff_location"]:
            changes.append(f"Drop-off location changed to {new_dropoff_location}")
        if requested_car and requested_car["id"] != booking["car_id"]:
            changes.append(f"Vehicle change requested from {booking['car_name']} to {requested_car['name']}")
        additional_driver_requested = form.get("additional_driver_requested") == "1" or bool(form.get("driver_name"))
        if additional_driver_requested:
            changes.append(f"Additional driver requested{': ' + form.get('driver_name') if form.get('driver_name') else ''}")
        change_note = "; ".join(changes) or "Timing/location review requested"
        car_id = requested_car["id"] if requested_car and requested_car["id"] != booking["car_id"] else booking["car_id"]
        next_days = rental_day_count(requested_start, requested_end, booking["days"])
        next_daily_price = float(row_value(requested_car, "daily_price") if requested_car else row_value(booking, "daily_price") or 0)
        discount_amount = calculate_booking_discount_amount(next_daily_price, next_days, get_valid_discount(booking["discount_code"]))
        additional_driver_fee = additional_driver_fee_for_days(next_days, additional_driver_requested)
        next_breakdown = rental_price_breakdown(next_daily_price, next_days, discount_amount, additional_driver_fee)
        subtotal = float(next_breakdown["base"])
        total_price = float(next_breakdown["total"])
        with db() as con:
            con.execute(
                """
                UPDATE bookings
                SET car_id = ?,
                    pickup_date = ?,
                    pickup_time = ?,
                    dropoff_date = ?,
                    dropoff_time = ?,
                    pickup_location = ?,
                    dropoff_location = ?,
                    return_location = ?,
                    days = ?,
                    subtotal_price = ?,
                    discount_amount = ?,
                    total_price = ?,
                    tax_fee_amount = ?,
                    booking_hold_amount = ?,
                    due_at_pickup_amount = ?,
                    estimated_market_total = ?,
                    fairfares_savings_amount = ?,
                    additional_driver_requested = ?,
                    additional_driver_name = ?,
                    additional_driver_age = ?,
                    additional_driver_fee_amount = ?,
                    booking_status = 'MODIFIED',
                    status = 'MODIFIED',
                    cancellation_reason = ?
                WHERE id = ? AND user_id = ?
                """,
                (
                    car_id,
                    format_booking_date(new_pickup_date, new_pickup_date),
                    new_pickup_time,
                    format_booking_date(new_return_date, new_return_date),
                    new_return_time,
                    new_pickup_location,
                    new_dropoff_location,
                    new_dropoff_location,
                    next_days,
                    subtotal,
                    discount_amount,
                    total_price,
                    next_breakdown["tax_fee_amount"],
                    next_breakdown["booking_hold"],
                    next_breakdown["due_at_pickup"],
                    next_breakdown["market_total"],
                    next_breakdown["savings"],
                    int(additional_driver_requested),
                    form.get("driver_name", "") if additional_driver_requested else "",
                    form.get("driver_age", "") if additional_driver_requested else "",
                    additional_driver_fee,
                    change_note,
                    booking["id"],
                    user["id"],
                ),
            )
            if requested_car and requested_car["id"] != booking["car_id"]:
                con.execute("UPDATE cars SET status = 'AVAILABLE' WHERE id = ?", (booking["car_id"],))
                con.execute("UPDATE cars SET status = 'BOOKED' WHERE id = ?", (requested_car["id"],))
        self.send_json(
            {
                "ok": True,
                "message": f"Modification request sent: {change_note}",
                "status_label": booking_status_label("MODIFIED", row_value(booking, "payment_status")),
                "status_class": booking_status_class("MODIFIED", row_value(booking, "payment_status")),
            }
        )

    def cancel_booking_request(self) -> None:
        user = self.current_user()
        if not user:
            self.not_found()
            return
        form = self.read_form()
        booking = get_booking_for_user_by_identifier(user["id"], form.get("booking_id")) or get_booking_for_user(user["id"])
        if not booking or booking["booking_status"] not in {"MODIFIED", "CANCELLATION_REQUESTED"}:
            self.send_json({"ok": False, "message": "No pending request to cancel."})
            return
        payment_confirmed = booking_payment_confirmed(booking)
        next_status = "CONFIRMED" if payment_confirmed else "PENDING_HOLD"
        next_payment_status = row_value(booking, "payment_status") if payment_confirmed else "HOLD_PENDING"
        hold_sql = ""
        if not payment_confirmed:
            hold_sql = """
                    hold_started_at = COALESCE(hold_started_at, CURRENT_TIMESTAMP),
                    hold_expires_at = COALESCE(hold_expires_at, datetime('now', '+10 minutes')),
            """
        with db() as con:
            con.execute(
                f"""
                UPDATE bookings
                SET booking_status = ?,
                    status = ?,
                    payment_status = ?,
                    {hold_sql}
                    cancellation_reason = ''
                WHERE id = ? AND user_id = ?
                """,
                (next_status, next_status, next_payment_status, booking["id"], user["id"]),
            )
        self.send_json({
            "ok": True,
            "message": "Pending request cancelled. Complete payment to confirm this booking." if not payment_confirmed else "Pending request cancelled. Your booking remains confirmed.",
            "status_label": booking_status_label(next_status, next_payment_status),
            "status_class": booking_status_class(next_status, next_payment_status),
        })

    def cancel_user_booking(self) -> None:
        user = self.current_user()
        if not user:
            self.not_found()
            return
        form = self.read_form()
        booking = get_booking_for_user_by_identifier(user["id"], form.get("booking_id")) or get_booking_for_user(user["id"])
        if not booking:
            self.not_found()
            return
        if row_value(booking, "booking_status") in {"RETURNED", "CANCELLED", "EXPIRED_HOLD"}:
            self.send_json({"ok": False, "message": "Past bookings cannot be cancelled or modified. Their invoices remain available."}, 409)
            return
        if row_value(booking, "booking_status") in {"MODIFIED", "CANCELLATION_REQUESTED"}:
            self.send_json({"ok": False, "message": "This booking already has a pending request. Cancel or wait for that review before requesting cancellation."}, 409)
            return
        if not booking_customer_tools_unlocked(booking):
            self.send_json(
                {"ok": False, "message": "This checkout is not confirmed yet. Pay first, or remove the unpaid hold."},
                403,
            )
            return
        if booking["booking_status"] == "CANCELLED":
            self.send_json({"ok": False, "message": "This booking is already cancelled."}, 409)
            return
        if booking["payment_status"] == "REFUNDED":
            self.send_json({"ok": False, "message": "This booking has already been refunded."}, 409)
            return
        reason = form.get("reason") or "Customer cancellation"
        refund_method = (form.get("refund_method") or "Original payment method").strip()
        if refund_method != "Original payment method":
            self.send_json({"ok": False, "message": "Refunds can only return to the original Stripe payment method."}, 400)
            return
        note = form.get("note", "")
        if note:
            reason = f"{reason}: {note}"
        auto_cancel = not cancellation_requires_admin_review(booking)
        next_status = "CANCELLED" if auto_cancel else "CANCELLATION_REQUESTED"
        refund_message = ""
        if auto_cancel and booking["payment_status"] == "HOLD_PAID":
            next_payment_status, refund_message = auto_refund_booking_payments(int(booking["id"]))
        elif booking["payment_status"] in {"PAID", "HOLD_PAID"}:
            next_payment_status = "REFUND_REVIEW"
        else:
            next_payment_status = booking["payment_status"]
        with db() as con:
            con.execute(
                """
                UPDATE bookings
                SET booking_status = ?,
                    status = ?,
                    payment_status = ?,
                    cancellation_reason = ?
                WHERE id = ? AND user_id = ?
                """,
                (next_status, next_status, next_payment_status, reason, booking["id"], user["id"]),
            )
            if auto_cancel:
                con.execute("UPDATE cars SET status = 'AVAILABLE' WHERE id = ?", (booking["car_id"],))
            ticket_id = make_cancellation_task(con, booking, user, reason, auto_cancel)
        deposit_release_message = ""
        if auto_cancel:
            deposit_released, deposit_release_message = release_security_deposit_after_cancellation(booking)
            if not deposit_released:
                deposit_release_message = f"Deposit release needs staff review: {deposit_release_message}"
        self.send_json({
            "ok": True,
            "message": (
                f"Booking cancelled automatically. {refund_message or 'No online payment refund was needed.'} {deposit_release_message} Task {ticket_id} was created for admin recordkeeping."
                if auto_cancel
                else f"Cancellation request sent to admin for approval. Task {ticket_id} was created."
            ),
            "booking_status": next_status,
            "status_label": booking_status_label(next_status, next_payment_status),
            "status_class": booking_status_class(next_status, next_payment_status),
        })

    def save_current_booking(self) -> None:
        user = self.current_user()
        if not user:
            self.not_found()
            return
        booking = get_booking_for_user(user["id"])
        if not booking:
            self.send_json({"ok": False, "message": "No booking available to save."})
            return
        with db() as con:
            con.execute("UPDATE bookings SET saved_by_user = 1 WHERE id = ? AND user_id = ?", (booking["id"], user["id"]))
        self.send_json({"ok": True, "message": "Current trip saved."})

    def pay_booking_hold(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to pay and confirm this car."}, 401)
            return
        expire_stale_booking_holds()
        form = self.read_form()
        booking = get_booking_for_user(user["id"])
        if not booking:
            self.send_json({"ok": False, "message": "Choose a car before paying."}, 404)
            return
        if booking["booking_status"] == "EXPIRED_HOLD":
            self.send_json({"ok": False, "message": "Payment window closed. Restart checkout or remove this vehicle."}, 409)
            return
        if booking["booking_status"] in {"CANCELLED", "RETURNED"}:
            self.send_json({"ok": False, "message": "This booking cannot accept payment right now."}, 400)
            return
        breakdown = booking_price_breakdown(booking)
        hold_amount = float(breakdown["booking_hold"])
        cardholder = form.get("cardholder_name", "").strip()
        raw_card = re.sub(r"\D+", "", form.get("card_last4", ""))
        payment_method = form.get("payment_method", "Card").strip() or "Card"
        if not cardholder or len(raw_card) < 4:
            self.send_json({"ok": False, "message": "Enter the cardholder name and last 4 card digits."}, 400)
            return
        card_last4 = raw_card[-4:]
        billing_status, billing_notes = evaluate_billing_name(
            payment_method,
            cardholder,
            booking["contact_name"] or user["name"],
            "",
        )
        if billing_status == "REVIEW_REQUIRED":
            billing_status = "MATCHED"
            billing_notes = "Billing name captured for 10% payment."
        invoice_number = f"HOLD-{secrets.randbelow(900000) + 100000}"
        with db() as con:
            while con.execute("SELECT 1 FROM transactions WHERE invoice_number = ?", (invoice_number,)).fetchone():
                invoice_number = f"HOLD-{secrets.randbelow(900000) + 100000}"
            con.execute(
                """
                INSERT INTO transactions
                (booking_id, payment_method, cardholder_name, amount, transaction_status, billing_verification_status, billing_verification_notes, invoice_number)
                VALUES (?, ?, ?, ?, 'HOLD_PAID', ?, ?, ?)
                """,
                (
                    booking["id"],
                    f"{payment_method} ending {card_last4}",
                    cardholder,
                    hold_amount,
                    billing_status,
                    billing_notes,
                    invoice_number,
                ),
            )
            con.execute(
                """
                UPDATE bookings
                SET payment_status = 'HOLD_PAID',
                    booking_status = 'CONFIRMED',
                    status = 'CONFIRMED',
                    booking_hold_amount = ?,
                    due_at_pickup_amount = ?,
                    hold_expires_at = NULL
                WHERE id = ? AND user_id = ?
                """,
                (hold_amount, breakdown["due_at_pickup"], booking["id"], user["id"]),
            )
            con.execute("UPDATE cars SET status = 'BOOKED' WHERE id = ?", (booking["car_id"],))
        notify_slack_payment(booking, f"10% hold paid: {format_money(hold_amount)}", self.public_origin())
        send_confirmed_booking_email_once(booking["id"], self.public_origin())
        confirmed_booking = get_booking_by_id(int(row_value(booking, "id") or 0))
        send_rental_booking_push(
            confirmed_booking or booking,
            "Rental booking confirmed",
            f"Payment received. Your booking {row_value(booking, 'booking_id')} is confirmed.",
            "PAYMENT_CONFIRMED",
        )
        self.send_json(
            {
                "ok": True,
                "message": f"Payment recorded: {format_money(hold_amount)}. It will be deducted from pickup balance.",
                "payment_status": "HOLD_PAID",
                "payment_label": payment_status_label("HOLD_PAID"),
                "status_label": booking_status_label("CONFIRMED", "HOLD_PAID"),
                "hold_amount": format_money(hold_amount),
                "due_at_pickup": format_money(breakdown["due_at_pickup"]),
                "invoice_number": invoice_number,
            }
        )

    def create_stripe_checkout_session(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to pay and confirm this car."}, 401)
            return
        expire_stale_booking_holds()
        form = self.read_form()
        booking = get_booking_for_user_by_identifier(user["id"], form.get("booking_id")) or get_booking_for_user(user["id"])
        if not booking:
            self.send_json({"ok": False, "message": "Choose a car before paying."}, 404)
            return
        if booking["booking_status"] == "EXPIRED_HOLD":
            self.send_json({"ok": False, "message": "Payment window closed. Restart checkout or remove this vehicle."}, 409)
            return
        if booking["booking_status"] not in {"PENDING_HOLD", "CONFIRMED"} or booking["payment_status"] == "PAID":
            self.send_json({"ok": False, "message": "This booking does not need a payment right now."}, 400)
            return
        payment_option = "full" if form.get("payment_option") == "full" else "hold"
        if booking["payment_status"] == "HOLD_PAID" and payment_option != "full":
            self.send_json({"ok": False, "message": "The 10% hold is already paid. Pay the remaining balance for hassle-free pickup."}, 400)
            return
        breakdown = booking_price_breakdown(booking)
        checkout_amount = (
            round(float(breakdown["due_at_pickup"]), 2)
            if payment_option == "full" and booking["payment_status"] == "HOLD_PAID"
            else full_payment_total(breakdown["total"])
            if payment_option == "full"
            else round(float(breakdown["booking_hold"]), 2)
        )
        amount_cents = max(50, int(round(checkout_amount * 100)))
        origin = self.public_origin().rstrip("/")
        product_name = (
            "FairFares remaining pickup balance"
            if payment_option == "full" and booking["payment_status"] == "HOLD_PAID"
            else "FairFares full booking payment"
            if payment_option == "full"
            else "FairFares 10% booking hold"
        )
        product_description = (
            f"{row_value(booking, 'car_name')} - {row_value(booking, 'booking_id')} - remaining balance for hassle-free pickup"
            if payment_option == "full" and booking["payment_status"] == "HOLD_PAID"
            else
            f"{row_value(booking, 'car_name')} - {row_value(booking, 'booking_id')} - full payment includes $10 pickup discount"
            if payment_option == "full"
            else f"{row_value(booking, 'car_name')} - {row_value(booking, 'booking_id')}"
        )
        params = {
            "mode": "payment",
            "success_url": f"{origin}/payment/success?session_id={{CHECKOUT_SESSION_ID}}",
            "cancel_url": f"{origin}/payment/cancel",
            "customer_email": row_value(booking, "contact_email") or row_value(user, "email"),
            "client_reference_id": row_value(booking, "booking_id"),
            "line_items[0][quantity]": 1,
            "line_items[0][price_data][currency]": "usd",
            "line_items[0][price_data][unit_amount]": amount_cents,
            "line_items[0][price_data][product_data][name]": product_name,
            "line_items[0][price_data][product_data][description]": product_description,
            "metadata[payment_option]": payment_option,
            "metadata[booking_id]": row_value(booking, "id"),
            "metadata[public_booking_id]": row_value(booking, "booking_id"),
            "metadata[user_id]": row_value(user, "id"),
            "payment_intent_data[metadata][payment_option]": payment_option,
            "payment_intent_data[metadata][booking_id]": row_value(booking, "id"),
            "payment_intent_data[metadata][public_booking_id]": row_value(booking, "booking_id"),
            "payment_intent_data[metadata][user_id]": row_value(user, "id"),
        }
        session, status = stripe_api_request("checkout/sessions", params)
        url = str(session.get("url") or "")
        if not url:
            self.send_json({"ok": False, "message": status}, 502)
            return
        self.send_json({"ok": True, "url": url})

    def create_stripe_identity_session(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Sign in to verify your identity."}, 401)
            return
        booking = get_booking_for_user(user["id"])
        if not booking:
            self.send_json({"ok": False, "message": "Book a vehicle before starting identity verification."}, 404)
            return
        if not booking_customer_tools_unlocked(booking):
            self.send_json(
                {"ok": False, "message": "Pay the 10% hold or full balance before starting pickup verification."},
                403,
            )
            return
        if not stripe_identity_enabled():
            self.send_json({"ok": False, "message": "Stripe Identity is not configured on this server."}, 503)
            return
        existing = latest_identity_verification(int(user["id"]), int(booking["id"]))
        if existing and row_value(existing, "status") == "VERIFIED":
            self.send_json({"ok": True, "verified": True, "message": "Identity is already verified."})
            return
        session, status = resumable_stripe_identity_session(int(user["id"]), int(booking["id"]))
        if session.get("url"):
            self.send_json({"ok": True, "url": session["url"], "message": "Resuming Stripe Identity."})
            return
        origin = self.public_origin().rstrip("/")
        session, status = create_stripe_identity_session_for(user, booking, f"{origin}/manage-booking?identity=return")
        url = str(session.get("url") or "")
        if not url:
            self.send_json({"ok": False, "message": status}, 502)
            return
        save_identity_verification_from_session(session, int(user["id"]), int(booking["id"]))
        self.send_json({"ok": True, "url": url, "message": "Opening Stripe Identity."})

    def create_admin_stripe_identity_session(self) -> None:
        admin = self.require_admin()
        if not admin:
            return
        form = self.read_form()
        try:
            booking_id = int(form.get("booking_id", "0") or 0)
        except ValueError:
            booking_id = 0
        if not booking_id:
            self.send_json({"ok": False, "message": "Booking is required for Stripe Identity."}, 400)
            return
        with db() as con:
            booking = con.execute("SELECT * FROM bookings WHERE id = ?", (booking_id,)).fetchone()
            if not booking:
                self.send_json({"ok": False, "message": "Booking not found."}, 404)
                return
            customer = con.execute("SELECT * FROM users WHERE id = ?", (booking["user_id"],)).fetchone()
            if not customer:
                self.send_json({"ok": False, "message": "Customer not found."}, 404)
                return
        existing = latest_identity_verification(int(customer["id"]), int(booking["id"]))
        if existing and row_value(existing, "status") == "VERIFIED":
            self.send_json({"ok": True, "verified": True, "message": "Identity is already verified."})
            return
        session, status = resumable_stripe_identity_session(int(customer["id"]), int(booking["id"]))
        if session.get("url"):
            self.send_json({"ok": True, "url": session["url"], "message": "Resuming Stripe Identity for pickup verification."})
            return
        origin = self.public_origin().rstrip("/")
        session, status = create_stripe_identity_session_for(customer, booking, f"{origin}/admin/pickup?identity=return")
        url = str(session.get("url") or "")
        if not url:
            self.send_json({"ok": False, "message": status}, 502)
            return
        save_identity_verification_from_session(session, int(customer["id"]), int(booking["id"]))
        self.send_json({"ok": True, "url": url, "message": "Opening Stripe Identity for pickup verification."})

