    def refund_admin_booking_payment(self) -> None:
        user = self.require_admin()
        if not user:
            return
        form = self.read_form()
        reason = (form.get("reason") or "").strip() or "Manual refund requested by staff."
        if not refund_passcode_configured() or not verify_refund_passcode(form.get("refund_passcode", "")):
            self.redirect("/admin/bookings")
            return
        with db() as con:
            booking = con.execute(
                """
                SELECT bookings.*, users.name AS user_name, users.email AS user_email,
                       cars.name AS car_name
                FROM bookings
                JOIN users ON users.id = bookings.user_id
                JOIN cars ON cars.id = bookings.car_id
                WHERE bookings.id = ?
                """,
                (form.get("booking_id"),),
            ).fetchone()
            allowed, _message = booking_refund_allowed(booking)
            if not allowed or not booking:
                self.redirect("/admin/bookings")
                return
            if not is_admin_user(user):
                create_manual_refund_task(con, booking, user, reason)
                self.redirect("/admin/bookings")
                return

        next_payment_status, refund_message = auto_refund_booking_payments(int(row_value(booking, "id")))
        with db() as con:
            con.execute(
                """
                UPDATE bookings
                SET payment_status = ?,
                    cancellation_reason = CASE
                        WHEN cancellation_reason = '' THEN ?
                        ELSE cancellation_reason || ' | ' || ?
                    END
                WHERE id = ?
                """,
                (
                    next_payment_status,
                    f"Manual refund: {refund_message}",
                    f"Manual refund: {refund_message}",
                    row_value(booking, "id"),
                ),
            )
            updated_booking = con.execute(
                """
                SELECT bookings.*, users.name AS user_name, users.email AS user_email,
                       cars.name AS car_name
                FROM bookings
                JOIN users ON users.id = bookings.user_id
                JOIN cars ON cars.id = bookings.car_id
                WHERE bookings.id = ?
                """,
                (row_value(booking, "id"),),
            ).fetchone()
            if next_payment_status != "REFUNDED" and updated_booking:
                create_manual_refund_task(con, updated_booking, user, f"{reason} | Automatic refund result: {refund_message}")
        notify_slack_payment(
            booking,
            f"Manual refund action by {row_value(user, 'name')}: {next_payment_status} - {refund_message}",
            self.public_origin(),
        )
        self.redirect("/admin/bookings")

    def update_admin_booking_status(self) -> None:
        user = self.require_admin()
        if not user:
            return
        form = self.read_form()
        booking_status = form.get("booking_status", "CONFIRMED")
        payment_status = form.get("payment_status", "PAY_AT_PICKUP")
        if booking_status not in {"PENDING_HOLD", "EXPIRED_HOLD", "CONFIRMED", "MODIFIED", "CANCELLATION_REQUESTED", "CANCELLED", "PICKED_UP", "RETURNED"}:
            booking_status = "CONFIRMED"
        if payment_status not in {"HOLD_PENDING", "HOLD_EXPIRED", "HOLD_PAID", "PAID", "PAY_AT_PICKUP", "REFUND_REVIEW", "REFUNDED"}:
            payment_status = "PAY_AT_PICKUP"
        reason = form.get("reason", "")
        if booking_status in {"CONFIRMED", "PICKED_UP", "RETURNED"}:
            reason = ""
        if booking_status == "CANCELLED" and not reason:
            reason = "Cancelled by admin approval."
        with db() as con:
            previous_booking = con.execute(
                """
                SELECT bookings.*, users.name AS user_name, cars.name AS car_name
                FROM bookings
                JOIN users ON users.id = bookings.user_id
                JOIN cars ON cars.id = bookings.car_id
                WHERE bookings.id = ?
                """,
                (form.get("booking_id"),),
            ).fetchone()
        if not previous_booking:
            self.send_error(404, "Booking not found.")
            return
        if booking_status == "PICKED_UP" and not booking_releasable_at_pickup(previous_booking):
            self.send_error(
                409,
                "Pickup blocked: confirm payment and authorize the refundable security deposit first.",
            )
            return
        cancellation_refund_message = ""
        cancellation_deposit_message = ""
        if booking_status == "CANCELLED" and row_value(previous_booking, "booking_status") != "CANCELLED":
            if row_value(previous_booking, "payment_status") in {"PAID", "HOLD_PAID", "REFUND_REVIEW"}:
                payment_status, cancellation_refund_message = auto_refund_booking_payments(
                    int(row_value(previous_booking, "id") or 0)
                )
            deposit_released, cancellation_deposit_message = release_security_deposit_after_cancellation(previous_booking)
            if not deposit_released:
                cancellation_deposit_message = f"Deposit release requires review: {cancellation_deposit_message}"
        with db() as con:
            con.execute(
                """
                UPDATE bookings
                SET booking_status = ?,
                    payment_status = ?,
                    status = ?,
                    cancellation_reason = ?
                WHERE id = ?
                """,
                (booking_status, payment_status, booking_status, reason, form.get("booking_id")),
            )
            if booking_status in {"CANCELLED", "EXPIRED_HOLD"}:
                con.execute(
                    """
                    UPDATE cars
                    SET status = 'AVAILABLE'
                    WHERE id = (SELECT car_id FROM bookings WHERE id = ?)
                    """,
                    (form.get("booking_id"),),
                )
            elif booking_status == "PENDING_HOLD":
                con.execute(
                    """
                    UPDATE cars
                    SET status = 'HOLD'
                    WHERE id = (SELECT car_id FROM bookings WHERE id = ?)
                    """,
                    (form.get("booking_id"),),
                )
            elif booking_status in {"CONFIRMED", "MODIFIED", "PICKED_UP", "CANCELLATION_REQUESTED"}:
                con.execute(
                    """
                    UPDATE cars
                    SET status = 'BOOKED'
                    WHERE id = (SELECT car_id FROM bookings WHERE id = ?)
                    """,
                    (form.get("booking_id"),),
                )
            elif booking_status == "RETURNED":
                con.execute(
                    """
                    UPDATE cars
                    SET status = 'AVAILABLE'
                    WHERE id = (SELECT car_id FROM bookings WHERE id = ?)
                    """,
                    (form.get("booking_id"),),
                )
            updated_booking = con.execute(
                """
                SELECT bookings.*, users.name AS user_name, cars.name AS car_name
                FROM bookings
                JOIN users ON users.id = bookings.user_id
                JOIN cars ON cars.id = bookings.car_id
                WHERE bookings.id = ?
                """,
                (form.get("booking_id"),),
            ).fetchone()
            notify_payment_statuses = {"HOLD_PAID", "PAID", "REFUND_REVIEW", "REFUNDED"}
            if updated_booking and (
                not previous_booking
                or row_value(previous_booking, "booking_status") != booking_status
                or row_value(previous_booking, "payment_status") != payment_status
            ) and (
                payment_status in notify_payment_statuses
                or row_value(previous_booking, "payment_status") in notify_payment_statuses
            ):
                notify_slack_payment(
                    updated_booking,
                    f"Admin set booking {booking_status} / payment {payment_status}. {cancellation_refund_message} {cancellation_deposit_message}",
                    self.public_origin(),
                )
        status_changed = bool(
            updated_booking
            and (
                not previous_booking
                or row_value(previous_booking, "booking_status") != booking_status
                or row_value(previous_booking, "payment_status") != payment_status
            )
        )
        if status_changed:
            status_titles = {
                "CONFIRMED": "Rental booking confirmed",
                "MODIFIED": "Rental modification updated",
                "CANCELLATION_REQUESTED": "Rental cancellation under review",
                "CANCELLED": "Rental booking cancelled",
                "PICKED_UP": "Rental pickup completed",
                "RETURNED": "Rental return completed",
                "EXPIRED_HOLD": "Rental payment window expired",
            }
            send_rental_booking_push(
                updated_booking,
                status_titles.get(booking_status, "Rental booking updated"),
                f"Booking {row_value(updated_booking, 'booking_id')} is now {booking_status.replace('_', ' ').lower()}.",
                f"STATUS_{booking_status}",
            )
        self.redirect("/admin/bookings")

