    def update_content(self) -> None:
        user = self.require_owner_admin()
        if not user:
            return
        form = self.read_form()
        with db() as con:
            for key, value in form.items():
                con.execute("UPDATE site_content SET value = ? WHERE key = ?", (value, key))
        self.redirect("/dashboard")

    def logout(self) -> None:
        header = self.headers.get("Cookie", "")
        jar = cookies.SimpleCookie(header)
        morsel = jar.get(SESSION_COOKIE)
        if morsel:
            with db() as con:
                con.execute("DELETE FROM sessions WHERE token = ?", (morsel.value,))
        self.send_response(303)
        self.send_header("Location", "/")
        secure = "; Secure" if self.headers.get("X-Forwarded-Proto") == "https" or os.environ.get("PUBLIC_BASE_URL", "").startswith("https://") else ""
        self.send_header("Set-Cookie", f"{SESSION_COOKIE}=; Max-Age=0; HttpOnly; SameSite=Lax; Path=/{secure}")
        self.end_headers()

    def api_site(self) -> None:
        payload = {"content": get_content(), "services": [dict(row) for row in get_services()]}
        body = json.dumps(payload, indent=2).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def api_cars(self) -> None:
        public_fields = (
            "id", "name", "brand", "model", "year", "category", "type", "fuel_type",
            "seats", "bags", "doors", "transmission", "daily_price", "badge",
            "features", "location", "image_url", "booked_until_date", "booked_until_time",
        )
        payload = {"cars": [{field: row_value(row, field) for field in public_fields} for row in get_cars()]}
        body = json.dumps(payload, indent=2).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def api_mobile_social_auth(self) -> None:
        payload = self.read_json_body()
        consented, consented_at = consent_values(payload)
        action_key = auth_action_rate_limit_key(self.client_ip(), "mobile-social")
        retry_after = auth_action_retry_after(action_key)
        if retry_after:
            self.send_json(
                {"ok": False, "error": "Too many sign-in attempts. Please wait and try again."},
                429,
                {"Retry-After": str(retry_after)},
            )
            return
        record_auth_action(action_key)
        provider = clean_text_value(payload.get("provider"), 20).lower()
        identity_token = str(payload.get("identityToken") or "").strip()
        submitted_name = " ".join(str(payload.get("name") or "").split())[:120]
        if provider not in {"google", "apple"} or not identity_token or len(identity_token) > 20_000:
            self.send_json({"ok": False, "error": "A supported social sign-in token is required."}, 400)
            return
        try:
            claims = verify_google_identity_token(identity_token) if provider == "google" else verify_apple_identity_token(identity_token)
        except RuntimeError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 503)
            return
        except ValueError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 401)
            return
        subject = clean_text_value(claims.get("sub"), 255)
        email = normalize_email(claims.get("email") or "")
        display_name = submitted_name or clean_text_value(claims.get("name"), 120) or (email.split("@", 1)[0] if email else "FairFares member")
        if not subject:
            self.send_json({"ok": False, "error": "The identity provider did not return an account identifier."}, 401)
            return
        try:
            with db() as con:
                con.execute("DELETE FROM auth_phone_continuations WHERE used_at IS NOT NULL OR datetime(expires_at) <= datetime('now')")
                identity = con.execute(
                    "SELECT user_id FROM auth_identities WHERE provider = ? AND provider_subject = ?",
                    (provider, subject),
                ).fetchone()
                user = con.execute("SELECT * FROM users WHERE id = ?", (int(identity["user_id"]),)).fetchone() if identity else None
                if not user:
                    if not email:
                        self.send_json({"ok": False, "error": "Share your email with the identity provider to create the account."}, 400)
                        return
                    existing = find_user_by_email(con, email)
                    if (not existing or int(row_value(existing, "guest_account") or 0)) and not consented:
                        self.send_json({"ok": False, "error": "Agree to the Terms, Community Guidelines, and acknowledge the Privacy Policy before creating an account."}, 400)
                        return
                    if existing:
                        user_id = int(existing["id"])
                        if int(row_value(existing, "guest_account") or 0):
                            con.execute(
                                "UPDATE users SET name = ?, guest_account = 0, is_verified = 1, verified_at = CURRENT_TIMESTAMP, consented_at = ?, terms_version = ?, privacy_version = ?, community_guidelines_version = ? WHERE id = ?",
                                (display_name, consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION, user_id),
                            )
                    else:
                        con.execute(
                            "INSERT INTO users (name, email, password_hash, is_verified, verified_at, consented_at, terms_version, privacy_version, community_guidelines_version) VALUES (?, ?, ?, 1, CURRENT_TIMESTAMP, ?, ?, ?, ?)",
                            (display_name, email, hash_password(secrets.token_urlsafe(48)), consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION),
                        )
                        user_id = int(con.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
                    con.execute(
                        "INSERT INTO auth_identities (user_id, provider, provider_subject, provider_email) VALUES (?, ?, ?, ?)",
                        (user_id, provider, subject, email),
                    )
                    user = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
                else:
                    user_id = int(user["id"])
                    con.execute(
                        "UPDATE auth_identities SET provider_email = ?, updated_at = CURRENT_TIMESTAMP WHERE provider = ? AND provider_subject = ?",
                        (email, provider, subject),
                    )
                if canonical_e164_phone(row_value(user, "phone")):
                    cleanup_expired_sessions(con)
                    session_token = secrets.token_urlsafe(32)
                    con.execute("INSERT INTO sessions (token, user_id) VALUES (?, ?)", (session_token, user_id))
                    refreshed = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
                    self.send_json({"ok": True, "token": session_token, "user": mobile_user_payload(refreshed)})
                    return
                continuation = secrets.token_urlsafe(32)
                expires_at = (datetime.now(UTC) + timedelta(minutes=SOCIAL_AUTH_CONTINUATION_MINUTES)).strftime("%Y-%m-%d %H:%M:%S")
                con.execute(
                    "INSERT INTO auth_phone_continuations (token_hash, user_id, provider, expires_at) VALUES (?, ?, ?, ?)",
                    (auth_token_hash(continuation), user_id, provider, expires_at),
                )
            self.send_json({
                "ok": True,
                "phoneRequired": True,
                "continuationToken": continuation,
                "user": mobile_user_payload(user),
            })
        except sqlite3.IntegrityError:
            self.send_json({"ok": False, "error": "This social account is already linked to another FairFares account."}, 409)

    def api_mobile_social_phone_complete(self) -> None:
        payload = self.read_json_body()
        continuation = str(payload.get("continuationToken") or "").strip()
        phone = canonical_e164_phone(payload.get("phone"), payload.get("countryCode"))
        if not continuation or not phone:
            self.send_json({"ok": False, "error": "Choose a country code and enter a valid mobile number."}, 400)
            return
        token_hash = auth_token_hash(continuation)
        with db() as con:
            row = con.execute(
                "SELECT * FROM auth_phone_continuations WHERE token_hash = ? AND used_at IS NULL AND datetime(expires_at) > datetime('now')",
                (token_hash,),
            ).fetchone()
            if not row:
                self.send_json({"ok": False, "error": "This sign-in expired. Start social sign-in again."}, 401)
                return
            user_id = int(row["user_id"])
            owner = con.execute("SELECT id FROM users WHERE phone = ? AND id != ? LIMIT 1", (phone, user_id)).fetchone()
            if owner:
                owner_user = con.execute("SELECT email FROM users WHERE id = ?", (int(owner["id"]),)).fetchone()
                self.send_json({
                    "ok": False,
                    "error": "That phone number belongs to another FairFares account.",
                    "emailRecoveryAvailable": True,
                    "recoveryEmailHint": masked_email_hint(row_value(owner_user, "email")),
                }, 409)
                return
            con.execute(
                "UPDATE users SET phone = ?, phone_verified_at = NULL, is_verified = 1, verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP) WHERE id = ?",
                (phone, user_id),
            )
            con.execute("UPDATE auth_phone_continuations SET phone = ?, used_at = CURRENT_TIMESTAMP WHERE token_hash = ?", (phone, token_hash))
            cleanup_expired_sessions(con)
            session_token = secrets.token_urlsafe(32)
            con.execute("INSERT INTO sessions (token, user_id) VALUES (?, ?)", (session_token, user_id))
            user = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
        self.send_json({"ok": True, "token": session_token, "user": mobile_user_payload(user)})

    def api_mobile_social_phone_send(self) -> None:
        payload = self.read_json_body()
        continuation = str(payload.get("continuationToken") or "").strip()
        phone = canonical_e164_phone(payload.get("phone"), payload.get("countryCode"))
        if not continuation or not phone:
            self.send_json({"ok": False, "error": "Choose a country code and enter a valid mobile number."}, 400)
            return
        token_hash = auth_token_hash(continuation)
        with db() as con:
            row = con.execute(
                "SELECT * FROM auth_phone_continuations WHERE token_hash = ? AND used_at IS NULL AND datetime(expires_at) > datetime('now')",
                (token_hash,),
            ).fetchone()
            if not row:
                self.send_json({"ok": False, "error": "This sign-in expired. Start social sign-in again."}, 401)
                return
            owner = con.execute("SELECT id FROM users WHERE phone = ? AND id != ? LIMIT 1", (phone, int(row["user_id"]))).fetchone()
            if owner:
                self.send_json({"ok": False, "error": "That phone number belongs to another FairFares account."}, 409)
                return
            if int(row["send_count"] or 0) >= 5:
                self.send_json({"ok": False, "error": "Too many codes were requested. Start sign-in again later."}, 429)
                return
            last_sent = row_value(row, "last_sent_at")
            if last_sent:
                try:
                    elapsed = (datetime.now(UTC).replace(tzinfo=None) - datetime.fromisoformat(str(last_sent))).total_seconds()
                except ValueError:
                    elapsed = PHONE_OTP_COOLDOWN_SECONDS
                if elapsed < PHONE_OTP_COOLDOWN_SECONDS:
                    self.send_json({"ok": False, "error": f"Wait {max(1, int(PHONE_OTP_COOLDOWN_SECONDS - elapsed))} seconds before requesting another code."}, 429)
                    return
        try:
            result = twilio_verify_request("Verifications", {"To": phone, "Channel": "sms"})
        except RuntimeError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 503)
            return
        except ValueError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 400)
            return
        if result.get("status") not in {"pending", "approved"}:
            self.send_json({"ok": False, "error": "The verification code could not be sent."}, 502)
            return
        with db() as con:
            con.execute(
                "UPDATE auth_phone_continuations SET phone = ?, send_count = send_count + 1, last_sent_at = CURRENT_TIMESTAMP WHERE token_hash = ?",
                (phone, token_hash),
            )
        self.send_json({"ok": True, "message": "Verification code sent."})

    def api_mobile_social_phone_verify(self) -> None:
        payload = self.read_json_body()
        continuation = str(payload.get("continuationToken") or "").strip()
        code = re.sub(r"\D", "", str(payload.get("code") or ""))
        token_hash = auth_token_hash(continuation) if continuation else ""
        with db() as con:
            row = con.execute(
                "SELECT * FROM auth_phone_continuations WHERE token_hash = ? AND used_at IS NULL AND datetime(expires_at) > datetime('now')",
                (token_hash,),
            ).fetchone()
            if not row:
                self.send_json({"ok": False, "error": "This sign-in expired. Start social sign-in again."}, 401)
                return
            if not row_value(row, "phone") or not re.fullmatch(r"\d{4,10}", code):
                self.send_json({"ok": False, "error": "Enter the verification code sent to your phone."}, 400)
                return
            if int(row["verify_attempts"] or 0) >= 8:
                self.send_json({"ok": False, "error": "Too many incorrect codes. Start sign-in again."}, 429)
                return
            con.execute("UPDATE auth_phone_continuations SET verify_attempts = verify_attempts + 1 WHERE token_hash = ?", (token_hash,))
            phone = str(row["phone"])
            user_id = int(row["user_id"])
        try:
            result = twilio_verify_request("VerificationCheck", {"To": phone, "Code": code})
        except RuntimeError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 503)
            return
        except ValueError as exc:
            self.send_json({"ok": False, "error": str(exc)}, 400)
            return
        if result.get("status") != "approved":
            self.send_json({"ok": False, "error": "That verification code is incorrect or expired."}, 400)
            return
        with db() as con:
            owner = con.execute("SELECT id FROM users WHERE phone = ? AND id != ? LIMIT 1", (phone, user_id)).fetchone()
            if owner:
                self.send_json({"ok": False, "error": "That phone number belongs to another FairFares account."}, 409)
                return
            con.execute(
                "UPDATE users SET phone = ?, phone_verified_at = CURRENT_TIMESTAMP, chat_phone_discoverable = 1, is_verified = 1, verified_at = COALESCE(verified_at, CURRENT_TIMESTAMP) WHERE id = ?",
                (phone, user_id),
            )
            con.execute("UPDATE auth_phone_continuations SET used_at = CURRENT_TIMESTAMP WHERE token_hash = ?", (token_hash,))
            cleanup_expired_sessions(con)
            session_token = secrets.token_urlsafe(32)
            con.execute("INSERT INTO sessions (token, user_id) VALUES (?, ?)", (session_token, user_id))
            user = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
        self.send_json({"ok": True, "token": session_token, "user": mobile_user_payload(user)})

    def api_mobile_login(self) -> None:
        payload = self.read_json_body()
        identifier = str(payload.get("identifier") or payload.get("email") or payload.get("phone") or "").strip()
        password = str(payload.get("password") or "")
        rate_key = login_rate_limit_key(self.client_ip(), identifier)
        account_rate_key = login_account_rate_limit_key(identifier)
        retry_after = max(login_retry_after(rate_key), login_retry_after(account_rate_key))
        if retry_after:
            self.send_response(429)
            self.send_header("Retry-After", str(retry_after))
            self.send_header("Content-Type", "application/json; charset=utf-8")
            body = json.dumps({"ok": False, "error": "Too many login attempts. Please wait and try again."}).encode()
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        with db() as con:
            user = find_user_by_login_identifier(con, identifier)
            if not user or len(password) > MAX_PASSWORD_LENGTH or not verify_password(password, row_value(user, "password_hash")):
                record_login_failure(rate_key)
                record_login_failure(account_rate_key)
                log_login_failure(identifier, "mobile_password_mismatch")
                self.send_json({"ok": False, "error": "That email/phone and password did not match."}, 401)
                return
            if not int(row_value(user, "is_verified") or 0):
                token = create_verification(int(row_value(user, "id") or 0), row_value(user, "email"))
                link = self.activation_url(token)
                _outbox_file, delivery_status = send_activation_email(row_value(user, "email"), row_value(user, "name"), link)
                delivery_message = (
                    "Your account is not activated yet. We sent a fresh activation link to your email."
                    if delivery_status.startswith("sent")
                    else "Your account is not activated, and the activation email could not be delivered. Check the address or contact FairFares support."
                )
                self.send_json(
                    {
                        "ok": False,
                        "activationRequired": True,
                        "error": delivery_message,
                    },
                    403,
                )
                return
            clear_login_failures(rate_key)
            clear_login_failures(account_rate_key)
            if password_hash_needs_upgrade(row_value(user, "password_hash")):
                con.execute("UPDATE users SET password_hash = ? WHERE id = ?", (hash_password(password), int(row_value(user, "id") or 0)))
            cleanup_expired_sessions(con)
            token = secrets.token_urlsafe(32)
            con.execute("INSERT INTO sessions (token, user_id) VALUES (?, ?)", (token, int(row_value(user, "id") or 0)))
        self.send_json({"ok": True, "token": token, "user": mobile_user_payload(user)})

    def api_mobile_signup(self) -> None:
        payload = self.read_json_body()
        action_key = auth_action_rate_limit_key(self.client_ip(), "mobile-signup")
        retry_after = auth_action_retry_after(action_key)
        if retry_after:
            self.send_json(
                {"ok": False, "error": "Too many signup attempts. Please wait and try again."},
                429,
                {"Retry-After": str(retry_after)},
            )
            return
        record_auth_action(action_key)
        consented, consented_at = consent_values(payload)
        if not consented:
            self.send_json({"ok": False, "error": "You must agree to the Terms of Service and Community Guidelines and acknowledge the Privacy Policy."}, 400)
            return
        submitted_phone = str(payload.get("phone") or "").strip()
        country_code = str(payload.get("countryCode") or "").strip()
        phone = canonical_e164_phone(submitted_phone, country_code)
        # Keep older released clients working while all new builds send an
        # explicit countryCode and persist a canonical E.164 number.
        password = str(payload.get("password") or "")
        name, email, _validated_phone, validation_error = validate_account_fields(
            payload.get("name"), payload.get("email") or payload.get("identifier"), phone or submitted_phone, password
        )
        phone_discoverable = str(payload.get("phoneDiscoverable", "true")).strip().lower() not in {"0", "false", "no", "off"}
        if validation_error or (country_code and not phone):
            self.send_json(
                {
                    "ok": False,
                    "error": validation_error or "Choose a valid country code and mobile number.",
                },
                400,
            )
            return
        try:
            with db() as con:
                existing_email_user = find_user_by_email(con, email)
                if existing_email_user and not int(row_value(existing_email_user, "guest_account") or 0):
                    self.send_json({"ok": False, "error": "An account with that email already exists."}, 409)
                    return
                stored_phone = phone or submitted_phone
                phone_owner = find_user_by_login_identifier(con, stored_phone)
                if phone_owner and (not existing_email_user or int(phone_owner["id"]) != int(existing_email_user["id"])) and not int(row_value(phone_owner, "guest_account") or 0):
                    self.send_json({"ok": False, "error": "An account with that phone number already exists. Log in or recover that account."}, 409)
                    return
                guest = existing_email_user or (phone_owner if phone_owner and int(row_value(phone_owner, "guest_account") or 0) else None)
                if guest:
                    con.execute(
                        """UPDATE users
                           SET name = ?, email = ?, phone = ?, password_hash = ?, is_verified = 0,
                               guest_account = 0, chat_phone_discoverable = ?, consented_at = ?,
                               terms_version = ?, privacy_version = ?, community_guidelines_version = ?
                           WHERE id = ?""",
                        (name, email, stored_phone, hash_password(password), 1 if phone_discoverable else 0, consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION, int(guest["id"])),
                    )
                    user_id = int(guest["id"])
                else:
                    con.execute(
                        "INSERT INTO users (name, email, phone, password_hash, is_verified, chat_phone_discoverable, consented_at, terms_version, privacy_version, community_guidelines_version) VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?, ?)",
                        (name, email, stored_phone, hash_password(password), 1 if phone_discoverable else 0, consented_at, TERMS_VERSION, PRIVACY_VERSION, COMMUNITY_GUIDELINES_VERSION),
                    )
                    user_id = int(con.execute("SELECT last_insert_rowid() AS id").fetchone()["id"])
                user = con.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
                cleanup_expired_sessions(con)
        except sqlite3.IntegrityError:
            self.send_json({"ok": False, "error": "An account with that email already exists."}, 409)
            return
        token = create_verification(user_id, email)
        link = self.activation_url(token)
        _outbox_file, delivery_status = send_activation_email(email, name, link)
        delivered = delivery_status.startswith("sent")
        self.send_json(
            {
                "ok": True,
                "activationRequired": True,
                "token": "",
                "user": mobile_user_payload(user),
                "message": (
                    "Account created. We sent an activation link to your email."
                    if delivered
                    else "Account created, but the activation email could not be delivered. Check the address or contact FairFares support."
                ),
            },
            201,
        )

    def api_mobile_logout(self) -> None:
        auth_header = (self.headers.get("Authorization") or "").strip()
        token = auth_header.split(" ", 1)[1].strip() if auth_header.lower().startswith("bearer ") else ""
        if token:
            with db() as con:
                con.execute("DELETE FROM sessions WHERE token = ?", (token,))
        self.send_json({"ok": True})

    def api_mobile_account_deletion_status(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "error": "Login is required."}, 401)
            return
        with db() as con:
            row = con.execute("SELECT * FROM account_deletion_requests WHERE user_id = ? ORDER BY id DESC LIMIT 1", (int(user["id"]),)).fetchone()
        self.send_json({"ok": True, "request": account_deletion_payload(row)})

    def api_mobile_request_account_deletion(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "error": "Login is required to request account deletion."}, 401)
            return
        payload = self.read_json_body()
        if str(payload.get("confirmation") or "").strip().upper() != "DELETE":
            self.send_json({"ok": False, "error": "Type DELETE exactly to confirm account deletion."}, 400)
            return
        request = create_account_deletion_request(int(user["id"]), str(row_value(user, "email") or ""), "MOBILE")
        self.send_json({"ok": True, "message": "Your account deletion request was received.", "request": request}, 202)

    def api_mobile_push_token(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "error": "Login is required to register notifications."}, 401)
            return
        payload = self.read_json_body() if "application/json" in (self.headers.get("Content-Type") or "").lower() else self.read_form()
        token = clean_text_value(payload.get("token"), 300)
        platform = clean_text_value(payload.get("platform"), 30).lower()
        device_label = clean_text_value(payload.get("deviceLabel") or payload.get("device_label"), 120)
        device_id = re.sub(r"[^A-Za-z0-9._-]", "", clean_text_value(payload.get("deviceId") or payload.get("device_id"), 100))
        enabled = str(payload.get("enabled", "1")).strip().lower() not in {"0", "false", "no", "off"}
        if not (token.startswith("ExponentPushToken[") or token.startswith("ExpoPushToken[")):
            self.send_json({"ok": False, "error": "A valid Expo push token is required."}, 400)
            return
        current_user_id = int(user["id"])
        with _PUSH_TOKEN_REGISTRATION_LOCK:
            with db() as con:
                existing = con.execute(
                    """
                    SELECT tokens.user_id, tokens.platform, tokens.device_label, tokens.device_id, tokens.enabled,
                           preferences.chitthi_enabled, preferences.carpool_enabled, preferences.rentals_enabled,
                           preferences.housing_enabled, preferences.support_enabled, preferences.marketing_enabled
                    FROM mobile_push_tokens tokens
                    LEFT JOIN mobile_notification_preferences preferences ON preferences.user_id = tokens.user_id
                    WHERE tokens.token = ? LIMIT 1
                    """,
                    (token,),
                ).fetchone()
                already_current = bool(
                    existing
                    and int(row_value(existing, "user_id") or 0) == current_user_id
                    and str(row_value(existing, "platform") or "") == platform
                    and str(row_value(existing, "device_label") or "") == device_label
                    and str(row_value(existing, "device_id") or "") == device_id
                    and bool(int(row_value(existing, "enabled") or 0)) == enabled
                    and (not enabled or all(bool(int(row_value(existing, f"{category}_enabled") or 0)) for category in ("chitthi", "carpool", "rentals", "housing", "support", "marketing")))
                )
                if not already_current:
                    con.execute(
                        """
                        INSERT INTO mobile_push_tokens (user_id, token, platform, device_label, device_id, enabled)
                        VALUES (?, ?, ?, ?, ?, ?)
                        ON CONFLICT(token) DO UPDATE SET
                            user_id = excluded.user_id,
                            platform = excluded.platform,
                            device_label = excluded.device_label,
                            device_id = excluded.device_id,
                            enabled = excluded.enabled,
                            updated_at = CURRENT_TIMESTAMP,
                            last_seen_at = CURRENT_TIMESTAMP
                        """,
                        (current_user_id, token, platform, device_label, device_id, 1 if enabled else 0),
                    )
                    if enabled:
                        con.execute(
                            """
                            INSERT INTO mobile_notification_preferences
                            (user_id, chitthi_enabled, carpool_enabled, rentals_enabled, housing_enabled, support_enabled, marketing_enabled, updated_at)
                            VALUES (?, 1, 1, 1, 1, 1, 1, CURRENT_TIMESTAMP)
                            ON CONFLICT(user_id) DO UPDATE SET
                                chitthi_enabled = 1,
                                carpool_enabled = 1,
                                rentals_enabled = 1,
                                housing_enabled = 1,
                                support_enabled = 1,
                                marketing_enabled = 1,
                                updated_at = CURRENT_TIMESTAMP
                            """,
                            (current_user_id,),
                        )
        response = {"ok": True, "enabled": enabled}
        if already_current:
            response["unchanged"] = True
        self.send_json(response)

    def api_mobile_notification_preferences(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Login is required."}, 401)
            return
        with db() as con:
            row = con.execute("SELECT * FROM mobile_notification_preferences WHERE user_id = ?", (int(row_value(user, "id") or 0),)).fetchone()
        self.send_json({"ok": True, "preferences": notification_preferences_payload(row)})

    def api_mobile_update_notification_preferences(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "message": "Login is required."}, 401)
            return
        payload = self.read_json_body()
        current_user_id = int(row_value(user, "id") or 0)
        values = {key: 1 if bool(payload.get(key, True)) else 0 for key in ("chitthi", "carpool", "rentals", "housing", "support")}
        values["marketing"] = 1 if bool(payload.get("marketing", False)) else 0
        with db() as con:
            con.execute(
                """
                INSERT INTO mobile_notification_preferences
                (user_id, chitthi_enabled, carpool_enabled, rentals_enabled, housing_enabled, support_enabled, marketing_enabled, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                ON CONFLICT(user_id) DO UPDATE SET
                    chitthi_enabled = excluded.chitthi_enabled,
                    carpool_enabled = excluded.carpool_enabled,
                    rentals_enabled = excluded.rentals_enabled,
                    housing_enabled = excluded.housing_enabled,
                    support_enabled = excluded.support_enabled,
                    marketing_enabled = excluded.marketing_enabled,
                    updated_at = CURRENT_TIMESTAMP
                """,
                (current_user_id, values["chitthi"], values["carpool"], values["rentals"], values["housing"], values["support"], values["marketing"]),
            )
            row = con.execute("SELECT * FROM mobile_notification_preferences WHERE user_id = ?", (current_user_id,)).fetchone()
        self.send_json({"ok": True, "preferences": notification_preferences_payload(row)})

    def api_mobile_update_profile(self) -> None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "login_required": True, "error": "Sign in to update your profile."}, 401)
            return
        payload = self.read_json_body()
        name = clean_text_value(payload.get("name") if "name" in payload else row_value(user, "name"), 120)
        email = normalize_email(payload.get("email") if "email" in payload else row_value(user, "email"))
        phone = clean_text_value(payload.get("phone") if "phone" in payload else row_value(user, "phone"), 40)
        date_of_birth = clean_text_value(payload.get("dateOfBirth") if "dateOfBirth" in payload else row_value(user, "date_of_birth"), 10)
        clean_phone = normalize_phone(phone)
        current_password = str(payload.get("currentPassword") or "")
        current_email = normalize_email(row_value(user, "email"))
        current_phone = clean_text_value(row_value(user, "phone"), 40)
        email_changed = email != current_email
        phone_changed = normalize_phone(phone) != normalize_phone(current_phone)
        if not name:
            self.send_json({"ok": False, "error": "Name is required."}, 400)
            return
        if not valid_contact_email(email):
            self.send_json({"ok": False, "error": "Use a valid email address."}, 400)
            return
        if len(clean_phone) < 7:
            self.send_json({"ok": False, "error": "Use a valid phone number."}, 400)
            return
        if date_of_birth:
            try:
                birthday = datetime.strptime(date_of_birth, "%Y-%m-%d").date()
            except ValueError:
                self.send_json({"ok": False, "error": "Use a valid birthday."}, 400)
                return
            today = date.today()
            if birthday > today or birthday.year < today.year - 120:
                self.send_json({"ok": False, "error": "Use a valid birthday."}, 400)
                return
        if (email_changed or phone_changed) and not verify_password(current_password, row_value(user, "password_hash")):
            self.send_json({"ok": False, "error": "Enter your current password to change email or phone."}, 403)
            return
        photo = None
        if "profilePhoto" in payload or "profilePhotoUrl" in payload:
            photo = str(payload.get("profilePhoto") or payload.get("profilePhotoUrl") or "").strip()
            if photo.startswith("data:image/svg xml"):
                photo = photo.replace("data:image/svg xml", "data:image/svg+xml", 1)
            if photo:
                if photo.startswith("data:image/"):
                    if ";base64," not in photo or len(photo) > MAX_PROFILE_PHOTO_DATA_URL_LENGTH:
                        self.send_json({"ok": False, "error": "Use a smaller JPG, PNG, or WebP profile image."}, 400)
                        return
                    mime_type = photo.split(";", 1)[0].replace("data:", "", 1).lower()
                    if mime_type not in ALLOWED_HOUSING_IMAGE_MIME_TYPES:
                        self.send_json({"ok": False, "error": "Use a JPG, PNG, WebP, or GIF profile image."}, 400)
                        return
                    photo = save_data_url_payload_locally(
                        folder_name="profiles",
                        data_url=photo,
                        fallback_name=f"profile-{row_value(user, 'id') or uuid.uuid4().hex}",
                        allowed_mime_types=ALLOWED_HOUSING_IMAGE_MIME_TYPES,
                        max_bytes=MAX_HOUSING_IMAGE_BYTES,
                    )
                    if not photo:
                        self.send_json({"ok": False, "error": "Use a smaller JPG, PNG, or WebP profile image."}, 400)
                        return
                elif not (
                    photo.startswith("local://uploads/")
                    or photo.startswith("/uploads/")
                    or photo.startswith("https://")
                    or photo.startswith("http://")
                ):
                    self.send_json({"ok": False, "error": "Use a JPG, PNG, WebP, or GIF profile image."}, 400)
                    return
        with db() as con:
            existing = find_user_by_email(con, email)
            if existing and int(row_value(existing, "id") or 0) != int(row_value(user, "id") or 0):
                self.send_json({"ok": False, "error": "That email is already used by another account."}, 409)
                return
            verified_value = 0 if email_changed else int(row_value(user, "is_verified") or 0)
            if photo is None:
                con.execute(
                    "UPDATE users SET name = ?, email = ?, phone = ?, date_of_birth = ?, is_verified = ? WHERE id = ?",
                    (name, email, phone, date_of_birth or None, verified_value, user["id"]),
                )
            else:
                con.execute(
                    "UPDATE users SET name = ?, email = ?, phone = ?, date_of_birth = ?, is_verified = ?, profile_photo_url = ? WHERE id = ?",
                    (name, email, phone, date_of_birth or None, verified_value, photo, user["id"]),
                )
            if email_changed:
                con.execute("DELETE FROM sessions WHERE user_id = ?", (user["id"],))
            updated = con.execute("SELECT * FROM users WHERE id = ?", (user["id"],)).fetchone()
        activation_link = ""
        if email_changed:
            token = create_verification(int(row_value(user, "id") or 0), email)
            activation_link = self.activation_url(token)
            send_activation_email(email, name, activation_link)
        self.send_json(
            {
                "ok": True,
                "user": mobile_user_payload(updated),
                "activationRequired": email_changed,
                "activationLink": activation_link,
                "message": "Profile updated. Please activate your new email before logging in again." if email_changed else "Profile updated.",
            }
        )

    def api_mobile_bootstrap(self, parsed: urllib.parse.ParseResult) -> None:
        user = self.current_user()
        auth_header = (self.headers.get("Authorization") or "").strip()
        if auth_header.lower().startswith("bearer ") and not user:
            self.send_json(
                {
                    "ok": False,
                    "login_required": True,
                    "error": "Your FairFares session has expired. Please log in again.",
                },
                401,
            )
            return
        params = urllib.parse.parse_qs(parsed.query)
        city = (params.get("city", ["Denver, CO"])[0] or "").strip()
        area = (params.get("area", [""])[0] or "").strip()
        metro_context = accommodation_metro_context(city if "Metro" in city else "", area or city)
        user_id = int(row_value(user, "id") or 0) if user else 0
        chats = get_chat_conversations_for_user(user_id) if user_id else []
        housing_posts = mobile_housing_posts(city=city, area=area, limit=12)
        self.send_json(
            {
                "ok": True,
                "user": mobile_user_payload(user),
                "location": {
                    "city": city or "Denver, CO",
                    "selected": metro_context.get("selected_location") or city or "Denver, CO",
                    "suggested": metro_context.get("suggested_location") or "",
                },
                "housing": housing_posts,
                "communities": get_chat_communities_for_user(user_id if user_id else None, city),
                "chat": {
                    "unreadCount": sum(int(item.get("unread") or 0) for item in chats),
                    "conversations": chats[:10],
                },
                "dashboard": {
                    "housingPosts": len(get_accommodation_posts_for_user(user_id)) if user_id else 0,
                    "messages": sum(int(item.get("unread") or 0) for item in chats),
                },
                "hasSubmittedHousingExperience": has_submitted_housing_experience(user_id),
                "testimonials": get_mobile_housing_testimonials(city=city),
            }
        )

    def require_mobile_admin(self) -> sqlite3.Row | None:
        user = self.current_user()
        if not user:
            self.send_json({"ok": False, "error": "Staff login required."}, 401)
            return None
        if not int(row_value(user, "is_admin") or 0):
            self.send_json({"ok": False, "error": "FairFares staff access required."}, 403)
            return None
        return user

    def api_mobile_admin_pickups(self) -> None:
        if not self.require_mobile_admin():
            return
        pickups = []
        for row in get_admin_bookings():
            if not booking_ready_for_pickup(row):
                continue
            pickups.append(
                {
                    "id": int(row_value(row, "id") or 0),
                    "bookingId": row_value(row, "booking_id"),
                    "customerName": row_value(row, "user_name"),
                    "customerEmail": row_value(row, "user_email"),
                    "carName": row_value(row, "car_name"),
                    "pickupDate": row_value(row, "pickup_date"),
                    "pickupTime": row_value(row, "pickup_time"),
                    "pickupLocation": row_value(row, "pickup_location"),
                    "bookingStatus": row_value(row, "booking_status"),
                    "paymentStatus": row_value(row, "payment_status"),
                    "depositStatus": row_value(row, "security_deposit_status") or "NOT_AUTHORIZED",
                    "depositAmount": float(row_value(row, "security_deposit_amount") or SECURITY_DEPOSIT_AMOUNT),
                }
            )
        self.send_json(
            {
                "ok": True,
                "pickups": pickups,
                "deposit": {
                    "configured": bool(stripe_secret_key() and stripe_webhook_secret()),
                    "amount": SECURITY_DEPOSIT_AMOUNT,
                },
            }
        )

    def api_mobile_security_deposit_checkout(self) -> None:
        admin = self.require_mobile_admin()
        if not admin:
            return
        payload = self.read_json_body()
        try:
            booking_id = int(payload.get("bookingId") or 0)
        except (TypeError, ValueError):
            booking_id = 0
        booking = get_booking_by_id(booking_id) if booking_id else None
        if not booking:
            self.send_json({"ok": False, "error": "Booking not found."}, 404)
            return
        if not booking_ready_for_pickup(booking):
            self.send_json({"ok": False, "error": "Only paid, confirmed bookings can authorize a pickup deposit."}, 409)
            return
        session, status = create_security_deposit_checkout_session(booking, admin, self.public_origin())
        checkout_url = str(session.get("url") or "")
        if status != "ok" or not checkout_url:
            self.send_json({"ok": False, "error": status}, 502)
            return
        self.send_json(
            {
                "ok": True,
                "bookingId": booking_id,
                "url": checkout_url,
                "amount": SECURITY_DEPOSIT_AMOUNT,
            }
        )

